    local function b64dec(s)
        local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local map = {}
        for i = 1, 64 do map[A:byte(i)] = i - 1 end
        local out, n = {}, 0
        local bits, nb = 0, 0
        for i = 1, #s do
            local v = map[s:byte(i)]
            if v then
                bits = bits * 64 + v; nb = nb + 6
                if nb >= 8 then
                    nb = nb - 8
                    local p = 2 ^ nb
                    local byte = math.floor(bits / p)
                    bits = bits - byte * p
                    n = n + 1; out[n] = string.char(byte)
                end
            end
        end
        return table.concat(out)
    end
    Core.b64dec = b64dec
