local K = light and Color3.new(0, 0, 0) or W
hi = hi or acc:Lerp(W, 0.28)
return {Accent = acc, AccentHi = hi, Bg = bg,
Panel = bg:Lerp(K, 0.045):Lerp(acc, 0.035), PanelHi = bg:Lerp(K, 0.08):Lerp(acc, 0.05),
Element = bg:Lerp(K, 0.09):Lerp(acc, 0.07), ElementHi = bg:Lerp(K, 0.14):Lerp(acc, 0.11),
Border = bg:Lerp(K, 0.12):Lerp(acc, 0.36), Text = txt, Sub = txt:Lerp(bg, 0.3), Dim = txt:Lerp(bg, 0.55)}
end
