function Anim.lift(b, hov, down)
if b:GetAttribute("PXW") then return end
hov = 1; down = 1
b:SetAttribute("PXW", true)
local s = make("UIScale", {Name = "PXB"}, b)
local over = false
b.MouseEnter:Connect(function() over = true; Anim.tw(s, 0.3, {Scale = hov}, Enum.EasingStyle.Quad) end)
b.MouseLeave:Connect(function() over = false; Anim.tw(s, 0.3, {Scale = 1}, Enum.EasingStyle.Quad) end)
b.MouseButton1Down:Connect(function() Anim.tw(s, 0.08, {Scale = down}, Enum.EasingStyle.Quad) end)
b.MouseButton1Up:Connect(function() Anim.tw(s, 0.35, {Scale = over and hov or 1}, Enum.EasingStyle.Quad) end)
return s
end
function Anim.hook(b)
if not b:IsA("TextButton") or b:GetAttribute("PXW") then return end
if b.BackgroundTransparency < 1 then
local sz = b.Size
if sz.Y.Scale == 0 and sz.Y.Offset <= 44 and (sz.X.Scale > 0 or sz.X.Offset <= 240) then
Anim.lift(b, sz.X.Scale > 0 and 1.02 or 1.05, 0.94)
end
return
end
local p = b.Parent
local s = p and p:FindFirstChild("PXS")
if not s then return end
b:SetAttribute("PXW", true)
local over = false
b.MouseEnter:Connect(function() over = true; Anim.tw(s, 0.25, {Scale = 1}, Enum.EasingStyle.Quad) end)
b.MouseLeave:Connect(function() over = false; Anim.tw(s, 0.3, {Scale = 1}, Enum.EasingStyle.Quad) end)
b.MouseButton1Down:Connect(function() Anim.tw(s, 0.07, {Scale = 1}, Enum.EasingStyle.Quad) end)
