function Anim.universal(root, skipRoot)
    local budget, ready = 0, false
    track(RunService.Heartbeat:Connect(function() budget = 20 end))
    local function hook(d)
        if d:GetAttribute("PXU") then return end
        if d:IsA("TextBox") then
            d:SetAttribute("PXU", true)
            local st = d:FindFirstChildOfClass("UIStroke")
            if st then
                d.Focused:Connect(function() Anim.tw(st, 0.2, {Color = T.AccentHi, Thickness = 2, Transparency = 0.1}, Enum.EasingStyle.Quad) end)
                d.FocusLost:Connect(function() Anim.tw(st, 0.3, {Color = T.Border, Thickness = 1, Transparency = 0.4}, Enum.EasingStyle.Quad) end)
            end
        elseif d:IsA("TextButton") or d:IsA("ImageButton") then
            d:SetAttribute("PXU", true)
            if d:GetAttribute("PXW") or d:FindFirstChildOfClass("UIScale") then return end
            if d:IsA("TextButton") and d.BackgroundTransparency >= 1 and d.Text == "" then return end
            local big = d.Size.X.Scale > 0 or d.Size.X.Offset > 240
            local hov, dn = 1, 1
            local sc = Instance.new("UIScale"); sc.Name = "PXU"; sc.Parent = d
            local over = false
            d.MouseEnter:Connect(function() over = true; Anim.tw(sc, 0.25, {Scale = hov}, Enum.EasingStyle.Quad) end)
            d.MouseLeave:Connect(function() over = false; Anim.tw(sc, 0.3, {Scale = 1}, Enum.EasingStyle.Quad) end)
            d.MouseButton1Down:Connect(function() Anim.tw(sc, 0.08, {Scale = dn}, Enum.EasingStyle.Quad) end)
            d.MouseButton1Up:Connect(function() Anim.tw(sc, 0.3, {Scale = over and hov or 1}, Enum.EasingStyle.Quad) end)
        elseif d:IsA("ScrollingFrame") then
            d:SetAttribute("PXU", true)
            local tok = 0
            d.ScrollBarImageTransparency = 0.65
            d:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
                tok = tok + (1); local my = tok
                Anim.tw(d, 0.12, {ScrollBarImageTransparency = 0}, Enum.EasingStyle.Quad)
                task.delay(0.9, function() if tok == my and d.Parent then Anim.tw(d, 0.5, {ScrollBarImageTransparency = 0.65}, Enum.EasingStyle.Sine) end end)
            end)
        end
    end
    for _, d in ipairs(root:GetDescendants()) do pcall(hook, d) end
    track(root.DescendantAdded:Connect(function(d) task.defer(function() pcall(hook, d) end) end))
    task.delay(1, function() ready = true end)
end
function Anim.extra(root)
    local function hook(d)
        if d:GetAttribute("PXE") then return end
        if not (d:IsA("TextButton") or d:IsA("ImageButton")) then return end
        d:SetAttribute("PXE", true)
        local st = d:FindFirstChildOfClass("UIStroke")
        if st and st.Name ~= "SubSel" then
            local c0, th0 = st.Color, st.Thickness
            d.MouseEnter:Connect(function() Anim.tw(st, 0.2, {Color = T.AccentHi, Thickness = th0 + 0.8}, Enum.EasingStyle.Quad) end)
            d.MouseLeave:Connect(function() Anim.tw(st, 0.35, {Color = c0, Thickness = th0}, Enum.EasingStyle.Sine) end)
        end
        if d:IsA("TextButton") and d.Text ~= "" then
            local t0 = d.TextTransparency
            d.MouseButton1Down:Connect(function() Anim.tw(d, 0.06, {TextTransparency = math.min(1, t0 + 0.35)}, Enum.EasingStyle.Quad) end)
            d.MouseButton1Up:Connect(function() Anim.tw(d, 0.25, {TextTransparency = t0}, Enum.EasingStyle.Quad) end)
        end
        d.MouseButton1Click:Connect(function()
            local sz = d.AbsoluteSize
            if sz.X < 24 or sz.Y < 18 then return end
            local rp = Instance.new("Frame")
            rp.BackgroundTransparency = 1; rp.BorderSizePixel = 0; rp.Active = false
            local pl, pr, pt, pb = 0, 0, 0, 0
            local pad = d:FindFirstChildOfClass("UIPadding")
            if pad then pl, pr, pt, pb = pad.PaddingLeft.Offset, pad.PaddingRight.Offset, pad.PaddingTop.Offset, pad.PaddingBottom.Offset end
            rp.AnchorPoint = Vector2.new(0.5, 0.5); rp.Position = UDim2.new(0.5, (pr - pl) / 2, 0.5, (pb - pt) / 2)
            rp.Size = UDim2.new(1, pl + pr, 1, pt + pb); rp.ZIndex = d.ZIndex + 1
            local dc = d:FindFirstChildOfClass("UICorner")
            Instance.new("UICorner", rp).CornerRadius = dc and dc.CornerRadius or UDim.new(0, 8)
            local rs = Instance.new("UIStroke"); rs.Color = T.AccentHi; rs.Thickness = 2; rs.Transparency = 0.2; rs.Parent = rp
            rp.Parent = d
            Anim.tw(rp, 0.5, {Size = UDim2.new(1.12, pl + pr + 6, 1.45, pt + pb + 6)}, Enum.EasingStyle.Quint)
            Anim.tw(rs, 0.45, {Transparency = 1, Thickness = 0.5}, Enum.EasingStyle.Quad)
            task.delay(0.5, function() pcall(function() rp:Destroy() end) end)
        end)
    end
    for _, d in ipairs(root:GetDescendants()) do pcall(hook, d) end
    track(root.DescendantAdded:Connect(function(d) task.defer(function() pcall(hook, d) end) end))
end
