PERM.shine = function()
local objs, bands = {}, {}
local function band(w, peak, off, speed, rot)
local b = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Rotation = rot, Size = UDim2.fromOffset(w, WIN_H * 2.4), Position = UDim2.fromOffset(-300, WIN_H / 2), ZIndex = 25, Active = false, Visible = false}, shineOv)
make("UIGradient", {Name = "NoTheme", Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, peak), NumberSequenceKeypoint.new(1, 1)})}, b)
objs[#objs + 1] = b; bands[#bands + 1] = {b = b, off = off, speed = speed}
end
band(280, 0.9, 0, 0.30, 22)
band(70, 0.8, 0.06, 0.30, 22)
band(150, 0.93, 0.85, 0.22, 22)
return objs, function(t, dt)
for _, q in ipairs(bands) do
