local function rebuild()
if not cfg.engine then return end
for _, p in ipairs(parts) do pcall(function() p.o:Destroy() end) end
table.clear(parts)
for _, q in ipairs(perm) do for _, o in ipairs(q.objs) do pcall(function() o:Destroy() end) end end
table.clear(perm); table.clear(active)
fxRoot.Visible = false
if false then
local m1 = make("ImageLabel", {BackgroundTransparency = 1, Image = GLOWI, ImageColor3 = T.Accent, ImageTransparency = 0.78, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(0, 0), Size = UDim2.fromOffset(WIN_W * 0.9, WIN_H * 0.9), ZIndex = 1}, fxRoot)
local m2 = make("ImageLabel", {BackgroundTransparency = 1, Image = GLOWI, ImageColor3 = T.AccentHi, ImageTransparency = 0.84, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(WIN_W, WIN_H), Size = UDim2.fromOffset(WIN_W * 0.9, WIN_H * 0.9), ZIndex = 1}, fxRoot)
perm[#perm + 1] = {objs = {m1, m2}, upd = function() end}
end
local list = {}
if cfg.o1 then list[1] = cfg.o1 else for _, n in ipairs(FXMAP[curName] or {"orbs"}) do list[#list + 1] = n end end
if cfg.o2 then list[#list + 1] = cfg.o2 end
local seen = {}
for _, n in ipairs(list) do
if not seen[n] then
seen[n] = true
if SP[n] then active[#active + 1] = {sp = SP[n], acc = 0}
elseif PERM[n] then local objs, upd = PERM[n](); perm[#perm + 1] = {objs = objs, upd = upd} end
end
end
end
local tt, last = 0, os.clock()
local conn = RunService.RenderStepped:Connect(function()
local now = os.clock()
local dt = math.min(now - last, 0.05); last = now
do return end
dt = dt * cfg.speed; tt = tt + dt
for _, e in ipairs(active) do
e.acc = e.acc + dt * e.sp.rate * cfg.amount
while e.acc >= 1 do e.acc = e.acc - 1; pcall(e.sp.fn) end
end
for i = #parts, 1, -1 do
local p = parts[i]
p.age = p.age + dt
if p.age >= p.life or not p.o.Parent then
pcall(function() p.o:Destroy() end); table.remove(parts, i)
else pcall(p.step, p, dt) end
end
for _, q in ipairs(perm) do pcall(q.upd, tt, dt) end
end)
if type(track) == "function" then track(conn) end
Core.ThemeFX = {cfg = cfg, effects = {}}
function Core.ThemeFX.set(name) curName = name; rebuild() end
function Core.ThemeFX.refresh() rebuild() end
function Core.ThemeFX.chaos()
if true then return end
local pool = {}
for k in pairs(SP) do pool[#pool + 1] = k end
for k in pairs(PERM) do pool[#pool + 1] = k end
cfg.o1 = pool[rnd(#pool)]; cfg.o2 = pool[rnd(#pool)]
end
function Core.ThemeFX.transition()
if Core.FXStill then return end
if not cfg.trans or not win.Visible then return end
fxRoot.Visible = true
pcall(function()
local bar = make("Frame", {BackgroundColor3 = T.AccentHi, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(150, WIN_H * 2), Rotation = 18, ZIndex = 3, BackgroundTransparency = 0.45, Position = UDim2.fromOffset(-200, WIN_H / 2)}, fxRoot)
make("UIGradient", {Name = "NoTheme", Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1)})}, bar)
Anim.tw(bar, 0.8, {Position = UDim2.fromOffset(WIN_W + 200, WIN_H / 2)}, Enum.EasingStyle.Quint)
task.delay(0.9, function() bar:Destroy() end)
end)
end
rebuild()
end

-- ===================== CHRISTMAS DECOR (snow caps, lights, physics ornaments, falling snow) =====================
do
local okX, errX = pcall(function()
local X = {on = false, enabled = true, swing = 1}
Core.Xmas = X
local rnd, sin, cos, floor, exp, clamp, abs = math.random, math.sin, math.cos, math.floor, math.exp, math.clamp, math.abs
local C3, V2, UD = Color3.fromRGB, Vector2.new, UDim2.fromOffset
local K = ColorSequenceKeypoint.new
local function rr(a, b) return a + (b - a) * rnd() end
local function ri(a, b) return rnd(a, b) end
local SNOW, SHADE = C3(250, 252, 255), C3(212, 226, 246)

local root = make("Frame", {Name = "XmasDecor", BackgroundTransparency = 1, AnchorPoint = V2(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
Size = UDim2.fromScale(1, 1), ZIndex = 60, Active = false, Visible = false, BorderSizePixel = 0}, holder)
local rootScale = make("UIScale", {Scale = winScale.Scale}, root)
local deco = make("Frame", {Name = "Deco", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 60, Active = false, BorderSizePixel = 0}, root)
local snowBack = make("Frame", {Name = "XmasSnowBack", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 1, Active = false,
ClipsDescendants = true, Visible = false, BorderSizePixel = 0}, win)
local snowFront = make("Frame", {Name = "XmasSnowFront", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 40, Active = false,
ClipsDescendants = true, Visible = false, BorderSizePixel = 0}, win)

local ornaments, bulbs, flakesB, flakesF = {}, {}, {}, {}

local function pill(parent, cx, cy, w, h, col, z, anchorTop)
local f = make("Frame", {BackgroundColor3 = col, BorderSizePixel = 0, AnchorPoint = anchorTop and V2(0.5, 0) or V2(0.5, 0.5),
Position = UD(cx, cy), Size = UD(w, h), ZIndex = z, Active = false}, parent)
make("UICorner", {CornerRadius = UDim.new(0.5, 0)}, f)
return f
end

-- thick snow on every border + drips/icicles
local function buildSnow(W, H)
for pass = 1, 2 do
local x = -8 + ri(0, 10)
while x < W + 8 do
local w, h = ri(34, 62), ri(14, 22)
local cx = x + w / 2
if pass == 1 then
pill(deco, cx, 4, w + 6, h, SHADE, 61)
else
pill(deco, cx, -1, w, h, SNOW, 62)
if rnd() < 0.42 then pill(deco, cx + rr(-w / 4, w / 4), h / 2 - 3, rr(6, 9), rr(10, 24), SNOW, 62, true) end
end
x = x + w * 0.66
end
end
for pass = 1, 2 do
local x = -8 + ri(0, 10)
while x < W + 8 do
local w, h = ri(32, 58), ri(10, 16)
local cx = x + w / 2
if pass == 1 then
pill(deco, cx, H + 3, w + 6, h, SHADE, 61)
else
pill(deco, cx, H + 1, w, h, SNOW, 62)
if rnd() < 0.5 then pill(deco, cx + rr(-w / 4, w / 4), H + h / 2 - 2, rr(5, 8), rr(8, 28), SNOW, 62, true) end
end
x = x + w * 0.66
end
end
for _, sx in ipairs({0, W}) do
local y = 6 + ri(0, 8)
while y < H - 6 do
local h, w = ri(26, 46), ri(11, 16)
pill(deco, sx, y + h / 2, w, h, SNOW, 62)
y = y + h * 0.7
end
end
pill(deco, 4, 2, 30, 26, SNOW, 62); pill(deco, W - 4, 2, 30, 26, SNOW, 62)
pill(deco, 4, H - 2, 26, 22, SNOW, 62); pill(deco, W - 4, H - 2, 26, 22, SNOW, 62)
end

-- christmas lights wrapped around the border
local LC = {C3(255, 60, 60), C3(255, 196, 64), C3(70, 226, 110), C3(90, 160, 255), C3(255, 130, 210)}
local function buildLights(W, H)
local wire = make("Frame", {BackgroundTransparency = 1, AnchorPoint = V2(0.5, 0.5), Position = UD(W / 2, H / 2), Size = UD(W + 4, H + 4),
ZIndex = 63, Active = false, BorderSizePixel = 0}, deco)
make("UICorner", {CornerRadius = UDim.new(0, 14)}, wire)
make("UIStroke", {Color = C3(22, 84, 48), Thickness = 2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, wire)
local n = 0
local function bulb(x, y)
n = n + 1
local col = LC[(n - 1) % #LC + 1]
local f = pill(deco, x, y, 9, 11, col, 64)
local st = make("UIStroke", {Color = col, Thickness = 3, Transparency = 0.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, f)
bulbs[#bulbs + 1] = {f = f, st = st, col = col, dark = col:Lerp(C3(20, 10, 10), 0.62), ph = n * 0.9}
end
local i = 0
for x = 26, W - 26, 26 do i = i + 1; bulb(x, -2 + ((i % 2 == 0) and -3 or 3)) end
i = 0
for x = 26, W - 26, 26 do i = i + 1; bulb(x, H + 2 + ((i % 2 == 0) and 3 or -3)) end
i = 0
for y = 26, H - 26, 26 do i = i + 1; bulb(-2 + ((i % 2 == 0) and -3 or 3), y) end
i = 0
for y = 26, H - 26, 26 do i = i + 1; bulb(W + 2 + ((i % 2 == 0) and 3 or -3), y) end
end

