local OC = {C3(226, 24, 48), C3(246, 200, 74), C3(24, 160, 86), C3(120, 190, 255), C3(200, 30, 120), C3(150, 90, 255), C3(255, 140, 40), C3(236, 244, 255)}
local GOLD = ColorSequence.new({K(0, C3(255, 240, 170)), K(0.5, C3(226, 168, 52)), K(1, C3(150, 98, 20))})
