-- falling snow (behind the UI + a few flakes in front for depth)
local function buildFlakes(W, H)
snowBack:ClearAllChildren(); snowFront:ClearAllChildren()
flakesB, flakesF = {}, {}
local nb = clamp(floor(W * H / (IS_MOBILE and 11000 or 6500)), 30, 100)
local nf = IS_MOBILE and 6 or 14
local function mkf(parent, list, front)
local s = front and rr(3, 6) or rr(2, 5)
local o = make("Frame", {BackgroundColor3 = SNOW, BackgroundTransparency = front and rr(0.35, 0.6) or rr(0.1, 0.55), BorderSizePixel = 0,
Size = UD(s, s), ZIndex = 1, Active = false}, parent)
make("UICorner", {CornerRadius = UDim.new(0.5, 0)}, o)
list[#list + 1] = {o = o, bx = rr(0, W), y = rr(-10, H), vy = rr(26, 70) * (front and 1.35 or 1) * (s / 3.5) ^ 0.4, ph = rr(0, 6.28), sw = rr(6, 24), fr = rr(0.6, 1.6)}
end
for _ = 1, nb do mkf(snowBack, flakesB, false) end
for _ = 1, nf do mkf(snowFront, flakesF, true) end
end

local function build()
deco:ClearAllChildren()
ornaments, bulbs = {}, {}
local W, H = WIN_W, WIN_H
buildOrnaments(W, H); buildFlakes(W, H)
end

local function sync()
local vis = X.on and X.enabled and win.Visible and win.GroupTransparency < 0.7
root.Visible = vis; snowBack.Visible = false; snowFront.Visible = false
end
win:GetPropertyChangedSignal("Visible"):Connect(sync)
win:GetPropertyChangedSignal("GroupTransparency"):Connect(sync)
winScale:GetPropertyChangedSignal("Scale"):Connect(function() rootScale.Scale = winScale.Scale end)

local lastChange, waiting = 0, false
holder:GetPropertyChangedSignal("Size"):Connect(function()
lastChange = os.clock()
if waiting then return end
waiting = true
task.spawn(function()
while os.clock() - lastChange < 0.25 do task.wait(0.1) end
waiting = false
if root.Parent then pcall(build) end
end)
end)

-- physics: pendulum per ornament, pivot accelerates with the hub
local G, DAMP, LIM = 1500, 0.85, 1.75
local lastPos, svx, svy, t, bulbAcc = nil, 0, 0, 0, 0
track(RunService.RenderStepped:Connect(function(dt)
if not root.Visible then lastPos = nil; svx, svy = 0, 0; return end
dt = math.min(dt, 0.05)
if dt <= 0 then return end
t = t + dt
deco.Visible = not Core.resizing
local W, H = WIN_W, WIN_H
local sc = holderScale.Scale * rootScale.Scale
if sc < 0.05 then sc = 1 end
local pos = holder.AbsolutePosition
local ax, ay = 0, 0
if lastPos then
local vx, vy = (pos.X - lastPos.X) / dt / sc, (pos.Y - lastPos.Y) / dt / sc
local k = 1 - exp(-dt * 26)
local nvx, nvy = svx + (vx - svx) * k, svy + (vy - svy) * k
ax = clamp((nvx - svx) / dt, -9000, 9000) * X.swing
ay = clamp((nvy - svy) / dt, -6000, 6000) * X.swing
svx, svy = nvx, nvy
end
lastPos = pos
local sub = 2
local h = dt / sub
for _ = 1, sub do
for _, o in ipairs(ornaments) do
local wind = sin(t * 0.7 + o.ph) * 60 + sin(t * 1.7 + o.ph * 2.3) * 28
local th, w = o.th, o.w
local a = -((G - ay) * sin(th) + (ax + wind) * cos(th)) / o.L
w = (w + a * h) * exp(-DAMP * h)
th = th + w * h
if th > LIM then th = LIM; w = -abs(w) * 0.35 elseif th < -LIM then th = -LIM; w = abs(w) * 0.35 end
o.th, o.w = th, w
end
end
for _, o in ipairs(ornaments) do o.c.Rotation = -math.deg(o.th) end
bulbAcc = bulbAcc + dt
if bulbAcc >= 0.05 then
bulbAcc = 0
for _, o in ipairs(fxO) do
local v = 0.5 + 0.5 * sin(t * 2.2 + o.ph)
o.halo.ImageTransparency = 0.78 - 0.4 * v
for _, q in ipairs(o.sps) do
local z = math.max(0, sin(t * q.sp + q.ph))
q.f.Size = UD(2 + 12 * z, 2 + 12 * z); q.f.Rotation = t * 40 * q.sp
end
end
end
for _, list in ipairs({flakesB, flakesF}) do
for _, f in ipairs(list) do
f.y = f.y + f.vy * dt
if f.y > H + 8 then f.y = -8; f.bx = rr(0, W) end
f.o.Position = UD(f.bx + sin(t * f.fr + f.ph) * f.sw, f.y)
end
end
end))

function X.set(on)
X.on = on == true
Core.XmasOn = X.on
if Core.applyLogo then pcall(Core.applyLogo) end
sync()
end
function X.setEnabled(v) X.enabled = v ~= false; sync() end
function X.setSwing(v) X.swing = clamp(tonumber(v) or 1, 0, 3) end

if Core.ThemeFX then
local baseSet = Core.ThemeFX.set
Core.ThemeFX.set = function(name) baseSet(name); X.set(name == "Christmas") end
end
build()
X.set(true)
end)
if not okX then warn("[Aspen Christmas] " .. tostring(errX)) end
end

