local filterPage
local function pageRows(page)
local out = {}
local function walk(p)
for _, c in ipairs(p:GetChildren()) do
if c:GetAttribute("ColFrame") then walk(c) else out[#out + 1] = c end
end
end
walk(page)
return out
end
Core.pageRows = pageRows
filterPage = function(page)
if not page then return end
local q = string.lower(searchBox.Text or "")
local rows = pageRows(page)
for _, c in ipairs(rows) do
if c:IsA("GuiObject") then
if c:GetAttribute("Hid") then
c.Visible = false
elseif c:GetAttribute("Sec") then
c.Visible = (q == "")
else
local sx = c:GetAttribute("S")
if sx then
if q == "" then c.Visible = true
else c.Visible = string.find(sx, q, 1, true) ~= nil end
end
end
end
end
local holder = page:FindFirstChild("Cols")
if holder then
local pl = page:FindFirstChildOfClass("UIListLayout")
local shown = 0
for _, col in ipairs(holder:GetChildren()) do
if col:GetAttribute("ColFrame") then
for _, card in ipairs(col:GetChildren()) do
if card:GetAttribute("IsCard") then
local any = false
for _, r in ipairs(card:GetChildren()) do
if r:IsA("GuiObject") and r.Visible and (r:GetAttribute("S") or r:GetAttribute("Sec")) then any = true; break end
end
card.Visible = any
if any then shown = shown + (1) end
local cl = card:FindFirstChildOfClass("UIListLayout")
if cl and pl then pcall(function() cl.HorizontalAlignment = pl.HorizontalAlignment end) end
end
end
end
end
local c1, c2 = holder:FindFirstChild("Col1"), holder:FindFirstChild("Col2")
if c1 and c2 then
if shown <= 1 then c1.Size = UDim2.new(1, 0, 0, 0); c2.Visible = false
else c1.Size = UDim2.new(0.5, -7, 0, 0); c2.Visible = true end
end
end
end
