function API.Keybind(text, default)
local key = keyOf(text)
local def = default or "None"
if CONFIG_VALUES[key] then default = CONFIG_VALUES[key] end
CONFIG_VALUES[key] = default or def
do local known = false
for _, e in ipairs(Core.KB) do if e.key == key then known = true end end
if not known then Core.KB[#Core.KB + 1] = {key = key, text = text} end end
local f = rowBase(28, text)
rowLabel(f, text, -120)
local kb = make("TextButton", {BackgroundColor3 = T.PanelHi, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0),
Size = UDim2.fromOffset(112, 20), Text = default or "None", FontFace = F_HEAVY, TextSize = 18, TextColor3 = T.AccentHi,
AutoButtonColor = false, ZIndex = 5}, f)
corner(kb, 2); stroke(kb, T.Border, 1, 0.4)
onAccent(function() kb.TextColor3 = T.AccentHi end)
kb.MouseEnter:Connect(function() hoverSfx(); tween(kb, 0.15, {BackgroundColor3 = T.ElementHi}) end)
kb.MouseLeave:Connect(function() tween(kb, 0.15, {BackgroundColor3 = T.PanelHi}) end)
local listening
kb.MouseButton1Click:Connect(function()
clickSfx()
if listening then return end
Core._keybindListening = true
kb.Text = "..."
listening = UIS.InputBegan:Connect(function(i)
local nm
if i.UserInputType == Enum.UserInputType.Keyboard then
nm = (i.KeyCode == Enum.KeyCode.Escape or i.KeyCode == Enum.KeyCode.Backspace) and "None" or i.KeyCode.Name
elseif i.UserInputType == Enum.UserInputType.MouseButton2 or i.UserInputType == Enum.UserInputType.MouseButton3 then
nm = i.UserInputType.Name
elseif i.UserInputType.Name:sub(1, 7) == "Gamepad" then
local k = i.KeyCode.Name
if k == "ButtonY" then nm = "None"
elseif k == "ButtonL1" or k == "ButtonR1" or k == "ButtonL2" or k == "ButtonR2" or k == "ButtonL3" or k == "ButtonR3" or k == "DPadLeft" or k == "DPadRight" then nm = k end
end
if nm then
kb.Text = nm
CONFIG_VALUES[key] = nm
Core._capturedInput = i
Core._keybindListening = false
markDirty()
listening:Disconnect(); listening = nil
end
end)
end)
f.Destroying:Connect(function()
    if listening then pcall(function() listening:Disconnect() end); listening = nil end
    Core._keybindListening = false
end)
registry[key] = function(v) kb.Text = tostring(v) end
resetters[key] = function() kb.Text = tostring(def); CONFIG_VALUES[key] = def end
return {
Get = function() return CONFIG_VALUES[key] end,
Set = function(_, v) kb.Text = tostring(v or "None"); CONFIG_VALUES[key] = v or "None"; markDirty() end,
Frame = f,
}
end
local function expandable(text, headW)
local HEAD = 28
local f = rowBase(HEAD, text)
f.ClipsDescendants = true
rowLabel(f, text, -(headW + 20))
local state = {open = false, body = 0}
function state.apply() tween(f, 0.2, {Size = UDim2.new(1, 0, 0, state.open and (HEAD + 4 + state.body) or HEAD)}) end
function state.toggle(v) state.open = v; state.apply() end
return f, HEAD, state
end
local DD = {ROW = 26, MAX = 26 * 6} -- MAX = tallest a dropdown list gets (6 rows) before it scrolls
function DD.list(f, HEAD)
local list = make("ScrollingFrame", {BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromOffset(8, HEAD + 2),
Size = UDim2.new(1, -16, 0, 0), CanvasSize = UDim2.new(), ScrollBarThickness = 3, ScrollBarImageColor3 = T.Accent,
ScrollingDirection = Enum.ScrollingDirection.Y, ZIndex = 4}, f)
onAccent(function() list.ScrollBarImageColor3 = T.Accent end)
make("UIListLayout", {Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder}, list)
return list
end
function DD.size(list, n)
local full = n * DD.ROW
local body = math.min(full, DD.MAX)
list.Size = UDim2.new(1, -16, 0, body)
list.CanvasSize = UDim2.fromOffset(0, full)
return body, full > DD.MAX
end
function API.Dropdown(text, options, default, cb)
local key = keyOf(text)
local def = default or options[1]
if CONFIG_VALUES[key] then default = CONFIG_VALUES[key] end
local current = default or options[1]
CONFIG_VALUES[key] = current
local f, HEAD, st = expandable(text, 120)
local head = make("TextButton", {BackgroundColor3 = T.PanelHi, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 4),
Size = UDim2.fromOffset(120, 20), Text = tostring(current) .. "  v", FontFace = F_HEAVY, TextSize = 18,
TextColor3 = T.Text, AutoButtonColor = false, ZIndex = 5}, f)
corner(head, 2); stroke(head, T.Border, 1, 0.4)
head.MouseEnter:Connect(function() hoverSfx(); tween(head, 0.15, {BackgroundColor3 = T.ElementHi}) end)
head.MouseLeave:Connect(function() tween(head, 0.15, {BackgroundColor3 = T.PanelHi}) end)
local list = DD.list(f, HEAD)
local function setCurrent(v, silent)
current = v; CONFIG_VALUES[key] = v; head.Text = tostring(v) .. "  v"
for _, c in ipairs(list:GetChildren()) do if c:IsA("TextButton") then c.TextColor3 = (c.Text == tostring(v)) and T.AccentHi or T.Text end end
if cb and not silent then task.spawn(cb, v) end
end
local function rebuild(opts)
for _, c in ipairs(list:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
local _, scrolls = DD.size(list, #opts)
list.CanvasPosition = Vector2.new(0, 0)
for i, opt in ipairs(opts) do
local o = make("TextButton", {BackgroundColor3 = T.PanelHi, Size = UDim2.new(1, scrolls and -6 or 0, 0, 24), Text = tostring(opt),
FontFace = F_BOLD, TextSize = 19, TextColor3 = T.Text, AutoButtonColor = false, LayoutOrder = i, ZIndex = 5}, list)
corner(o, 2)
if tostring(opt) == tostring(current) then o.TextColor3 = T.AccentHi end
o.MouseEnter:Connect(function() hoverSfx(); tween(o, 0.12, {BackgroundColor3 = T.ElementHi}) end)
o.MouseLeave:Connect(function() tween(o, 0.12, {BackgroundColor3 = T.PanelHi}) end)
o.MouseButton1Click:Connect(function() clickSfx(); markDirty(); setCurrent(opt); st.toggle(false) end)
end
st.body = (DD.size(list, #opts))
if st.open then st.apply() end
end
rebuild(options)
head.MouseButton1Click:Connect(function() clickSfx(); st.toggle(not st.open) end)
registry[key] = function(v) setCurrent(v) end
resetters[key] = function() setCurrent(def) end
if cb then task.spawn(cb, current) end
return {Set = function(_, v) setCurrent(v) end, SetOptions = function(_, o) rebuild(o) end, Get = function() return current end,
Frame = f, Open = function(v) st.toggle(v ~= false) end}
end
function API.MultiDropdown(text, options, defaults, cb)
local key = keyOf(text)
local sel = {}
local src = CONFIG_VALUES[key] or defaults or {}
for _, v in ipairs(src) do sel[v] = true end
local f, HEAD, st = expandable(text, 120)
local head = make("TextButton", {BackgroundColor3 = T.PanelHi, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 4),
Size = UDim2.fromOffset(120, 20), Text = "", FontFace = F_HEAVY, TextSize = 18, TextColor3 = T.Text,
AutoButtonColor = false, ZIndex = 5}, f)
corner(head, 2); stroke(head, T.Border, 1, 0.4)
local list = DD.list(f, HEAD)
local mBody, mScrolls = DD.size(list, #options)
st.body = mBody
local btns = {}
local function refresh()
local arr, c = {}, 0
for _, o in ipairs(options) do
if sel[o] then c = c + (1); table.insert(arr, o) end
if btns[o] then tween(btns[o], 0.12, {BackgroundColor3 = sel[o] and T.Accent or T.PanelHi}) end
end
head.Text = c .. " selected  v"
CONFIG_VALUES[key] = arr
if cb then task.spawn(cb, arr) end
end
for i, opt in ipairs(options) do
local o = make("TextButton", {BackgroundColor3 = T.PanelHi, Size = UDim2.new(1, mScrolls and -6 or 0, 0, 26), Text = tostring(opt),
FontFace = F_BOLD, TextSize = 19, TextColor3 = T.Text, AutoButtonColor = false, LayoutOrder = i, ZIndex = 5}, list)
corner(o, 2)
btns[opt] = o
o.MouseEnter:Connect(hoverSfx)
o.MouseButton1Click:Connect(function() clickSfx(); sel[opt] = not sel[opt]; refresh() end)
end
refresh()
head.MouseEnter:Connect(hoverSfx)
head.MouseButton1Click:Connect(function() clickSfx(); st.toggle(not st.open) end)
registry[key] = function(v) sel = {}; for _, x in ipairs(v) do sel[x] = true end; refresh() end
return {Frame = f, Get = function() return CONFIG_VALUES[key] end, Set = function(_, v) registry[key](v) end}
end
local PALETTE = {"#C41A1E", "#CA4646", "#CA8018", "#D29B1D", "#40C057", "#12B886", "#307EC1", "#6A4DC3", "#C14D76", "#FFFFFF"}
local function themedKind(text, d)
d = tostring(d or ""):upper()
if d == "#FFA0BE" then return "Accent" end
if d == "#FFD6E6" then return "AccentHi" end
if d == "#FFFFFF" then
if text == "Crosshair Color" or text == "Wireframe Color" or text == "Highlight Fill Color" or text:find("Chams Color$") then return "Accent" end
if text == "Nametag Color" or text == "Label Color" or text == "Crosshair Text Color" or text == "Highlight Outline Color" then return "AccentHi" end
end
return nil
end
