local w = type(e.weapon) == "table" and e.weapon.Name or e.weapon
if type(w) == "string" and (e.skin or e.wrap or e.charm) and #out < 40 then
out[#out + 1] = {w = w, s = e.skin and e.skin.name or nil, wr = e.wrap, c = e.charm, i = e.inverted and true or nil}
end
end
end
return out
end
local function netIngest(users)
local new, n = {}, 0
for uidStr, info in pairs(users) do
local uid = tonumber(uidStr)
if uid and uid ~= lp.UserId and type(info) == "table" and type(info.data) == "table" then
local map = {}
for i, it in ipairs(info.data) do
if i > 40 then break end
if type(it) == "table" and type(it.w) == "string" and #it.w < 64 then
local k = norm(it.w)
local e = {weapon = it.w, inverted = it.i == true}
if type(it.s) == "string" and #it.s < 64 and allowed(it.s) then
local d = Net.skinCache[it.s]
if d == nil then
local ok, r = pcall(mkSkin, it.s)
d = (ok and r) or false
Net.skinCache[it.s] = d
end
if d then e.skin = {name = it.s, data = d} end
end
if type(it.wr) == "string" and #it.wr < 64 and allowed(it.wr) then e.wrap = it.wr end
if type(it.c) == "string" and #it.c < 64 and allowed(it.c) then e.charm = it.c end
if k and (e.skin or e.wrap or e.charm) then map[k] = e end
end
end
new[uid] = map; n = n + 1
end
end
Net.remote = new
Net.status = "connected, " .. n .. " other hub user" .. (n == 1 and "" or "s")
end
local function netLoop()
if Net.running then return end
Net.running = true
task.spawn(function()
while Net.running and not Core.unloaded do
if Net.on and Net.url ~= "" and netReq then
local ok, res = pcall(netReq, {Url = Net.url:match("/sync$") and Net.url or (Net.url .. "/sync"), Method = "POST", Headers = {["Content-Type"] = "application/json"},
Body = HttpService:JSONEncode({room = game.JobId ~= "" and game.JobId or "studio", uid = lp.UserId, name = lp.Name, data = netEncodeMine()})})
if ok and type(res) == "table" and res.StatusCode == 200 then
local ok2, j = pcall(function() return HttpService:JSONDecode(res.Body) end)
if ok2 and type(j) == "table" and type(j.users) == "table" then netIngest(j.users) else Net.status = "bad reply from relay" end
else
Net.status = "relay unreachable"
end
end
task.wait(6)
end
Net.running = false
end)
end
function Net.setUrl(u)
u = tostring(u or ""):gsub("%s+", ""):gsub("/+$", "")
if u == "" then u = DEFAULT_RELAY end
if not u:match("^https://") then Net.status = "url must start with https://"; return end
Net.url = u
if Net.on then netLoop() end
end
function Net.setOn(v)
Net.on = v == true
if not Net.on then Net.remote = {}; Net.status = "off" elseif not netReq then Net.status = "executor has no http request" else netLoop() end
end
function API.RemoteEntry(owner, weapon)
if not Net.on or not owner then return nil end
local m = Net.remote[owner.UserId]
local k = norm(weapon)
return m and k and m[k] or nil
end
Net.setOn(true)
API.Ready = true
return API
end)()
