xpcall(function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")
local lp = Players.LocalPlayer
local P = {
ws = false, wsm = 2, slide = false, slidem = 2, jp = false, jpm = 2,
grav = false, gv = Workspace.Gravity, inf = false, fly = false, fsp = 60, fvsp = 1,
nc = false, bhop = false, bhopDelay = 0.03, bhopMove = false,
strafe = false, strafeSp = 90, strafeMax = 120, strafeRequireInput = true,
longJump = false, longJumpMode = "Under Feet", longJumpForce = 60, longJumpUp = 20, longJumpBehind = 8,
fov = false, fovv = 70, zoom = 128, freeze = false, saved = nil,
}
local origGrav = Workspace.Gravity
local function hum() local c = lp.Character; return c and c:FindFirstChildOfClass("Humanoid") end
local function root() local c = lp.Character; return c and c:FindFirstChild("HumanoidRootPart") end

local hookStatus = {walk = false, jump = false}
local proxOf, proxySource = {}, {}
local hookedUpvalues, hookedLookup = {}, {}
local function proxyUp(fn)
    local found = {walk = false, jump = false}
    if type(fn) ~= "function" or not (debug and type(debug.getupvalues) == "function" and type(debug.setupvalue) == "function") then
        return found
    end
    local okValues, values = pcall(debug.getupvalues, fn)
    if not okValues or type(values) ~= "table" then return found end
    for index, up in pairs(values) do
        if type(up) == "table" then
            local source = proxySource[up] or up
            local hasWalk = rawget(source, "BASE_WALKSPEED") ~= nil
            local hasJump = rawget(source, "BASE_JUMPPOWER") ~= nil
            if hasWalk or hasJump then
                local proxy = proxOf[source]
                if not proxy then
                    proxy = setmetatable({}, {
                        __index = function(_, key)
                            local value = source[key]
                            if type(value) ~= "number" then return value end
                            if key == "BASE_WALKSPEED" then
                                if P.slide and debug and type(debug.info) == "function" then
                                    local okName, caller = pcall(debug.info, 3, "n")
                                    if okName and caller == "Slide" then return value * P.slidem end
                                end
                                if P.ws then return value * P.wsm end
                            elseif key == "BASE_JUMPPOWER" and P.jp then
                                return value * P.jpm
                            end
                            return value
                        end,
                        __newindex = function(_, key, value) source[key] = value end,
                    })
                    proxOf[source] = proxy
                    proxySource[proxy] = source
                end
                hookedLookup[fn] = hookedLookup[fn] or {}
                if not hookedLookup[fn][index] then
                    local originalUpvalue = source
                    local okSet = pcall(debug.setupvalue, fn, index, proxy)
                    if okSet then
                        hookedLookup[fn][index] = true
                        hookedUpvalues[#hookedUpvalues + 1] = {fn = fn, index = index, original = originalUpvalue}
                    end
                end
                if hasWalk then found.walk = true end
                if hasJump then found.jump = true end
            end
        end
    end
    return found
end

local hookNoticeAt = 0
local function installHooks()
    local ok, err = pcall(function()
        local playerScripts = lp:WaitForChild("PlayerScripts", 5)
        local controllers = playerScripts and playerScripts:WaitForChild("Controllers", 5)
        local module = controllers and controllers:WaitForChild("MechanicsController", 5)
        assert(module, "MechanicsController module not found")
        local mechanics = require(module)
        local mt = getmetatable(mechanics)
        local proto = mt and rawget(mt, "__index")
        assert(type(proto) == "table", "MechanicsController prototype not found")

        local walkFn = rawget(proto, "_GetWalkSpeed")
        if type(walkFn) == "function" then
            local found = proxyUp(walkFn)
            hookStatus.walk = hookStatus.walk or found.walk
        end

        local hookFighter = rawget(proto, "_HookFighter")
        if type(hookFighter) == "function" then
            local found = proxyUp(hookFighter)
            hookStatus.jump = hookStatus.jump or found.jump
        end

        local localFighter = rawget(mechanics, "LocalFighter")
        local signal = type(localFighter) == "table" and rawget(localFighter, "EntityAdded")
        local node = type(signal) == "table" and rawget(signal, "_handlerListHead")
        while type(node) == "table" do
            local callback = rawget(node, "_fn")
            if type(callback) == "function" then
                local hasCustomGravity = false
                if debug and type(debug.getconstants) == "function" then
                    local okConstants, constants = pcall(debug.getconstants, callback)
                    if okConstants and type(constants) == "table" then
                        for _, constant in pairs(constants) do
                            if constant == "CustomGravity" then hasCustomGravity = true; break end
                        end
                    end
                end
                if hasCustomGravity then
                    local found = proxyUp(callback)
                    hookStatus.jump = hookStatus.jump or found.jump
                    if debug and type(debug.getprotos) == "function" and type(debug.getproto) == "function" then
                        local okProtos, protos = pcall(debug.getprotos, callback)
                        if okProtos and type(protos) == "table" then
                            for protoIndex in pairs(protos) do
                                local okProto, nested = pcall(debug.getproto, callback, protoIndex, true)
                                if okProto and type(nested) == "table" then
                                    for _, nestedFn in pairs(nested) do
                                        if type(nestedFn) == "function" then
                                            local nestedFound = proxyUp(nestedFn)
                                            hookStatus.jump = hookStatus.jump or nestedFound.jump
                                        end
                                    end
                                end
                            end
                        end
                    end
                    break
                end
            end
            node = rawget(node, "_next")
        end
    end)
    if not ok and os.clock() - hookNoticeAt > 8 then
        hookNoticeAt = os.clock()
        pcall(notify, "Movement", "Hook not ready: " .. tostring(err), 4, "danger")
    end
    return ok and (hookStatus.walk or hookStatus.jump)
end
local function ensureHooks()
    if not hookStatus.walk or not hookStatus.jump then installHooks() end
end

local mv = addSub(Core.mPlayer, "Movement", "Ground speed, slide control, jumping, air movement and mobility.")
local movementResetters = {}
local movementFeatures = {}
local function rememberDefault(control, value)
    if control and type(control.Set) == "function" then
        movementResetters[#movementResetters + 1] = function() control:Set(value) end
    end
    return control
end
local function addFeature(label, field, defaultMode, defaultKey)
    local cfg = {enabled = false, mode = defaultMode, key = defaultKey or "None", toggled = false}
    local toggle = mv.Toggle(label, false, function(value)
        cfg.enabled = value == true
        if not cfg.enabled then cfg.toggled = false end
        if field == "ws" or field == "slide" or field == "jp" then
            if cfg.enabled then task.spawn(ensureHooks) end
        end
    end)
    cfg.enabled = toggle:Get()
    rememberDefault(toggle, false)
    local mode = mv.Dropdown(label .. " Activation Mode", {"Always", "Toggle", "Hold"}, defaultMode, function(value)
        cfg.mode = value
        cfg.toggled = false
    end)
    cfg.mode = mode:Get()
    rememberDefault(mode, defaultMode)
    local key = mv.Keybind(label .. " Key", defaultKey or "None")
    cfg.key = key:Get()
    rememberDefault(key, defaultKey or "None")
    movementFeatures[field] = cfg
    return cfg
end

