local function performLongJump()
    if not P.longJump then return end
    local h, r = hum(), root()
    if not h or not r or h.Health <= 0 then return end
    local cam = Workspace.CurrentCamera
    local look = cam and cam.CFrame.LookVector or r.CFrame.LookVector
    local dir = Vector3.new(look.X, 0, look.Z)
    if dir.Magnitude < 0.001 then
        local fallback = r.CFrame.LookVector
        dir = Vector3.new(fallback.X, 0, fallback.Z)
    end
    if dir.Magnitude < 0.001 then return end
    dir = dir.Unit
    if P.longJumpMode == "Under Feet" then
        dir = (dir * P.longJumpBehind + Vector3.new(0, 4, 0)).Unit
    end
    r.AssemblyLinearVelocity = dir * P.longJumpForce + Vector3.new(0, P.longJumpUp, 0)
end

