-- Flight, bhop and air-control runtime. Settings are read live each simulation step.
local mover
local function flyClear()
    if mover then
        pcall(function() mover.lv:Destroy() end)
        pcall(function() mover.at:Destroy() end)
        mover = nil
    end
end
local function inputDir()
    if UIS:GetFocusedTextBox() then return Vector3.zero end
    local cam = Workspace.CurrentCamera
    if not cam then return Vector3.zero end
    local cf = cam.CFrame
    local look = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
    if look.Magnitude > 0 then look = look.Unit end
    local right = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z)
    if right.Magnitude > 0 then right = right.Unit end
    local d = Vector3.zero
    if UIS:IsKeyDown(Enum.KeyCode.W) then d += look end
    if UIS:IsKeyDown(Enum.KeyCode.S) then d -= look end
    if UIS:IsKeyDown(Enum.KeyCode.D) then d += right end
    if UIS:IsKeyDown(Enum.KeyCode.A) then d -= right end
    if UIS:IsKeyDown(Enum.KeyCode.Space) then d += Vector3.yAxis end
    if UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.LeftShift) then d -= Vector3.yAxis end
    return d
end

local function inputMatchesBind(input, bind)
    if type(bind) ~= "string" or bind == "" or bind == "None" then return false end
    if input.UserInputType == Enum.UserInputType.Keyboard then
        return input.KeyCode.Name == bind
    end
    return input.UserInputType.Name == bind
end
local function bindIsDown(bind)
    if type(bind) ~= "string" or bind == "" or bind == "None" then return false end
    if bind == "MouseButton1" then return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) end
    if bind == "MouseButton2" then return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) end
    if bind == "MouseButton3" then return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton3) end
    local ok, keyCode = pcall(function() return Enum.KeyCode[bind] end)
    return ok and keyCode ~= nil and UIS:IsKeyDown(keyCode) or false
end
local function featureActive(cfg)
    if not cfg or not cfg.enabled then return false end
    if cfg.mode == "Always" then return true end
    if cfg.mode == "Toggle" then return cfg.toggled == true end
    if cfg.mode == "Hold" then return bindIsDown(cfg.key) end
    return false
end
local function syncFeatureFlags()
    P.ws = featureActive(walkFeature)
    P.slide = featureActive(slideFeature)
    P.jp = featureActive(jumpFeature)
    P.inf = featureActive(infiniteFeature)
    P.bhop = featureActive(bhopFeature)
    P.strafe = featureActive(strafeFeature)
    P.fly = featureActive(flyFeature)
    P.nc = featureActive(noclipFeature)
end

local function setFeatureToggles(input)
    for _, cfg in pairs(movementFeatures) do
        if cfg.enabled and cfg.mode == "Toggle" and inputMatchesBind(input, cfg.key) then
            cfg.toggled = not cfg.toggled
        end
    end
end
local inputConnection = track(UIS.InputBegan:Connect(function(input, processed)
    if Core._capturedInput then
        local captured = Core._capturedInput == input
        Core._capturedInput = nil
        if captured then return end
    end
    if Core._keybindListening or UIS:GetFocusedTextBox() then return end
    setFeatureToggles(input)
    if not processed and P.longJump and inputMatchesBind(input, longJumpKey:Get()) then performLongJump() end
end))
track(UIS.JumpRequest:Connect(function()
    syncFeatureFlags()
    if P.inf and not P.fly and not UIS:GetFocusedTextBox() then
        local h = hum()
        if h then
            h.Jump = true
            h:ChangeState(Enum.HumanoidStateType.Jumping)
        end
    end
end))

local ncParts, ncT = {}, 0
local ncOriginal = {}
local function restoreNoclip()
    for part, canCollide in pairs(ncOriginal) do
        if part.Parent then pcall(function() part.CanCollide = canCollide end) end
    end
    table.clear(ncOriginal)
    table.clear(ncParts)
    ncT = 0
end
local wasAirborne = false
local lastBhopAt = 0
track(RunService.PreSimulation:Connect(function(dt)
    if Core.unloaded then return end
    syncFeatureFlags()
    local h, r = hum(), root()
    if P.grav then Workspace.Gravity = P.gv end
    if not h or not r then
        flyClear()
        restoreNoclip()
        wasAirborne = false
        return
    end

    if P.fly then
        local d = inputDir()
        local horizontal = Vector3.new(d.X, 0, d.Z)
        if horizontal.Magnitude > 1 then horizontal = horizontal.Unit end
        local vertical = Vector3.new(0, d.Y * P.fvsp, 0)
        if not mover or mover.lv.Parent == nil then
            flyClear()
            local at = Instance.new("Attachment")
            at.Parent = r
            local lv = Instance.new("LinearVelocity")
            lv.RelativeTo = Enum.ActuatorRelativeTo.World
            lv.MaxForce = math.huge
            lv.Attachment0 = at
            lv.Parent = r
            mover = {at = at, lv = lv}
        end
        mover.lv.VectorVelocity = (horizontal + vertical) * P.fsp
    elseif mover then
        flyClear()
    end

    if P.nc then
        local now = os.clock()
        if now - ncT > 0.25 or #ncParts == 0 then
            ncT = now
            table.clear(ncParts)
            for _, part in ipairs(lp.Character:GetDescendants()) do
                if part:IsA("BasePart") then
                    ncParts[#ncParts + 1] = part
                    if ncOriginal[part] == nil then ncOriginal[part] = part.CanCollide end
                end
            end
        end
        for _, part in ipairs(ncParts) do
            if part.Parent then part.CanCollide = false end
        end
    elseif next(ncOriginal) ~= nil then
        restoreNoclip()
    end

    local air = h.FloorMaterial == Enum.Material.Air
    if air then
        wasAirborne = true
    elseif wasAirborne then
        if P.bhop and (not P.bhopMove or h.MoveDirection.Magnitude > 0.05) then
            local now = os.clock()
            if now - lastBhopAt >= P.bhopDelay then
                lastBhopAt = now
                wasAirborne = false
                h.Jump = true
                h:ChangeState(Enum.HumanoidStateType.Jumping)
            end
        else
            wasAirborne = false
        end
    end

    if P.strafe and air then
        local move = h.MoveDirection
        local direction = Vector3.new(move.X, 0, move.Z)
        if direction.Magnitude < 0.05 then
            local requested = inputDir()
            direction = Vector3.new(requested.X, 0, requested.Z)
        end
        if direction.Magnitude < 0.05 and not P.strafeRequireInput then
            local cam = Workspace.CurrentCamera
            if cam then
                local look = cam.CFrame.LookVector
                direction = Vector3.new(look.X, 0, look.Z)
            end
        end
        if direction.Magnitude > 0.05 then
            direction = direction.Unit
            local velocity = r.AssemblyLinearVelocity
            local horizontalVelocity = Vector3.new(velocity.X, 0, velocity.Z)
            local targetVelocity = direction * P.strafeMax
            local change = targetVelocity - horizontalVelocity
            local maxChange = P.strafeSp * math.max(dt, 0)
            if change.Magnitude > maxChange and maxChange > 0 then
                change = change.Unit * maxChange
            end
            local nextVelocity = horizontalVelocity + change
            r.AssemblyLinearVelocity = Vector3.new(nextVelocity.X, velocity.Y, nextVelocity.Z)
        end
    end
end))

