local function esc(s) return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")) end
local function rep(s) return (s:gsub("%%", "%%%%")) end
local function textOn() return (S.lon and S.lname ~= "") or (S.ldon and S.ldn ~= "") or (S.oon and S.oname ~= "") or (S.odon and S.odn ~= "") end
local function pairList()
    local t = {}
    if S.lon and S.lname ~= "" then t[#t + 1] = {lp.Name, S.lname} end
    if S.ldon and S.ldn ~= "" and lp.DisplayName ~= lp.Name then t[#t + 1] = {lp.DisplayName, S.ldn} end
    for _, p in ipairs(Players:GetPlayers()) do
