local gver = 0
local function gradSeq(a, b, st, en)
st = math.clamp(st, 0, 0.97); en = math.clamp(en, st + 0.02, 1)
local k = {ColorSequenceKeypoint.new(0, a)}
if st > 0 then k[#k + 1] = ColorSequenceKeypoint.new(st, a) end
if en < 1 then k[#k + 1] = ColorSequenceKeypoint.new(en, b) end
k[#k + 1] = ColorSequenceKeypoint.new(1, b)
return ColorSequence.new(k)
end
local function sampleGrad(a, b, st, en, p)
en = math.max(en, st + 0.02)
if p <= st then return a elseif p >= en then return b end
return a:Lerp(b, (p - st) / (en - st))
end

