local function setRow(f, show)
if not f or not f.Parent then return end
local pageOf = f.Parent
while pageOf and not pageOf:IsA("ScrollingFrame") do pageOf = pageOf.Parent end
local hidden = f:GetAttribute("Hid") == true
if show == (not hidden) then return end
f:SetAttribute("Hid", (not show) or nil)
pcall(filterPage, pageOf)
if show and not LOADING then
local sc = f:FindFirstChild("PXS")
if sc then sc.Scale = 1 end
end
end
local function gradRange(api, label, getAB, setSE, init)
local kS, kE = api.Key(label .. " Start"), api.Key(label .. " End")
local st, en = init[1], init[2]
if tonumber(CONFIG_VALUES[kS]) then st = CONFIG_VALUES[kS] end
if tonumber(CONFIG_VALUES[kE]) then en = CONFIG_VALUES[kE] end
local f = api.RowBase(48, label)
make("TextLabel", {BackgroundTransparency = 1, Position = UDim2.fromOffset(12, 6), Size = UDim2.new(1, -140, 0, 20), Text = label, FontFace = F_BOLD,
TextSize = 19, TextColor3 = T.Text, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 4}, f)
local val = make("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 6), Size = UDim2.fromOffset(110, 20),
Text = "", FontFace = F_HEAVY, TextSize = 16, TextColor3 = T.AccentHi, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 4}, f)
onAccent(function() val.TextColor3 = T.AccentHi end)
local bar = make("Frame", {Position = UDim2.new(0, 12, 1, -16), Size = UDim2.new(1, -24, 0, 6), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 4}, f)
make("UICorner", {CornerRadius = UDim.new(1, 0)}, bar)
local barGrad = make("UIGradient", {Name = "NoTheme"}, bar)
local function handle()
local h = make("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(14, 14), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 7}, bar)
make("UICorner", {CornerRadius = UDim.new(1, 0)}, h)
make("UIStroke", {Color = WHITE, Thickness = 1.5, Transparency = 0.05, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, h)
make("UIStroke", {Color = Color3.new(0, 0, 0), Thickness = 3, Transparency = 0.7, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, h)
return h
end
local hA, hB = handle(), handle()
local function refresh(silent)
local a, b = getAB()
barGrad.Color = gradSeq(a, b, st, en)
hA.BackgroundColor3 = a; hB.BackgroundColor3 = b
tween(hA, 0.12, {Position = UDim2.fromScale(st, 0.5)}, Enum.EasingStyle.Quad)
tween(hB, 0.12, {Position = UDim2.fromScale(en, 0.5)}, Enum.EasingStyle.Quad)
val.Text = math.floor(st * 100 + 0.5) .. "%  -  " .. math.floor(en * 100 + 0.5) .. "%"
CONFIG_VALUES[kS], CONFIG_VALUES[kE] = st, en
setSE(st, en)
end
local drag
local function upd(i)
local rel = math.clamp((i.Position.X - bar.AbsolutePosition.X) / math.max(1, bar.AbsoluteSize.X), 0, 1)
if drag == "S" then st = math.min(rel, en - 0.02) else en = math.max(rel, st + 0.02) end
refresh(); markDirty()
end
local function grab(which, h)
h.InputBegan:Connect(function(i)
if isPress(i) then
drag = which; clickSfx(); upd(i)
tween(h, 0.2, {Size = UDim2.fromOffset(18, 18)}, Enum.EasingStyle.Quad)
i.Changed:Connect(function()
if i.UserInputState == Enum.UserInputState.End then drag = nil; tween(h, 0.25, {Size = UDim2.fromOffset(14, 14)}, Enum.EasingStyle.Quad) end
end)
end
end)
end
grab("S", hA); grab("E", hB)
bar.InputBegan:Connect(function(i)
if isPress(i) then
local rel = (i.Position.X - bar.AbsolutePosition.X) / math.max(1, bar.AbsoluteSize.X)
drag = math.abs(rel - st) <= math.abs(rel - en) and "S" or "E"; upd(i)
i.Changed:Connect(function() if i.UserInputState == Enum.UserInputState.End then drag = nil end end)
end
end)
track(UIS.InputChanged:Connect(function(i) if drag and isMove(i) then upd(i) end end))
registry[kS] = function(v) if tonumber(v) then st = math.clamp(v, 0, en - 0.02); refresh() end end
registry[kE] = function(v) if tonumber(v) then en = math.clamp(v, st + 0.02, 1); refresh() end end
resetters[kS] = function() st = init[1]; refresh() end
resetters[kE] = function() en = init[2]; refresh() end
refresh(true)
return {Frame = f, Refresh = refresh}
end
