local BODY = {Head = true, Torso = true, UpperTorso = true, LowerTorso = true, LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
RightUpperLeg = true, RightLowerLeg = true, RightFoot = true, LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
RightUpperArm = true, RightLowerArm = true, RightHand = true, LeftLeg = true, RightLeg = true, LeftArm = true, RightArm = true}
local function buildBones(char)
local bones, seen = {}, {}
local function add(a, b)
if a and b and a ~= b and BODY[a.Name] and BODY[b.Name] then
local k = a.Name .. ">" .. b.Name
if not seen[k] then seen[k] = true; bones[#bones + 1] = {a, b} end
end
end
for _, d in ipairs(char:GetDescendants()) do
if d:IsA("Motor6D") then add(d.Part0, d.Part1)
elseif d:IsA("AnimationConstraint") then
local a0, a1 = d.Attachment0, d.Attachment1
add(a0 and a0.Parent, a1 and a1.Parent)
end
end
return bones
end
local function espStep(dt)
dt = math.min(dt, 0.1)
local cam = Workspace.CurrentCamera
local anyEsp = S.box or S.name or S.hp or S.dist or S.tracer or S.skel or S.weapon
tb = tb + (dt * S.gspeed); tc = tc + (dt * S.cspeed)
