else org = Vector2.new(vp.X / 2, vp.Y) end
local tx, ty
local inView = false
if front then
tx, ty = c.X, c.Y + h / 2
inView = tx >= 0 and tx <= vp.X and ty >= 0 and ty <= vp.Y
else
local rel = cam.CFrame:PointToObjectSpace(hrp.Position)
local dir = Vector2.new(rel.X, -rel.Y)
if dir.Magnitude < 1e-3 then dir = Vector2.new(0, 1) end
dir = dir.Unit
tx, ty = org.X + dir.X * 4000, org.Y + dir.Y * 4000
end

local dx, dy = tx - org.X, ty - org.Y
local tmax = 1
if dx > 0 then tmax = math.min(tmax, (vp.X - org.X) / dx) elseif dx < 0 then tmax = math.min(tmax, (0 - org.X) / dx) end
if dy > 0 then tmax = math.min(tmax, (vp.Y - org.Y) / dy) elseif dy < 0 then tmax = math.min(tmax, (0 - org.Y) / dy) end
tmax = math.max(tmax, 0)
tx, ty = org.X + dx * tmax, org.Y + dy * tmax
dx, dy = tx - org.X, ty - org.Y
local len = math.sqrt(dx * dx + dy * dy)
