o.tr.Visible = false; o.td.Visible = false
else
o.tr.Size = UDim2.fromOffset(math.floor(len), S.tracerThick)
o.tr.Position = UDim2.fromOffset((org.X + tx) / 2, (org.Y + ty) / 2)
o.tr.Rotation = math.deg(math.atan2(dy, dx))
local tcol = S.tracerCol
local tf = math.clamp(dist / (S.tracerMax or 600), 0, 1)
if S.tracerMode == "Distance" then tcol = S.tracerCol:Lerp(S.tracerFar or Color3.new(1, 1, 1), tf)
elseif S.tracerMode == "Pulse" then tcol = S.tracerCol:Lerp(S.tracerFar or Color3.new(1, 1, 1), (math.sin(os.clock() * 3) + 1) / 2) end
o.tr.BackgroundColor3 = tcol
o.tr.BackgroundTransparency = math.clamp((1 - (S.tracerOpa or 1)) + (S.tracerFade and tf * 0.7 or 0), 0, 1)
o.tr.Visible = true
o.td.Position = UDim2.fromOffset(tx, ty)
