local function sameMatch(plr)
local a, b = player:GetAttribute("EnvironmentID"), plr:GetAttribute("EnvironmentID")
if a == nil and b == nil then return true end
return a == b
end
local function sameTeam(plr)
local a, b = player:GetAttribute("TeamID"), plr:GetAttribute("TeamID")
if a ~= nil and b ~= nil and a == b then return true end
if plr.Team ~= nil and plr.Team == player.Team then return true end
return plr.Neutral == false and player.Neutral == false and plr.TeamColor == player.TeamColor
end
local function shielded(plr, char)
if char:FindFirstChildOfClass("ForceField") then return true end
for _, src in ipairs({char, plr}) do
for _, k in ipairs({"IsInvincible", "Invincible", "ForceField", "Spawned", "Protected"}) do
if src:GetAttribute(k) == true then return true end
end
end
return false
end
local function legitOK(cfg, plr, char, hrp, camPos)
local tOn = cfg.team == nil and S.team or cfg.team
if tOn and sameTeam(plr) then return false end
if cfg.match ~= false and not sameMatch(plr) then return false end
local dist = (camPos - hrp.Position).Magnitude
if dist > math.min(S.maxd, cfg.maxD or cfg.maxR or 1000) then return false end
local lc = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
if lc and math.abs(hrp.Position.Y - lc.Position.Y) > (cfg.maxH or 60) then return false end
local v = hrp.Position - camPos
local elev = math.deg(math.asin(math.clamp(v.Y / math.max(v.Magnitude, 1e-3), -1, 1)))
if elev > (cfg.maxElev or 50) then return false end
if cfg.noFF ~= false and shielded(plr, char) then return false end
return true
end
