local baseFov = 70
local function hasAimState(obj)
    if not obj then return false end
    for _, key in ipairs({"IsAiming", "Aiming", "Scoped", "IsScoped", "ADS", "IsADS"}) do
        local ok, value = pcall(function() return obj:GetAttribute(key) end)
        if ok and value == true then return true end
        local child = obj:FindFirstChild(key)
        if child and child:IsA("BoolValue") and child.Value then return true end
    end
    return false
end
local function isScoped(cam)
    if not cam then return false end
    local f = cam.FieldOfView
    if f > baseFov then baseFov = f end
    local ch = player.Character
    return f < baseFov * 0.94
        or hasAimState(player)
        or hasAimState(ch)
        or UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
        or UIS:IsGamepadButtonDown(Enum.UserInputType.Gamepad1, Enum.KeyCode.ButtonL2)
end
