local p = char:FindFirstChild(nm)
if p then return p end
p = char:FindFirstChild((kind == "Head") and (small and "HitboxHead" or "HitboxHeadSmall") or (small and "HitboxBody" or "HitboxBodySmall"))
if p then return p end
if kind == "Head" then return char:FindFirstChild("Head") end
return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
end
function SA.parts(char, plr, sel)
local head = SA.hb(char, "Head")
local torso = SA.hb(char, "Torso")
local hrp = torso or char:FindFirstChild("HumanoidRootPart")
local list = {}
if sel == "Head" then if head then list[1] = head end
elseif sel == "Torso" then if torso then list[1] = torso end
elseif sel == "HumanoidRootPart" then if hrp then list[1] = hrp end
else
if head then list[#list + 1] = head end
if torso then list[#list + 1] = torso end
if hrp then list[#list + 1] = hrp end
if sel == "Random" and #list > 0 then
local rs = SA.rs
if rs.plr ~= plr or not rs.part or not rs.part.Parent then
rs.plr, rs.part = plr, list[math.random(1, #list)]
