end
end
return list
end
local saRP = RaycastParams.new()
saRP.FilterType = Enum.RaycastFilterType.Exclude
function SA.visible(cam, part, char)
local ign = {player.Character, char, cam}
local from = cam.CFrame.Position
local dir = part.Position - from
for _ = 1, 16 do
saRP.FilterDescendantsInstances = ign
local r = Workspace:Raycast(from, dir, saRP)
if not r then return true end
local h = r.Instance
if h:IsDescendantOf(char) then return true end
if h.CanCollide == false or h.CanQuery == false or h.Transparency >= 0.95 or h:HasTag("OutOfBoundsPart") then
ign[#ign + 1] = h
else
return false
end
end
return false
end
local function cfEnc(cf)
