return {["\0"] = cf.X, ["\1"] = cf.Y, ["\2"] = cf.Z, ["\3"] = rx, ["\4"] = ry, ["\5"] = rz}
end
local function cfDec(t)
if type(t) ~= "table" then return nil end
local a, b, c, d, e, f = t["\0"], t["\1"], t["\2"], t["\3"], t["\4"], t["\5"]
if type(a) ~= "number" or type(b) ~= "number" or type(c) ~= "number" or type(d) ~= "number" or type(e) ~= "number" or type(f) ~= "number" then return nil end
return CFrame.new(a, b, c) * CFrame.fromOrientation(d, e, f)
end
local hitRP = RaycastParams.new()
