do
-- ===================================================================================================
-- Aimbot + Silent Aim, rebuilt from Kiciahook's logic:
--   * shared target engine (filters, allowed hitboxes, closest-to-crosshair / weighted-random hitbox, centre / closest-point aim point)
--   * reaction + switch delay acquisition, activation modes + rules, target lock (toggle / auto / manual)
--   * Aimbot = camera aim using Kiciahook's aim types (Lock / Linear / Humanized / Spring) + smooth release after a kill
--   * Silent Aim = rewrites the game's own StartShooting packet (origin, look, hit part, local hit offset), optional "Manipulate"
--     (finds a shot origin up to 9.9 studs away from which the target is visible, same search pattern Kicia uses)
-- ===================================================================================================
local TAU = math.pi * 2
local AB = {on = false, mode = "Hold", held = false, toggled = false, showName = true, aimType = "Linear", spd = {Linear = 0.5, Humanized = 0.5, Spring = 0.5}, svx = 0, svy = 0,
    radius = 150, fov = true, fovCol = hexc("#FFA0BE"), fovThick = 1.5, ffill = 0}
local TL = {on = false, mode = "Toggle Lock", plr = nil}

local function baseCfg(c)
    c.filters = {Visible = true, Vulnerable = true, NotDeflecting = true, NotShielded = true, WithinFov = true}
    c.rules = {NotReloading = true, ScopedIn = false}
    c.hitboxes = {Head = true, Body = true}
    c.hsel, c.headPct, c.ptype, c.surfRed, c.keepDepth = "Closest to Crosshair", 50, "Center", 0, false
    c.react, c.swDelay = 0, 0
    c.acq = {cur = nil, pend = nil, since = 0}
    return c
end
baseCfg(AB)
baseCfg(SA)
SA.mode, SA.chance = "Always", 100
SA.manip, SA.manipMode, SA.manipRange, SA.manipInd = false, "On Best Target", 9.9, true
SA.fovThick = 1.5

-- ---------------------------------------------------------------- helpers
local function toSet(arr)
    local s = {}
    for _, v in ipairs(arr or {}) do s[v] = true end
    return s
end
local function kmatch(obj, i)
    local b = obj and obj.Get and obj.Get()
    if not b or b == "None" then return false end
    return (i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == b) or i.UserInputType.Name == b
        or (i.UserInputType.Name:sub(1, 7) == "Gamepad" and i.KeyCode.Name == b)
end
local function keyDown(obj)
    local b = obj and obj.Get and obj.Get()
    if not b or b == "None" then return false end
    if b == "MouseButton2" or b == "MouseButton3" then return UIS:IsMouseButtonPressed(Enum.UserInputType[b]) end
    local ok, r = pcall(function() return UIS:IsKeyDown(Enum.KeyCode[b]) end)
    return ok and r == true
end
local function actOn(c)
    if not c.on then return false end
    if c.mode == "Always" then return true end
    if c.mode == "Hold" then return c.held or keyDown(c.key) end
    return c.toggled
end
local function curGun()
    local f = Core.myFighter and Core.myFighter()
    local eq = f and rawget(f, "EquippedItem")
    if type(eq) ~= "table" then return nil end
    local info = rawget(eq, "Info")
    if type(info) ~= "table" or info.Type == "Melee" or info.Type == "Throwable" then return nil end
    return eq
end
local function blocked(c, eq, cam)
    if c.rules.NotReloading then
        local ok, r = pcall(function() return type(eq.IsReloading) == "function" and eq:IsReloading() end)
        if ok and r == true then return true end
    end
    if c.rules.ScopedIn and not isScoped(cam) then return true end
    return false
end
local function deflecting(ch)
    local k = ch:FindFirstChild("Katana")
    local d = k and k:FindFirstChild("Deflecting")
    return d ~= nil and d.Value == true
end
local function riotBlocks(root, from)
    local ch = root.Parent
    local sh = ch and (ch:FindFirstChild("Riot Shield") or ch:FindFirstChild("Shield"))
    if not sh then return false end
    return root.CFrame.LookVector:Dot((from - root.Position).Unit) < -0.2
end
local visRP = RaycastParams.new()
visRP.FilterType = Enum.RaycastFilterType.Exclude
local function visFrom(from, part, char, cam)
    local ign = {player.Character, char, cam}
    local dir = part.Position - from
    for _ = 1, 16 do
        visRP.FilterDescendantsInstances = ign
        local r = Workspace:Raycast(from, dir, visRP)
        if not r then return true end
        local h = r.Instance
        if h:IsDescendantOf(char) then return true end
        if h.CanCollide == false or h.CanQuery == false or h.Transparency >= 0.95 or h:HasTag("OutOfBoundsPart") then
            ign[#ign + 1] = h
        else
            return false
        end
    end
    return false
end
-- Kiciahook's manipulation search: the origin itself, a point pushed towards the target, then a ring of points around the line of fire
local function manipOrigin(from, part, char, cam, range)
    if visFrom(from, part, char, cam) then return from end
    local dir = part.Position - from
    local dist = dir.Magnitude
    if dist < 0.1 then return nil end
    local u = dir / dist
    local reach = math.min(range, dist - part.Size.Magnitude / 2)
    local pushed = false
    if reach > 0 then
        local p = from + u * reach
        pushed = true
        if visFrom(p, part, char, cam) then return p end
    end
    local up = math.abs(u:Dot(Vector3.yAxis)) > 0.99 and Vector3.xAxis or Vector3.yAxis
    local a = u:Cross(up).Unit
    local b = a:Cross(u).Unit
    local n = pushed and 6 or 7
    for k = 0, n - 1 do
        local th = TAU * k / n
        local p = from + (a * math.cos(th) + b * math.sin(th)) * range
        if visFrom(p, part, char, cam) then return p end
    end
    return nil
end

local HB = {Head = function(ch) return SA.hb(ch, "Head") end, Body = function(ch) return SA.hb(ch, "Torso") end}
local function aimPoint(c, cam, part)
    if c.ptype ~= "Closest Point" then return part.Position end
    local vp = cam.ViewportSize / 2
    local ray = cam:ViewportPointToRay(vp.X, vp.Y)
    local cf = part.CFrame
    local half = part.Size * 0.5 * (1 - c.surfRed / 100)
    local t = math.max((cf.Position - ray.Origin):Dot(ray.Direction), 0)
    local function clampL(l) return Vector3.new(math.clamp(l.X, -half.X, half.X), math.clamp(l.Y, -half.Y, half.Y), math.clamp(l.Z, -half.Z, half.Z)) end
    local p = cf:PointToWorldSpace(clampL(cf:PointToObjectSpace(ray.Origin + ray.Direction * t)))
    if c.keepDepth then
        local d = (cf.Position - ray.Origin):Dot(ray.Direction)
        local pd = (p - ray.Origin):Dot(ray.Direction)
        p = cf:PointToWorldSpace(clampL(cf:PointToObjectSpace(p + ray.Direction * (d - pd))))
    end
    return p
end

-- ---------------------------------------------------------------- target engine
local function candidates(c, cam, lockPlr, allowManip)
    local list = {}
    local center = cam.ViewportSize / 2
    local camPos = cam.CFrame.Position
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player and (not lockPlr or plr == lockPlr) and not sameTeam(plr) and sameMatch(plr) then
            local ch = plr.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            local root = ch and ch:FindFirstChild("HumanoidRootPart")
            if hum and root and hum.Health > 0 then
                local f = c.filters
                local ok = true
                if f.Vulnerable and shielded(plr, ch) then ok = false end
                if ok and f.NotDeflecting and deflecting(ch) then ok = false end
                if ok and f.NotShielded and riotBlocks(root, camPos) then ok = false end
                if ok then
                    for name, on in pairs(c.hitboxes) do
                        local part = on and HB[name] and HB[name](ch)
                        if part then
                            local pt = aimPoint(c, cam, part)
                            local sp = cam:WorldToViewportPoint(pt)
                            if sp.Z > 0 then
                                local scr = Vector2.new(sp.X, sp.Y)
                                local d = (scr - center).Magnitude
                                if lockPlr or not f.WithinFov or d <= c.radius then
                                    local entry = {plr = plr, char = ch, part = part, kind = name, point = pt, dist = d, screen = scr}
                                    if not f.Visible or visFrom(camPos, part, ch, cam) then
                                        list[#list + 1] = entry
                                    elseif allowManip then
                                        entry.needManip = true
                                        list[#list + 1] = entry
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return list
end
local function selectBest(c, cam, lockPlr)
    local allowManip = c.manip == true and c.filters.Visible
    local list = candidates(c, cam, lockPlr, allowManip)
    if #list == 0 then return nil end
    local camPos = cam.CFrame.Position
    if allowManip then
        -- On Best Target: only the single best candidate may be manipulated, the rest must be visible. On All Targets: any of them.
        local bestAny
        for _, e in ipairs(list) do if not bestAny or e.dist < bestAny.dist then bestAny = e end end
        local keep = {}
        for _, e in ipairs(list) do
            if not e.needManip then
                keep[#keep + 1] = e
            elseif c.manipMode == "On All Targets" or e == bestAny then
                local o = manipOrigin(camPos, e.part, e.char, cam, c.manipRange)
                if o then e.org = o; keep[#keep + 1] = e end
            end
        end
        list = keep
        if #list == 0 then return nil end
    end
    local bestP, bestD
    for _, e in ipairs(list) do
        if not bestD or e.dist < bestD then bestD, bestP = e.dist, e.plr end
    end
    local curP = c.acq and c.acq.cur
    if curP and curP ~= bestP then
        for _, e in ipairs(list) do
            if e.plr == curP and e.dist <= bestD * 1.45 + 6 then bestP = curP; break end
        end
    end
    local pick
    if c.hsel == "Weighted Random" then
        local now = os.clock()
        local roll = c.roll
        if not roll or roll.plr ~= bestP or now > roll.t then
            roll = {plr = bestP, t = now + 0.35, head = math.random() * 100 < c.headPct}
            c.roll = roll
        end
        local want = roll.head and "Head" or "Body"
        for _, e in ipairs(list) do if e.plr == bestP and e.kind == want then pick = e; break end end
    end
    if not pick then
        for _, e in ipairs(list) do
            if e.plr == bestP and (not pick or e.dist < pick.dist) then pick = e end
        end
    end
    if pick then
        local tn = os.clock()
        if c.lastPlr == pick.plr and c.lastKind and pick.kind ~= c.lastKind and tn - (c.lastKT or 0) < 0.4 then
            for _, e in ipairs(list) do if e.plr == pick.plr and e.kind == c.lastKind then pick = e; break end end
        end
        if c.lastPlr ~= pick.plr or c.lastKind ~= pick.kind then c.lastPlr, c.lastKind, c.lastKT = pick.plr, pick.kind, tn end
    end
    return pick
end
local function acquire(c, now, plr)
    local a = c.acq
    if a.cur == plr then a.pend = nil; return true end
    local need = (a.cur == nil) and c.react or c.swDelay
    if a.pend ~= plr then a.pend, a.since = plr, now end
    if now - a.since >= need then a.cur, a.pend = plr, nil; return true end
    return false
end
local function resetAcq(c) c.acq.cur, c.acq.pend = nil, nil end

