manipLbl.Name = "Manipulated"; manipLbl.BackgroundTransparency = 1; manipLbl.AnchorPoint = Vector2.new(0.5, 0)
manipLbl.Position = UDim2.new(0.5, 0, 0.5, 34); manipLbl.Size = UDim2.fromOffset(160, 18); manipLbl.Text = "Manipulated"
manipLbl.Font = Enum.Font.Code; manipLbl.TextSize = 14; manipLbl.TextColor3 = Color3.new(1, 1, 1); manipLbl.Visible = false
manipLbl.ZIndex = 5; manipLbl.Parent = aimGui
local function drawFov(cam, dt)
    local vp = cam.ViewportSize
    local show = AB.on and AB.fov
    AB.cf.Visible = show
    if show then AB.cf.Position = UDim2.fromOffset(vp.X / 2, vp.Y / 2); AB.cf.Size = UDim2.fromOffset(AB.radius * 2, AB.radius * 2) end
    local sshow = SA.on and SA.fov
    SA.cf.Visible = sshow
    if sshow then
        local goal = (SA.follow and SA.tScreen) or Vector2.new(vp.X / 2, vp.Y / 2)
        SA.fp = SA.fp and SA.fp:Lerp(goal, math.clamp(dt * (SA.follow and SA.tScreen and 18 or 40), 0, 1)) or goal
        SA.cf.Position = UDim2.fromOffset(SA.fp.X, SA.fp.Y); SA.cf.Size = UDim2.fromOffset(SA.radius * 2, SA.radius * 2)
        if SA.ffill and SA.fgrad then
            local t, sp = os.clock(), SA.fspeed or 1
            if SA.fmode == "Spin" then SA.cg.Rotation = (t * 60 * sp) % 360
            elseif SA.fmode == "Wave" then SA.cg.Offset = Vector2.new(((t * 0.3 * sp) % 2) - 1, 0)
            else SA.cg.Offset = Vector2.new(math.sin(t * 2 * sp) * 0.3, 0) end
        end
    end
    manipLbl.Visible = SA.on and SA.manip and SA.manipInd and SA.cur ~= nil and SA.cur.org ~= nil
end

-- ---------------------------------------------------------------- Aimbot (Kicia aim types: Lock / Linear / Humanized / Spring)
-- Port of Kiciahook's aim applier. Every type turns the screen-space gap between the aim origin (where the camera Rotation
-- points) and the target point into a delta, and the delta becomes a camera Rotation change using Kicia's radians-per-pixel
-- (rad(FOV) / ViewportSize.Y). On top of that: a target that dies / drops out is released smoothly (momentum glide-out),
-- and after a kill there is a short pause + ease-in before the next target is taken, so the camera never snaps away.
local GLIDE_TAU, KILL_PAUSE, EASE_IN, GLIDE_CAP = 0.10, 0.30, 0.45, 12

function AB.resetMotion()
    AB.svx, AB.svy, AB.glide = 0, 0, nil
end
function AB.reset()
    resetAcq(AB); AB.pick = nil; AB.curPlr = nil; AB.killT = nil; AB.resetMotion()
end
-- the game's CameraController rebuilds the camera from its own Rotation (pitch, yaw) every frame, so writing cam.CFrame fights it and jitters.
-- Like Kicia, we read / write that Rotation directly and the game turns it into the camera itself.
local CCtl = {}
local function ccInit()
    if CCtl.ok then return true end
    if os.clock() - (CCtl.at or -10) < 5 then return false end
    CCtl.at = os.clock()
    pcall(function()
        local ctrls = player.PlayerScripts:FindFirstChild("Controllers")
        local node = ctrls and ctrls:FindFirstChild("CameraController")
        local m = node and require(node)
        local mt = m and getmetatable(m)
        local idx = type(mt) == "table" and rawget(mt, "__index")
        local set = type(idx) == "table" and rawget(idx, "SetRotation")
        if type(set) == "function" and typeof(rawget(m, "Rotation")) == "Vector2" then CCtl.m, CCtl.set, CCtl.ok = m, set, true end
    end)
    return CCtl.ok == true
end
-- fallback only (CameraController not reachable): keeps the viewmodel glued to the camera when we have to write cam.CFrame
local function syncViewModel(delta, cam)
    local models = {}
    pcall(function()
        local eq = curGun()
        local vm = eq and rawget(eq, "ViewModel")
        local m = vm and rawget(vm, "Model")
        if typeof(m) == "Instance" and m:IsA("Model") then models[1] = m end
    end)
    if #models == 0 then
        local root = cam:FindFirstChild("ViewModels") or Workspace:FindFirstChild("ViewModels") or cam:FindFirstChild("ViewModel")
        if root then
            if root:IsA("Model") then models[1] = root
            else for _, c in ipairs(root:GetChildren()) do if c:IsA("Model") then models[#models + 1] = c end end end
        end
    end
    for _, m in ipairs(models) do pcall(function() m:PivotTo(delta * m:GetPivot()) end) end
end
local function rotGet(cam, forceCF)
    if not forceCF and ccInit() then
        local ok, r = pcall(rawget, CCtl.m, "Rotation")
        if ok and typeof(r) == "Vector2" then return r end
    end
    local rx, ry = cam.CFrame:ToOrientation()
    return Vector2.new(rx, ry)
end
local function rotSet(cam, v, forceCF)
    if CCtl.ok and not forceCF then
        local ok = pcall(function() coroutine.wrap(CCtl.set)(CCtl.m, v) end)
        if ok then return end
    end
    local old = cam.CFrame
    local new = CFrame.new(old.Position) * CFrame.fromOrientation(v.X, v.Y, 0)
    cam.CFrame = new
    syncViewModel(new * old:Inverse(), cam)
end
-- Kicia: screen point the camera Rotation currently points at
local function aimOrigin(cam, rot)
    local look = CFrame.fromOrientation(rot.X, rot.Y, 0).LookVector
    local v = cam:WorldToViewportPoint(cam.CFrame.Position + look * 1000)
    return Vector2.new(v.X, v.Y)
end
local function toScreen(cam, wp)
    local v = cam:WorldToViewportPoint(wp)
    local p = Vector2.new(v.X, v.Y)
    if v.Z < 0 then -- behind the camera: the projection is mirrored, so push the point out the opposite way
        local c = cam.ViewportSize / 2
        local d = c - p
        if d.Magnitude < 1 then d = Vector2.new(1, 0) end
        return c + d.Unit * 4000
    end
    return p
end
-- Kicia's Spring type: critically damped spring (SmoothDamp)
local function smoothDamp(cur, goal, vel, smooth, dt)
    local w = 2 / smooth
    local x = w * dt
    local e = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x)
    local ch = cur - goal
    local tmp = (vel + w * ch) * dt
    local nv = (vel - w * tmp) * e
    local out = goal + (ch + tmp) * e
    if (goal - cur > 0) == (out > goal) then out, nv = goal, 0 end
    return out, nv
end
-- Kicia's four aim types. Lock = full gap in one go, Linear = constant pixel step toward the target (speed * 10 px / frame),
-- Humanized = Linear with a human feel (ease-in on a new target, slows near the target, tiny sideways wobble), Spring = SmoothDamp.
local function aimDelta(o, tp, dt)
    local t = AB.aimType
    local speed = math.clamp(AB.spd[t] or 0.5, 0.01, 1)
    if t == "Lock" then
        AB.svx, AB.svy = 0, 0
        return tp - o
    elseif t == "Spring" then
        local T = math.max(dt, 10 / speed / 1000)
        local nx, vx = smoothDamp(o.X, tp.X, AB.svx or 0, T, dt)
        local ny, vy = smoothDamp(o.Y, tp.Y, AB.svy or 0, T, dt)
        AB.svx, AB.svy = vx, vy
        return Vector2.new(nx, ny) - o
    end
    AB.svx, AB.svy = 0, 0
    local gap = tp - o
    local m = gap.Magnitude
    if m < 1 then return nil end
    local u = gap.Unit
    if t == "Humanized" then
        local now = os.clock()
        local engage = math.clamp((now - (AB.engT or now)) / 0.35, 0, 1)
        local near = math.clamp(m / 60, 0.3, 1)
        local step = math.min(m, speed * 10 * (0.35 + 0.65 * engage) * near * (0.94 + math.noise(now * 0.7, 2.2) * 0.06))
        local wob = Vector2.new(-u.Y, u.X) * (math.noise(now * 1.3, 5.1) * math.min(m * 0.05, 2))
        return u * step + wob
    end
    return u * math.min(m, speed * 10)
end
local function moveBy(cam, rot, d, forceCF)
    local k = math.rad(cam.FieldOfView) / cam.ViewportSize.Y
    rotSet(cam, Vector2.new(rot.X - d.Y * k, rot.Y - d.X * k), forceCF)
end
local function targetDead(plr)
    if not plr or not plr.Parent then return true end
    local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
    return not hum or hum.Health <= 0
end
-- smooth release: leftover motion fades out instead of the aim stopping dead / snapping elsewhere
local function glideOut(cam, dt)
    local g = AB.glide
    if not g then return end
    g = g * math.exp(-dt / GLIDE_TAU)
    if g.Magnitude < 0.15 then AB.glide = nil; return end
    if g.Magnitude > GLIDE_CAP then g = g.Unit * GLIDE_CAP end
    AB.glide = g
    moveBy(cam, rotGet(cam), g)
end
function AB.step(dt)
    if AB.gone then return end
    local cam = Workspace.CurrentCamera
    if not cam then return end
    drawFov(cam, dt)
    dt = math.clamp(dt, 1 / 240, 0.1)
    if not actOn(AB) then AB.reset(); if TL.plr and not AB.on then TL.plr = nil end return end
    local eq = curGun()
    if not eq or blocked(AB, eq, cam) then AB.reset(); return end
    if TL.plr then
        local ch = TL.plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not (hum and hum.Health > 0) or not TL.plr.Parent then TL.plr = nil end
    end
    local now = os.clock()
    if AB.killT and now - AB.killT < KILL_PAUSE then glideOut(cam, dt); return end -- just killed someone: don't grab the next target yet
    local lockPlr = TL.on and TL.plr or nil
    local pick = selectBest(AB, cam, lockPlr)
    if AB.curPlr and (not pick or pick.plr ~= AB.curPlr) and targetDead(AB.curPlr) then
        AB.killT, AB.curPlr, AB.pick = now, nil, nil
        resetAcq(AB); AB.svx, AB.svy = 0, 0
        glideOut(cam, dt)
        return
    end
    if not pick then
        AB.curPlr, AB.pick = nil, nil
        resetAcq(AB); AB.svx, AB.svy = 0, 0
        glideOut(cam, dt)
        return
    end
    AB.pick = pick
    if TL.on then
        if TL.mode == "Auto Lock" and not TL.plr then TL.plr = pick.plr end
        if TL.mode == "Manual Only" and not TL.plr then return end
    end
    if not acquire(AB, now, pick.plr) then return end
    if AB.curPlr ~= pick.plr then AB.engT = now end
    AB.curPlr = pick.plr
    local scoped = isScoped(cam)
    local ramp = 1
    if AB.killT then -- first target after a kill: ease the aim in instead of snapping onto it
        local x = math.clamp((now - AB.killT - KILL_PAUSE) / EASE_IN, 0, 1)
        ramp = x * x * (3 - 2 * x)
        if x >= 1 then AB.killT = nil end
    end
    if scoped then
        -- scoped in the game ignores Rotation writes, so aim the way sleepy does: lerp the camera CFrame toward a CFrame facing the target
        local old = cam.CFrame
        local alpha = 1
        if AB.aimType ~= "Lock" then
            local sp = math.clamp(AB.spd[AB.aimType] or 0.5, 0.01, 1)
            local a60 = math.clamp(0.67 * sp * sp, 0.01, 1) * ramp
            if AB.aimType == "Humanized" then
                local engage = math.clamp((now - (AB.engT or now)) / 0.35, 0, 1)
                a60 = a60 * (0.35 + 0.65 * engage)
            end
            alpha = 1 - (1 - a60) ^ (dt * 60)
        else
            alpha = ramp
        end
        local new = old:Lerp(CFrame.new(old.Position, pick.point), alpha)
        cam.CFrame = new
        syncViewModel(new * old:Inverse(), cam)
        AB.glide = nil
        return
    end
    local rot = rotGet(cam)
    local d = aimDelta(aimOrigin(cam, rot), toScreen(cam, pick.point), dt)
    if d then
        d = d * ramp
        moveBy(cam, rot, d)
    end
    AB.glide = (AB.glide or Vector2.zero):Lerp(d or Vector2.zero, 0.4)
end
