-- ---------------------------------------------------------------- Silent Aim (packet rewrite)
function SA.active() return SA.on and actOn(SA) end
local function silentStep()
    if SA.dead then return end
    if SA.on and SA.hooked == nil and os.clock() - (SA.hookTry or 0) > 1 then SA.hookTry = os.clock(); SA.hook() end
    if not SA.active() then SA.cur = nil; SA.tScreen = nil; resetAcq(SA); return end
    local cam = Workspace.CurrentCamera
    local eq = cam and curGun()
    if not eq or blocked(SA, eq, cam) then SA.cur = nil; SA.tScreen = nil; resetAcq(SA); return end
    local pick = selectBest(SA, cam, nil)
    if not pick then SA.cur = nil; SA.tScreen = nil; resetAcq(SA); return end
    SA.tScreen = pick.screen
    if not acquire(SA, os.clock(), pick.plr) then return end
    SA.cur = pick
end
-- called from the namecall hook with the packet table the game is about to send
function SA.onShot(objId, pkt)
    local pick = SA.cur
    if not pick or not SA.active() then return end
    local sh = pkt["\1"]
    if type(sh) ~= "table" then return end
    if (SA.chance or 100) < 100 and math.random() * 100 > SA.chance then return end
    local part = pick.part
    if not part or not part.Parent or not pick.char.Parent then return end
    local cf0, cf1 = cfDec(sh["\0"]), cfDec(sh["\1"])
    if not cf0 or not cf1 then return end
    local cam = Workspace.CurrentCamera
    local point = aimPoint(SA, cam, part)
    local o0, o1 = cf0.Position, cf1.Position
    if pick.org then o0, o1 = pick.org, pick.org end
    local lp = hitLocal(o0, part, point) or part.CFrame:PointToObjectSpace(point)
    if lp == Vector3.zero then return end
    sh["\0"] = cfEnc(CFrame.lookAt(o0, point))
    sh["\1"] = cfEnc(CFrame.lookAt(o1, point))
    sh["\2"] = part
    sh["\3"] = cfEnc(CFrame.new(lp))
end
-- The game fires shots through a cached FireServer, so a __namecall hook never sees them. Kicia swaps the ReplicatedStorage upvalue
-- inside ClientItem.Input for a stand-in whose UseItem:FireServer we control; we do the same, with __namecall kept as a backup.
local seenPkt = setmetatable({}, {__mode = "k"})
local function handlePacket(objId, pkt)
    if type(pkt) ~= "table" or seenPkt[pkt] then return end
    seenPkt[pkt] = true
    if SA.on and not Core.rageFiring then pcall(SA.onShot, objId, pkt) end
end
local function installInputHook(rem, en)
    local RSv = game:GetService("ReplicatedStorage")
    local ok, installed = pcall(function()
        local ci = require(player.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem)
        local input = rawget(ci, "Input")
        if type(input) ~= "function" or not debug or not debug.getupvalues then return false end
        local fire = Instance.new("RemoteEvent").FireServer
        if type(clonefunction) == "function" then fire = clonefunction(fire) end
        local realRem = RSv:FindFirstChild("Remotes")
        local realRep = realRem and realRem:FindFirstChild("Replication")
        local realFighter = realRep and realRep:FindFirstChild("Fighter")
        local useItem = {FireServer = function(_, objId, enc, args, ...)
            if enc == en then
                handlePacket(objId, args)
                if Core.onShotSent then pcall(Core.onShotSent) end
            end
            return fire(rem, objId, enc, args, ...)
        end}
        local function wrap(real, over) return setmetatable(over, {__index = function(_, key) return real and real[key] end}) end
        local fake = wrap(RSv, {Remotes = wrap(realRem, {Replication = wrap(realRep, {Fighter = wrap(realFighter, {UseItem = useItem})})})})
        for _, up in pairs(debug.getupvalues(input)) do
            if type(up) == "table" then
                for key, v in pairs(up) do
                    if v == RSv then up[key] = fake; return true end
                end
            end
        end
        return false
    end)
    return ok and installed == true
end
function SA.hook()
    if SA.hooked ~= nil then return SA.hooked end
    SA.hooked = false
    local rem = Core.Shot and Core.Shot.remote()
    local en = Core.Shot and Core.Shot.enum("StartShooting")
    if not rem or not en then SA.hooked = nil; return false end
    local okI = installInputHook(rem, en)
    local okN = false
    if type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
        local old
        okN = pcall(function()
            local fn = function(self, ...)
                if self == rem and SA.on and getnamecallmethod() == "FireServer" then
                    local a, b = ...
                    if b == en then handlePacket(a, (select(3, ...))) end
                end
                return old(self, ...)
            end
            if type(newcclosure) == "function" then fn = newcclosure(fn) end
            old = hookmetamethod(game, "__namecall", fn)
        end)
    end
    SA.hooked = (okI or okN) and true or false
    SA.inputHook = okI
    if not SA.hooked then notify("Silent Aim", "Couldn't hook the shot packet, so Silent Aim fires its own shot while you hold fire.", 8, "danger") end
    return SA.hooked
end
-- no hook support in the executor: send the game's shot ourselves while fire is held
local saLast = 0
local function silentFallback()
    if SA.hooked ~= false or not SA.cur or not SA.active() then return end
    if not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return end
    local now = os.clock()
    if now - saLast < 0.1 then return end
    if (SA.chance or 100) < 100 and math.random() * 100 > SA.chance then return end
    local eq = curGun()
    if not eq then return end
    saLast = now
    pcall(Core.Shot.shoot, eq, SA.cur.part)
end
track(RunService.Heartbeat:Connect(function()
    local ok, e = pcall(function() silentStep(); silentFallback() end)
    if not ok and e ~= SA.lastErr then SA.lastErr = e; notify("Silent aim error", tostring(e):sub(1, 140), 8, "danger") end
end))

