function X.hide(o) if o then o.d.Visible = false; o.l.Visible = false; o.a.Visible = false; o.t.Visible = false end end
function X.step()
if X.gone then return end
local cam = Workspace.CurrentCamera
if not cam then return end
local on = X.dot or X.look or X.arrow
local vp, cpos = cam.ViewportSize, cam.CFrame.Position
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= player then
local o = X.pool[plr]
local char = on and plr.Character
local hum = char and char:FindFirstChildOfClass("Humanoid")
local head = char and char:FindFirstChild("Head")
local hrp = char and char:FindFirstChild("HumanoidRootPart")
local ok = hum ~= nil and head ~= nil and hrp ~= nil and hum.Health > 0
local dist = hrp and (cpos - hrp.Position).Magnitude or 0
if ok and dist > X.maxd then ok = false end
if ok and X.team and plr.Team ~= nil and plr.Team == player.Team then ok = false end
if not ok then X.hide(o)
else
o = o or X.get(plr)
local sp = cam:WorldToViewportPoint(head.Position)
local inView = sp.Z > 0 and sp.X >= 0 and sp.X <= vp.X and sp.Y >= 0 and sp.Y <= vp.Y
if X.dot and inView then
local s = math.clamp(1800 / (dist + 15), 3, 16) * X.dotSize
o.d.Size = UDim2.fromOffset(s, s); o.d.Position = UDim2.fromOffset(sp.X, sp.Y); o.d.BackgroundColor3 = X.dotCol; o.d.Visible = true
else o.d.Visible = false end
if X.look and inView then
local e = cam:WorldToViewportPoint(head.Position + head.CFrame.LookVector * X.lookLen)
if e.Z > 0 then
local dx, dy = e.X - sp.X, e.Y - sp.Y
o.l.Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy), 1.5); o.l.Position = UDim2.fromOffset((sp.X + e.X) / 2, (sp.Y + e.Y) / 2)
o.l.Rotation = math.deg(math.atan2(dy, dx)); o.l.BackgroundColor3 = X.lookCol; o.l.Visible = true
else o.l.Visible = false end
else o.l.Visible = false end
if X.arrow and not inView then
local rel = cam.CFrame:PointToObjectSpace(hrp.Position)
local dir = Vector2.new(rel.X, rel.Z)
if dir.Magnitude < 1e-3 then dir = Vector2.new(0, 1) end
dir = dir.Unit
local r = math.min(X.arrowR, math.min(vp.X, vp.Y) / 2 - 24)
local p = Vector2.new(vp.X / 2, vp.Y / 2) + dir * r
o.a.Position = UDim2.fromOffset(p.X, p.Y); o.a.Rotation = math.deg(math.atan2(dir.X, -dir.Y)); o.a.TextColor3 = X.arrowCol; o.a.Visible = true
if X.arrowTxt then
local tpos = p - dir * 22
o.t.Position = UDim2.fromOffset(tpos.X, tpos.Y); o.t.Text = math.floor(dist) .. "m"; o.t.TextColor3 = X.arrowCol; o.t.Visible = true
else o.t.Visible = false end
else o.a.Visible = false; o.t.Visible = false end
end
end
end
end
