do
local TB = {on = false, act = "Always", held = false, toggled = false, react = 0.05, rel = 0.08, radius = 0, hit = "Any", scoped = false,
noreload = true, team = true, maxd = 1000, gap = 0, elapsed = nil, left = 0, lastFire = 0}
Core.Shot = {}
do
    local RSv = game:GetService("ReplicatedStorage")
    local S = Core.Shot
    local pi = math.pi
    local function enc(x, y, z, a, b, c) return {["\0"] = x, ["\1"] = y, ["\2"] = z, ["\3"] = a, ["\4"] = b, ["\5"] = c} end
    S.ORIG, S.DIR, S.OFF = enc(-9e37, 0, 0, -pi / 2, pi, pi), enc(0, -90000000, 0, -pi / 2, pi, pi), enc(0, 1, 0, 0, 0, 0)
    local remote, enums
    function S.remote()
        if remote and remote.Parent then return remote end
        local ok, r = pcall(function() return RSv.Remotes.Replication.Fighter.UseItem end)
        remote = ok and r or nil
        return remote
    end
    function S.enum(name)
        if not enums then
            local ok, lib = pcall(function() return require(RSv.Modules.EnumLibrary) end)
            if ok and type(lib) == "table" then enums = rawget(lib, "_to_enum") end
        end
        return enums and enums[name]
    end
    function S.objectId(eq)
        local d = rawget(eq, "Data")
        local id
        if type(d) == "table" then pcall(function() id = d.ObjectID end) end
        if id then return id end
        for _, tbl in ipairs({eq, type(d) == "table" and d or {}}) do
            for k, v in pairs(tbl) do
                if type(k) == "string" and k:lower():find("objectid") and v ~= nil then return v end
            end
        end
        return nil
    end
    function S.hitbox(ch, kind)
        if not ch then return nil end
        if kind == "Head" then return ch:FindFirstChild("HitboxHead") or ch:FindFirstChild("Head") end
        return ch:FindFirstChild("HitboxBody") or ch:FindFirstChild("HumanoidRootPart")
    end
    -- the game's own encoded shot (same packet newo/sleepy ragebot sends)
    function S.shoot(eq, part, realOrigin)
        local rem, id, en = S.remote(), S.objectId(eq), S.enum("StartShooting")
        if not rem then return false, "UseItem remote not found" end
        if not en then return false, "EnumLibrary StartShooting not found" end
        if not id then return false, "gun object id not found" end
        if not part then return false, "hitbox part not found" end
        local info = rawget(eq, "Info")
        local t = {["\0"] = S.ORIG, ["\1"] = S.DIR, ["\2"] = part, ["\3"] = S.OFF}
        local p = (type(info) == "table" and info.IsRaycast) and {["\1"] = t, ["\2"] = true} or {["\1"] = t}
        return pcall(rem.FireServer, rem, id, en, p, nil)
    end
end
local tb = addSub(mCombat, "Triggerbot", "Fires when an enemy hitbox is under your crosshair.")
tb.Section("Triggerbot")
