tb.Hint("Reaction Delay is how long the crosshair must stay on a target before firing. Release Delay keeps the trigger held briefly after you leave the target. Trigger Radius also fires when a target is within that many pixels of the crosshair.")
local function tbMatch(i)
    local b = tbKey.Get()
    if not b or b == "None" then return false end
    return (i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == b) or i.UserInputType.Name == b or (i.UserInputType.Name:sub(1, 7) == "Gamepad" and i.KeyCode.Name == b)
end
track(UIS.InputBegan:Connect(function(i, gp) if gp or not tbMatch(i) then return end TB.held = true; TB.toggled = not TB.toggled end))
track(UIS.InputEnded:Connect(function(i) if tbMatch(i) then TB.held = false end end))
local function tbActive()
    if not TB.on then return false end
    local m = TB.act
    if m == "Always" then return true end
    if m == "Hold Right Mouse" then return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) or UIS:IsGamepadButtonDown(Enum.UserInputType.Gamepad1, Enum.KeyCode.ButtonL2) end
    if m == "Key Hold" then return TB.held end
    return TB.toggled
end
local trp = RaycastParams.new()
trp.FilterType = Enum.RaycastFilterType.Exclude
local function look(cam, px, py)
    local ray = cam:ViewportPointToRay(px, py)
    local ign = {player.Character, cam}
    for _ = 1, 16 do
        trp.FilterDescendantsInstances = ign
        local r = Workspace:Raycast(ray.Origin, ray.Direction * 2000, trp)
        if not r then return false end
        local inst = r.Instance
        local model = inst:FindFirstAncestorOfClass("Model")
        local plr = model and Players:GetPlayerFromCharacter(model)
        if plr and plr ~= player then
            if inst.Name:sub(1, 6) ~= "Hitbox" then
                ign[#ign + 1] = inst
            else
                local hum = model:FindFirstChildOfClass("Humanoid")
                local okHit = hum ~= nil and hum.Health > 0
                if okHit and TB.team and plr.Team ~= nil and plr.Team == player.Team then okHit = false end
                if okHit and (r.Position - cam.CFrame.Position).Magnitude > TB.maxd then okHit = false end
                if okHit and TB.hit == "Head Only" and not inst.Name:find("Head") then okHit = false end
                if okHit and TB.hit == "Body Only" and not inst.Name:find("Body") then okHit = false end
                return okHit
            end
        elseif inst.CanCollide == false or inst.Transparency >= 0.95 then
            ign[#ign + 1] = inst
        else
            return false
        end
    end
    return false
end
local function onTarget(cam)
    local c = cam.ViewportSize * 0.5
    if look(cam, c.X, c.Y) then return true end
    local rd = TB.radius
    if rd > 0 then
        for _, o in ipairs({Vector2.new(rd, 0), Vector2.new(-rd, 0), Vector2.new(0, rd), Vector2.new(0, -rd)}) do
            if look(cam, c.X + o.X, c.Y + o.Y) then return true end
        end
    end
    return false
end
local function gun()
    local f = Core.myFighter and Core.myFighter()
    local eq = f and rawget(f, "EquippedItem")
    if type(eq) ~= "table" then return nil end
    local info = rawget(eq, "Info")
    if type(info) ~= "table" or info.Type == "Melee" or info.Type == "Throwable" then return nil end
    return f, eq
end
local function fire(f, eq)
    local now = os.clock()
    if now - TB.lastFire < TB.gap then return end
    TB.lastFire = now
    if type(mouse1click) == "function" then pcall(mouse1click); return end
    if type(mouse1press) == "function" and type(mouse1release) == "function" then pcall(mouse1press); task.defer(function() pcall(mouse1release) end); return end
    local ok = type(f.Input) == "function" and pcall(f.Input, f, "StartShooting")
    if not ok and type(eq.Input) == "function" then pcall(eq.Input, eq, "StartShooting") end
end
local function tbStep(dt)
    if not tbActive() then TB.elapsed = nil; TB.left = 0; return end
    local cam = Workspace.CurrentCamera
    local f, eq = gun()
    if not cam or not f then TB.elapsed = nil; TB.left = 0; return end
    local data = rawget(eq, "Data")
    if TB.scoped and not (type(data) == "table" and data.IsAiming == true) then TB.elapsed = nil; TB.left = 0; return end
    if TB.noreload then
        local okR, rl = pcall(function() return type(eq.IsReloading) == "function" and eq:IsReloading() end)
        if okR and rl == true then TB.elapsed = nil; TB.left = 0; return end
    end
    if onTarget(cam) then
        TB.elapsed = (TB.elapsed or 0) + (TB.elapsed and dt or 0)
        if TB.elapsed >= TB.react then TB.left = TB.rel; fire(f, eq); return end
    else
        TB.elapsed = nil
    end
    TB.left = math.max(0, TB.left - dt)
    if TB.left > 0 then fire(f, eq) end
end
pcall(function() RunService:UnbindFromRenderStep("AspenTrigger") end)
RunService:BindToRenderStep("AspenTrigger", Enum.RenderPriority.Camera.Value + 3, function(dt) pcall(tbStep, dt) end)
gui.Destroying:Connect(function() pcall(function() RunService:UnbindFromRenderStep("AspenTrigger") end) end)
end

do (function()
-- ===================== RAGEBOT (ported from Kaze hub's rage + Kicia transport settings) =====================
-- loop (Heartbeat): pick target -> make sure the chosen gun is equipped -> when the gun is ready, sit at the shot position (head based) for a
-- moment, fire the shot packet from there, hold, then teleport back to where you were before the shooting started.
-- RenderStepped(First) puts your real character back so you never see any of it.
local RS = game:GetService("ReplicatedStorage")
local RG = {on = false, act = "Always", held = false, toggled = false, tprio = "Closest", maxd = 5000, team = true, noFF = true,
    weapon = "Primary", hit = "Head", pos = "Inside", rndWait = 1, rndPos = "Inside", rndAt = 0, dist = 5, inY = -0.7, orbit = 8, face = false,
    autoReload = true, autoEquip = true, park = true, retMode = "Start Position", home = nil, roundAt = -100, roundDelay = 0.5, sawRound = false, spawnAt = -100, settle = 0.05, hold = 0.12, gap = 0, multi = 1, phys = true, eqWait = 0.18, mDelay = 0.4,
    target = nil, state = nil, oldCF = nil, root = nil, lastCF = nil, posSince = nil, shotAt = -100, lockUntil = 0, nextShot = 0, nextReload = 0,
    nextEquip = 0, nextMelee = 0, eqSeen = nil, eqAt = 0, physOn = false, physH = nil, dead = false, rt = nil, ammoId = nil, ammoSeen = nil, shotsSince = 0,
    ind = true, indCol = Color3.fromRGB(212, 76, 86), spin = 180, barLen = 12, barTh = 2, barGap = 6, txtSize = 14, indY = 0, indName = true,
    }
local MODES = {"Inside", "Above", "Under", "Behind", "Front", "Orbit"}

-- ---- game plumbing (same lookups kaze / kicia use) ----
local NET = {}
local function ensureNet()
    if NET.fire and NET.remote and NET.to then return true end
    pcall(function()
        local lib = require(RS:WaitForChild("Modules", 3):WaitForChild("EnumLibrary", 3))
        NET.to = rawget(lib, "_to_enum") or lib._to_enum
        local rem = RS:WaitForChild("Remotes", 3):WaitForChild("Replication", 3):WaitForChild("Fighter", 3):WaitForChild("UseItem", 3)
        local fire = rem.FireServer
        if type(clonefunction) == "function" then fire = clonefunction(fire) end
        NET.remote, NET.fire = rem, fire
    end)
    return NET.fire and NET.remote and NET.to and true or false
end
local FC
local function myFighter()
    if not FC then
        local ok, m = pcall(function()
            local c = player:WaitForChild("PlayerScripts", 3):WaitForChild("Controllers", 3):WaitForChild("FighterController", 3)
            return require(c)
        end)
        FC = ok and m or nil
    end
    local objs = FC and rawget(FC, "Objects")
    if type(objs) ~= "table" then return nil end
    for _, o in pairs(objs) do
        if type(o) == "table" and rawget(o, "Player") == player then return o end
    end
end
Core.myFighter = myFighter
local function weaponList(f)
    local list, gi = {}, 0
    local its = rawget(f, "Items")
    if type(its) ~= "table" then return list end
    for _, it in pairs(its) do
        local info, data = rawget(it, "Info"), rawget(it, "Data")
        if type(info) == "table" and type(data) == "table" and data.ObjectID then
            local slot
            if info.Type == "Melee" then slot = "Melee"
            elseif info.Type == "Throwable" then slot = "Utility"
            else
                gi = gi + 1
                slot = tostring(info.Slot or info.Category or "")
                if slot ~= "Primary" and slot ~= "Secondary" then slot = gi == 1 and "Primary" or "Secondary" end
            end
            list[#list + 1] = {item = it, id = data.ObjectID, name = data.Name, ty = info.Type, slot = slot, ammo = data.Ammo, reserve = data.AmmoReserve, ray = info.IsRaycast, info = info}
        end
    end
    return list
end
local function cfEnc(cf)
    local rx, ry, rz = cf:ToOrientation()
    return {["\0"] = cf.X, ["\1"] = cf.Y, ["\2"] = cf.Z, ["\3"] = rx, ["\4"] = ry, ["\5"] = rz}
end
local hitRP = RaycastParams.new()
hitRP.FilterType = Enum.RaycastFilterType.Include
local function shotLocal(origin, part)
    hitRP.FilterDescendantsInstances = {part}
    local r = Workspace:Raycast(origin, part.Position - origin, hitRP)
    local l = r and part.CFrame:PointToObjectSpace(r.Position)
    if l and l ~= Vector3.zero then return l end
    local l2 = part.CFrame:PointToObjectSpace(part:GetClosestPointOnSurface(origin))
    if l2 == Vector3.zero then return nil end
    return l2
end
local function fireGun(w, t, org)
    if not ensureNet() then return false end
    local part = RG.hit == "Body" and t.root or t.head
    local lh = shotLocal(org, part) or Vector3.zero
    local aim = part.Position
    local cf = cfEnc((aim - org).Magnitude > 0.01 and CFrame.lookAt(org, aim) or CFrame.new(org))
    local sh = {["\0"] = cf, ["\1"] = cf, ["\2"] = part, ["\3"] = cfEnc(CFrame.new(lh))}
    local args = w.ray and {["\1"] = sh, ["\2"] = true} or {["\1"] = sh}
    Core.rageFiring = true
    pcall(NET.fire, NET.remote, w.id, NET.to["StartShooting"], args, nil)
    Core.rageFiring = false
    return true
end
local mAnim = 1
local function attackMelee(w, t, org)
    if not ensureNet() then return false end
    local to = NET.to
    local part = RG.hit == "Body" and t.root or t.head
    local lh = shotLocal(org, part) or Vector3.zero
    local cf = cfEnc((part.Position - org).Magnitude > 0.01 and CFrame.lookAt(org, part.Position) or CFrame.new(org))
    local sh = {["\0"] = cf, ["\1"] = cf, ["\2"] = part, ["\3"] = cfEnc(CFrame.new(lh))}
    local an = to["AttackAnimation" .. mAnim] or to["Attack" .. mAnim] or to["AttackAnimation1"] or to["Attack1"]
    Core.rageFiring = true
    pcall(NET.fire, NET.remote, w.id, to["StartShooting"], {["\1"] = sh, ["\2"] = an}, nil)
    Core.rageFiring = false
    mAnim = mAnim % 3 + 1
    if not (to["AttackAnimation" .. mAnim] or to["Attack" .. mAnim]) then mAnim = 1 end
    return true
end
local function reload(w)
    local now = tick()
    if now < RG.nextReload or not ensureNet() then return false end
    RG.nextReload = now + 0.7
    local r = NET.to["Reload"]
    NET.fire(NET.remote, w.id, NET.to["StartReloading"], {["\1"] = r, ["\2"] = r}, nil)
    return true
end
local function equip(w)
    local now = tick()
    if now < RG.nextEquip then return end
    RG.nextEquip = now + 0.12
    pcall(function() local fn = w.item.Equip; if type(fn) == "function" then fn(w.item) end end)
end
-- fast physics replication while the rage is on
local function physSync(on)
    if RG.physOn == on then return end
    RG.physOn = on
    pcall(function()
    end)
    local sf = setfflag or (syn and syn.setfflag)
    if type(sf) == "function" then
        pcall(sf, "DFIntS2PhysicsSenderRate", on and "120" or "15")
        pcall(sf, "DFIntAssemblyHistoryBufferSize", on and "2147483648" or "15")
        pcall(sf, "DFIntAssemblyHistorySkipSize", on and "0" or "8")
    end
end


-- ---- round start detection: the game replicates its round status as a plain "RoundStarted" string; watch the replication remotes for it ----
do
    local function scan(v, depth)
        if v == "RoundStarted" then return true end
        if type(v) == "table" and depth < 3 then
            for _, x in pairs(v) do if scan(x, depth + 1) then return true end end
        end
        return false
    end
    local hooked = setmetatable({}, {__mode = "k"})
    local function watch(r)
        if hooked[r] or not r:IsA("RemoteEvent") then return end
        hooked[r] = true
        track(r.OnClientEvent:Connect(function(...)
            for k = 1, select("#", ...) do
                if scan((select(k, ...)), 0) then RG.roundAt = os.clock(); RG.sawRound = true; RG.home = nil; return end
            end
        end))
    end
    pcall(function()
        local folder = RS:WaitForChild("Remotes", 5)
        if not folder then return end
        for _, d in ipairs(folder:GetDescendants()) do watch(d) end
        track(folder.DescendantAdded:Connect(watch))
    end)
    -- fallback for modes that never send a round status: a fresh spawn counts as the start of the round
    track(player.CharacterAdded:Connect(function() RG.spawnAt = os.clock(); RG.home = nil end))
end

-- ---- UI ----
local rg = addSub(mCombat, "Rage", "Auto-targeting rage (Kaze logic) with shot position, indicator and weapon logic.")
rg.Section("Activation")
rg.Toggle("Enable Rage", false, function(v) RG.on = v == true; RG.target = nil; if RG.on then ensureNet() end end)
rg.Dropdown("Activation", {"Always", "Toggle", "Hold"}, "Always", function(v) RG.act = v end)
local rgKey = rg.Keybind("Rage Key", "B")
rg.Section("Rage Position")
rg.Dropdown("Rage Position", {"Inside", "Above", "Under", "Behind", "Front", "Orbit", "Random"}, "Inside", function(v) RG.pos = v; RG.rndAt = 0 end)
rg.Slider("Random Switch Wait (s)", 0.05, 5, 1, function(v) RG.rndWait = v end, 0.05)
rg.Slider("Offset Distance", 1, 30, 5, function(v) RG.dist = v end, 0.5)
rg.Slider("Inside Depth Below Head", 0, 4, 0.7, function(v) RG.inY = -v end, 0.05)
rg.Slider("Orbit Speed", 1, 40, 8, function(v) RG.orbit = v end, 1)
rg.Toggle("Face Target", false, function(v) RG.face = v == true end)
rg.Hint("Positions are measured from the target's head. Inside sits in their head, Above/Under/Behind/Front use Offset Distance. Random switches between all modes after the wait time.")
rg.Section("Targeting")
rg.Dropdown("Target Sort", {"Closest", "Lowest Health", "Highest Health", "Fastest"}, "Closest", function(v) RG.tprio = v end)
rg.Slider("Max Distance", 50, 20000, 5000, function(v) RG.maxd = v end, 50)
rg.Toggle("Team Check", true, function(v) RG.team = v end)
rg.Toggle("Skip Forcefield", true, function(v) RG.noFF = v end)
rg.Section("Weapon")
rg.Dropdown("Rage Weapon", {"Primary", "Secondary", "Melee"}, "Primary", function(v) RG.weapon = v; RG.eqSeen = nil end)
rg.Dropdown("Hitbox", {"Head", "Body"}, "Head", function(v) RG.hit = v end)
rg.Toggle("Auto Equip", true, function(v) RG.autoEquip = v == true end)
rg.Toggle("Auto Reload", true, function(v) RG.autoReload = v == true end)
rg.Section("Shooting")
rg.Toggle("Return To Origin While Waiting", true, function(v) RG.park = v == true end)
rg.Dropdown("Return Position", {"Start Position", "Live Position"}, "Start Position", function(v) RG.retMode = v end)
rg.Slider("Round Start Delay (s)", 0, 5, 0.5, function(v) RG.roundDelay = v end, 0.1)
rg.Slider("Settle Time (s)", 0, 0.3, 0.05, function(v) RG.settle = v end, 0.01)
rg.Slider("Hold After Shot (s)", 0, 0.5, 0.12, function(v) RG.hold = v end, 0.01)
rg.Slider("Fire Gap (s)", 0, 0.5, 0, function(v) RG.gap = v end, 0.01)
rg.Slider("Shots Per Frame", 1, 5, 1, function(v) RG.multi = math.floor(v) end, 1)
rg.Hint("While the gun is on cooldown, reloading or equipping, the server sees you back at the spot you were standing before the shooting started (Start Position) or where you are right now (Live Position). The rage waits Round Start Delay seconds after the round starts before it begins shooting.")
rg.Section("Indicator")
rg.Toggle("Rage Indicator", true, function(v) RG.ind = v == true end)
rg.ColorWheel("Indicator Colour", "#D44C56", function(h) RG.indCol = Color3.fromHex(h) end)
rg.Slider("Spin Speed (deg/s)", 0, 720, 180, function(v) RG.spin = v end, 5)
rg.Slider("Bar Length", 3, 40, 12, function(v) RG.barLen = v end, 1)
rg.Slider("Bar Thickness", 1, 6, 2, function(v) RG.barTh = v end, 1)
rg.Slider("Bar Gap", 0, 30, 6, function(v) RG.barGap = v end, 1)
rg.Slider("Text Size", 10, 24, 14, function(v) RG.txtSize = v end, 1)
rg.Slider("Vertical Offset", -300, 300, 0, function(v) RG.indY = v end, 5)
rg.Toggle("Show Target Name", true, function(v) RG.indName = v == true end)

local function kmatch(i)
    local b = rgKey.Get()
    if not b or b == "None" then return false end
    return (i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == b) or i.UserInputType.Name == b or (i.UserInputType.Name:sub(1, 7) == "Gamepad" and i.KeyCode.Name == b)
end
track(UIS.InputBegan:Connect(function(i, gp) if gp or not kmatch(i) then return end RG.held = true; RG.toggled = not RG.toggled end))
track(UIS.InputEnded:Connect(function(i) if kmatch(i) then RG.held = false end end))
local function active()
    if not RG.on then return false end
    if RG.act == "Always" then return true end
    if RG.act == "Hold" then return RG.held end
    return RG.toggled
end

-- ---- targeting + position ----
local function pickTarget(hrp)
    local best, bs
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player and not (RG.team and plr.Team ~= nil and plr.Team == player.Team) then
            local c = plr.Character
            local h = c and c:FindFirstChildOfClass("Humanoid")
            local r = c and c:FindFirstChild("HumanoidRootPart")
            local head = c and (c:FindFirstChild("Head") or c:FindFirstChild("HitboxHead"))
            if h and r and head and h.Health > 0 and not (RG.noFF and c:FindFirstChildOfClass("ForceField")) then
                local d = (r.Position - hrp.Position).Magnitude
                if d <= RG.maxd then
                    local score = d
                    if RG.tprio == "Lowest Health" then score = h.Health * 1000 + d
                    elseif RG.tprio == "Highest Health" then score = -h.Health * 1000 + d
                    elseif RG.tprio == "Fastest" then score = -r.AssemblyLinearVelocity.Magnitude * 1000 + d end
                    if not bs or score < bs then best, bs = {plr = plr, char = c, hum = h, root = r, head = head, dist = d}, score end
                end
            end
        end
    end
    return best
end
local function baseCF(t, now)
    local hp, d = t.head.Position, RG.dist
    local mode = RG.pos
    if mode == "Random" then
        if now >= RG.rndAt then RG.rndPos = MODES[math.random(1, #MODES)]; RG.rndAt = now + RG.rndWait end
        mode = RG.rndPos
    end
    local look = t.root.CFrame.LookVector
    local p
    if mode == "Above" then p = hp + Vector3.new(0, d, 0)
    elseif mode == "Under" then p = hp - Vector3.new(0, d, 0)
    elseif mode == "Behind" then p = hp - look * d
    elseif mode == "Front" then p = hp + look * d
    elseif mode == "Orbit" then local a = now * RG.orbit; p = hp + Vector3.new(math.cos(a) * d, 0, math.sin(a) * d)
    else p = hp + Vector3.new(0, RG.inY, 0.05) end
    if RG.face and (hp - p).Magnitude > 0.05 then
        local dir = (hp - p).Unit
        return CFrame.lookAt(p, hp, math.abs(dir.Y) > 0.99 and Vector3.new(0, 0, 1) or Vector3.yAxis)
    end
    return CFrame.new(p)
end

local function step(dt)
    if RG.dead then return end
    local ch = player.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    local cam = Workspace.CurrentCamera
    if not active() then RG.state = nil; RG.target = nil; RG.lastCF = nil; RG.rt = nil; RG.home = nil; physSync(false); return end
    if not (hum and hrp and hum.Health > 0 and cam) then RG.state = "waiting for spawn..."; RG.target = nil; RG.lastCF = nil; RG.rt = nil; RG.home = nil; physSync(false); return end
    physSync(RG.phys)
    ensureNet()
    local now = os.clock()
    -- round start: wait Round Start Delay seconds (default 1s) before any shooting begins
    local gate = RG.sawRound and RG.roundAt or RG.spawnAt
    if now < gate + RG.roundDelay then
        RG.state = "waiting..."; RG.target = nil; RG.lastCF = nil; RG.rt = nil; RG.home = nil
        return
    end
    local t = pickTarget(hrp)
    RG.target = t
    if not t and not RG.rt then RG.state = "waiting..."; RG.lastCF = nil; RG.home = nil; return end
    -- the spot you stood on before the shooting started; every "waiting" frame sends you back here
    if not RG.home then RG.home = hrp.CFrame end
    local function homeCF()
        if RG.retMode == "Live Position" or not RG.home then return hrp.CFrame end
        return RG.home
    end
    local fighter = myFighter()
    if not fighter then RG.rt = nil; RG.state = "fighter not found"; return end
    local list = weaponList(fighter)
    local eq = rawget(fighter, "EquippedItem")
    local eqData = type(eq) == "table" and rawget(eq, "Data")
    local eqId = type(eqData) == "table" and eqData.ObjectID or nil
    local chosen
    for _, w in ipairs(list) do if w.slot == RG.weapon then chosen = w; break end end
    if not chosen then RG.rt = nil; RG.state = "no " .. RG.weapon:lower() .. " weapon"; return end

    -- ---- Kicia reload transport: from the moment the last bullet is shot until the mag is full again you sit in the immune ring ----
    local ping = player:GetNetworkPing() * 0.5
    local repDelay, remDelay = ping + 0.05, ping + 1 / 60
    local ammo = type(chosen.ammo) == "number" and chosen.ammo or nil
    local reserveOk = type(chosen.reserve) ~= "number" or chosen.reserve > 0
    if RG.ammoId ~= chosen.id or RG.ammoSeen ~= ammo then RG.ammoId, RG.ammoSeen, RG.shotsSince = chosen.id, ammo, 0 end
    local isR = false
    pcall(function() local f = chosen.item.IsReloading; if type(f) == "function" then isR = f(chosen.item) == true end end)
    local rt = RG.rt
    if rt and (rt.id ~= chosen.id or eqId ~= chosen.id or now - rt.start > 8) then RG.rt = nil; rt = nil end
    if rt then
        if rt.pending then
            if ammo and ammo <= 0 then rt.pending = false; rt.ack = 0
            elseif now >= rt.ack or (ammo and ammo - RG.shotsSince > 0) then RG.rt = nil; rt = nil end
        elseif not reserveOk or (ammo and ammo > 0 and not isR) then RG.rt = nil; rt = nil
        elseif RG.autoReload and not isR and now >= rt.ready and now >= rt.ack and reload(chosen) then rt.ack = now + remDelay + repDelay end
    end
    if RG.rt then
        RG.state = "reloading..."
        local rcf = homeCF()
        RG.lastCF = rcf
        if not RG.oldCF then RG.oldCF = hrp.CFrame end
        RG.root = hrp
        hrp.CFrame = rcf
        return
    end
    if not t then RG.state = "waiting..."; RG.lastCF = nil; return end

    local base = baseCF(t, now)
    local org = base.Position
    local function settled(pos)
        local last = RG.lastCF
        if not RG.posSince or not last or (pos - last.Position).Magnitude > 3 then RG.posSince = now end
        return now - RG.posSince >= RG.settle
    end
    local ready, state = false, nil
    if eqId ~= chosen.id then
        RG.eqSeen = nil
        if RG.autoEquip then equip(chosen); state = "equipping..." else state = "weapon not equipped" end
    else
        if RG.eqSeen ~= chosen.id then RG.eqSeen = chosen.id; RG.eqAt = now end
        if now - RG.eqAt < RG.eqWait then state = "equipping..."
        elseif chosen.ty == "Melee" then
            ready = tick() >= RG.nextMelee
            if ready and settled(org) then
                if attackMelee(chosen, t, org) then RG.shotAt = now; RG.lockUntil = now + RG.hold; RG.nextMelee = tick() + RG.mDelay end
            end
        elseif ammo and ammo <= 0 then
            state = "reloading..."
            if RG.autoReload and reserveOk then RG.rt = {id = chosen.id, start = now, pending = false, ready = now + repDelay, ack = 0} end
        else
            local cd = rawget(chosen.item, "_shoot_cooldown")
            if type(cd) ~= "number" then cd = 0 end
            if tick() >= cd and tick() >= RG.nextShot then
                ready = true
                if settled(org) then
                    RG.lockUntil = now + RG.hold; RG.shotAt = now; RG.nextShot = tick() + RG.gap
                    for _ = 1, RG.multi do fireGun(chosen, t, org) end
                    RG.shotsSince = RG.shotsSince + RG.multi
                    -- that was the last bullet: leave to Kicia's reload spot straight away
                    if RG.autoReload and reserveOk and ammo and ammo - RG.shotsSince <= 0 then
                        RG.rt = {id = chosen.id, start = now, pending = true, ready = now + repDelay, ack = now + remDelay + repDelay}
                    end
                end
            end
        end
    end
    RG.state = state or ((now - RG.shotAt < 0.4) and "firing...") or (ready and "locking on...") or "cooldown..."
    local cf = base
    if RG.rt then
        cf = homeCF()
    elseif RG.park and not ready and now >= RG.lockUntil then
        cf = homeCF()
    end
    RG.lastCF = cf
    if not RG.oldCF then RG.oldCF = hrp.CFrame end
    RG.root = hrp
    hrp.CFrame = cf
end
local function restore()
    if RG.oldCF and RG.root and RG.root.Parent then RG.root.CFrame = RG.oldCF end
    RG.oldCF = nil
end
track(RunService.Heartbeat:Connect(function(dt)
    local ok, e = pcall(step, dt)
    if not ok and e ~= RG.lastErr then RG.lastErr = e; notify("Rage error", tostring(e):sub(1, 140), 8, "danger") end
end))

-- ===== rage indicator: small spinning outlined crosshair + status text under it =====
do
    local box = make("Frame", {Name = "AspenRageIndicator", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(120, 120), ZIndex = 120, Active = false, Visible = false, BorderSizePixel = 0}, gui)
    local spinner = make("Frame", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(120, 120), ZIndex = 120, Active = false, BorderSizePixel = 0}, box)
    local arms = {}
    for i = 1, 4 do
        local a = make("Frame", {BackgroundColor3 = RG.indCol, AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0, ZIndex = 121, Active = false}, spinner)
        make("UIStroke", {Color = Color3.new(0, 0, 0), Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, a)
        arms[i] = a
    end
