---------------------------------------------------------------- in-script sound engine (synth -> wav -> getcustomasset)
local SR = 44100
local TAU = math.pi * 2
local sin, exp, floor = math.sin, math.exp, math.floor

-- renders len seconds of fn(t) (floats), normalises, fades the edges and returns wav bytes
local function renderWav(len, fn)
    local n = floor(len * SR)
    local s, peak = table.create(n), 1e-6
    for i = 0, n - 1 do
        local v = fn(i / SR)
        s[i + 1] = v
        local a = v < 0 and -v or v
        if a > peak then peak = a end
    end
    local gain, out = 0.85 / peak, table.create(n)
    for i = 1, n do
        local fade = math.min(1, (i - 1) / 120, (n - i) / 500)
        out[i] = string.pack("<i2", floor(math.clamp(s[i] * gain * fade, -1, 1) * 32000))
    end
    local data = table.concat(out)
    return "RIFF" .. string.pack("<I4", 36 + #data) .. "WAVEfmt " .. string.pack("<I4I2I2I4I4I2I2", 16, 1, 1, SR, SR * 2, 2, 16) .. "data" .. string.pack("<I4", #data) .. data
end
local function note(t, t0, f, decay, h2, h3)
    if t < t0 then return 0 end
    local x = t - t0
    local e = exp(-decay * x)
    return e * (sin(TAU * f * x) + (h2 or 0) * sin(TAU * f * 2 * x) * exp(-decay * 0.6 * x) + (h3 or 0) * sin(TAU * f * 3 * x) * exp(-decay * 0.9 * x))
end
local function parts(t, f, ratios, decay)
    local v = 0
    for i, r in ipairs(ratios) do v = v + sin(TAU * f * r * t) * exp(-decay * (1 + 0.35 * (i - 1)) * t) / (1 + 0.5 * (i - 1)) end
    return v
end
-- Karplus-Strong string, sample-sequential (call once per sample)
local function pluck(f, damp)
    local nn = math.max(2, floor(SR / f))
    local buf, idx = table.create(nn), 1
    for i = 1, nn do buf[i] = math.random() * 2 - 1 end
    return function()
        local nxt = idx % nn + 1
        local v = buf[idx]
        buf[idx] = (buf[idx] + buf[nxt]) * 0.5 * damp
        idx = nxt
        return v
    end
end

local SYNTH = {
    {"Synth Crystal", 0.6, function(t) return parts(t, 1318.5, {1, 2, 3}, 5) end},
    {"Synth Chime", 0.8, function(t) return parts(t, 1760, {1, 2.76, 5.4}, 4.5) end},
    {"Synth Glass Tap", 0.3, function(t) return parts(t, 2400, {1, 2.32, 4.25, 6.63}, 20) end},
    {"Synth Bubble", 0.22, function(t) return sin(TAU * (400 * (1400 / 400) ^ math.min(1, t / 0.12)) * t * 0.5 + 0) * exp(-16 * t) end},
    {"Synth Drop", 0.22, function(t) local f = 500 + 700 * exp(-18 * t); return sin(TAU * f * t) * exp(-14 * t) end},
    {"Synth Coin", 0.5, function(t) return note(t, 0, 987.8, 25, 0.3, 0.1) * 0.8 + note(t, 0.06, 1318.5, 7, 0.3, 0.1) end},
    {"Synth Marimba", 0.5, function(t) return parts(t, 880, {1, 4, 10}, 9) end},
    {"Synth Kalimba", 0.6, function(t) return parts(t, 1046.5, {1, 5.4, 9}, 7) end},
    {"Synth Wood", 0.18, function(t) return parts(t, 1500, {1, 2.3, 3.9}, 38) end},
    {"Synth Blip", 0.12, function(t) return note(t, 0, 1200, 38, 0.5) end},
    {"Synth Soft Pop", 0.16, function(t) local f = 150 + 450 * exp(-70 * t); return sin(TAU * f * t) * exp(-34 * t) end},
    {"Synth Sparkle", 0.6, function(t)
        return note(t, 0, 1046.5, 14, 0.2) + note(t, 0.05, 1318.5, 14, 0.2) + note(t, 0.1, 1568, 12, 0.2) + note(t, 0.15, 2093, 9, 0.2)
    end},
    {"Synth Orb", 0.45, function(t)
        local f = 1000 + 900 * math.min(1, t / 0.18) + 18 * sin(TAU * 18 * t)
        return sin(TAU * f * t) * exp(-8 * t)
    end},
    {"Synth Bow Ding", 0.3, function(t)
        local f = 1900 - 300 * math.min(1, t / 0.08)
        return (sin(TAU * f * t) + 0.35 * sin(TAU * f * 2 * t)) * exp(-14 * t)
    end},
    {"Synth Pluck", 0.5, (function() local p; local last = -1
        return function(t) if t <= last or not p then p = pluck(660, 0.997) end; last = t; return p() end
    end)()},
    {"Synth Harp", 0.8, (function() local ps, last = nil, -1
        return function(t)
            if t <= last or not ps then ps = {pluck(523.3, 0.997), pluck(659.3, 0.997), pluck(784, 0.997)} end
            last = t
            local v = ps[1]()
            if t >= 0.07 then v = v + ps[2]() end
            if t >= 0.14 then v = v + ps[3]() end
            return v
        end
    end)()},
}
local SYNTH_ASSET, SYNTH_NAMES = {}, {}
if CAN_FILES then
    for _, r in ipairs(SYNTH) do SYNTH_NAMES[#SYNTH_NAMES + 1] = r[1] end
    task.spawn(function()
        for _, r in ipairs(SYNTH) do
            if Core.unloaded then return end
            local path = SND_DIR .. "/syn_" .. r[1]:lower():gsub("%W", "_") .. "_v1.wav"
            local ok = pcall(function()
                local has = isfile(path)
                if not has then writefile(path, renderWav(r[2], r[3])) end
                SYNTH_ASSET[r[1]] = getcustomasset(path)
            end)
            if not ok then SYNTH_ASSET[r[1]] = nil end
            task.wait()
        end
    end)
end

---------------------------------------------------------------- names, config, playback
local IDS, NAMES = {}, {}
for _, e in ipairs(PRESETS) do NAMES[#NAMES + 1] = e[1]; IDS[e[1]] = "rbxassetid://" .. e[2] end
for _, n in ipairs(SYNTH_NAMES) do NAMES[#NAMES + 1] = n end
NAMES[#NAMES + 1] = "Custom"

local HIT = {enabled = false, head = "Neverlose", body = "Pop", custom = "", hv = 2, hp = 1, bv = 2, bp = 1, mute = false}
local SHOT = {enabled = false, name = "Synth Pluck", custom = "", volume = 1.5, speed = 1, start = 0}

local function resolve(name, custom)
    if name ~= "Custom" then return IDS[name] or SYNTH_ASSET[name] end
    local c = tostring(custom or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if c == "" then return nil end
    if c:match("^%d+$") then return "rbxassetid://" .. c end
    if c:lower():find("^rbxassetid://") or c:lower():find("^rbxasset://") then return c end
    if CAN_FILES then
        for _, path in ipairs({c, SND_DIR .. "/" .. c, SND_DIR .. "/" .. c .. ".mp3", SND_DIR .. "/" .. c .. ".wav", SND_DIR .. "/" .. c .. ".ogg"}) do
            local okf, has = pcall(isfile, path)
            if okf and has then
                local oka, asset = pcall(getcustomasset, path)
                if oka and asset then return asset end
            end
        end
    end
    return nil
end

local function play(id, vol, speed, start)
    if not id or id == "" then return end
    pcall(function()
        local s = Instance.new("Sound")
        s.Name = "AspenSnd"
        s:SetAttribute("Aspen", true)
        s.SoundId = id
        s.Volume = math.clamp(vol, 0, 10)
        s.PlaybackSpeed = math.clamp(speed, 0.1, 3)
        if start and start > 0 then
            s.Parent = SoundService
            s.TimePosition = start
            s.Ended:Connect(function() pcall(function() s:Destroy() end) end)
            s:Play()
            task.delay(15, function() if s.Parent then pcall(function() s:Destroy() end) end end)
        else
            s.PlayOnRemove = true
            s.Parent = SoundService
            s:Destroy()
        end
    end)
end

---------------------------------------------------------------- shoot sound (UE style: one sound, volume, speed, start offset)
local playedAt = {hook = -1, ammo = -1}
local function shotEvent(src)
    local now = os.clock()
    local other = src == "ammo" and "hook" or "ammo"
    if now - playedAt[other] < 0.12 then return end   -- same shot already handled by the other detector
    if now - playedAt[src] < 0.03 then return end
    playedAt[src] = now
    Core.lastShotAt = now
    if SHOT.enabled then play(resolve(SHOT.name, SHOT.custom), SHOT.volume, SHOT.speed, SHOT.start) end
end
Core.playShootSound = nil   -- rage no longer plays its own sound; its shots are picked up by the ammo detector like normal ones
Core.onShotSent = function() shotEvent("hook") end       -- called by the silent aim input hook for every real shot

-- detector 1: the game's StartShooting packet (manual shots)
local hooked = false
local function installShootObserver()
    if hooked then return true end
    local remote = Core.Shot and Core.Shot.remote()
    local en = Core.Shot and Core.Shot.enum("StartShooting")
    if not remote or not en or type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then return false end
    local old
    local ok = pcall(function()
        local fn = function(self, ...)
            if self == remote and getnamecallmethod() == "FireServer" then
                local _, action = ...
                if action == en then task.defer(shotEvent, "hook") end
            end
            return old(self, ...)
        end
        if type(newcclosure) == "function" then fn = newcclosure(fn) end
        old = hookmetamethod(game, "__namecall", fn)
    end)
    hooked = ok
    return ok
end
task.spawn(function()
    for _ = 1, 60 do
        if installShootObserver() or Core.unloaded then break end
        task.wait(1)
    end
end)

-- detector 2: equipped gun ammo going down (catches every real shot, whatever fired it)
do
    local lastId, lastAmmo
    track(RunSvc.Heartbeat:Connect(function()
        local f = Core.myFighter and Core.myFighter()
        local it = f and rawget(f, "EquippedItem")
        local data = type(it) == "table" and rawget(it, "Data")
        local ammo = type(data) == "table" and data.Ammo
        local id = type(data) == "table" and data.ObjectID
        if type(ammo) ~= "number" then lastId, lastAmmo = nil, nil return end
        if id == lastId and lastAmmo and ammo < lastAmmo and lastAmmo - ammo <= 3 then shotEvent("ammo") end
        lastId, lastAmmo = id, ammo
    end))
end

---------------------------------------------------------------- hit sound (Kicia style: DamageNumberEffect replicate hook)
local function playHit(head)
    if not HIT.enabled then return end
    local name, vol, pit = HIT.body, HIT.bv, HIT.bp
    if head then name, vol, pit = HIT.head, HIT.hv, HIT.hp end
    play(resolve(name, HIT.custom), vol, pit)
end

local function myObjectId()
    local f = Core.myFighter and Core.myFighter()
    if type(f) ~= "table" then return nil end
    local id
    pcall(function()
        local st = rawget(f, "FighterState")
        id = (type(st) == "table" and (rawget(st, "ObjectId") or st.ObjectId)) or rawget(f, "ObjectId") or rawget(f, "ObjectID")
        if not id then local d = rawget(f, "Data"); if type(d) == "table" then id = d.ObjectID or d.ObjectId end end
    end)
    return id
end

local hitHooked, rcRef, rcOrig = false, nil, nil
local function installHitHook()
    if hitHooked then return true end
    local ok = pcall(function()
        local rc = require(player.PlayerScripts.Modules.ReplicatedController)
        local orig = rawget(rc, "_ObjectChanged")
        local enc = Core.Shot and Core.Shot.enum("DamageNumberEffect")
        if type(orig) ~= "function" or enc == nil then error("missing") end
        rcRef, rcOrig = rc, orig
        rawset(rc, "_ObjectChanged", function(self, objId, e, ...)
            if e == enc and type(objId) == "string" and HIT.enabled then
                local args = table.pack(...)
                pcall(function()
                    local mine = myObjectId()
                    if mine and objId ~= mine then return end
                    if not mine and os.clock() - (Core.lastShotAt or -100) > 3 then return end
                    local inst = args[1]
                    local par = typeof(inst) == "Instance" and inst.Parent
                    if par and par == player.Character then return end
                    task.defer(playHit, args[3] == true)
                end)
            end
            return coroutine.wrap(orig)(self, objId, e, ...)
        end)
        hitHooked = true
    end)
    return ok and hitHooked
end
task.spawn(function()
    for _ = 1, 60 do
        if installHitHook() or Core.unloaded then break end
        task.wait(1)
    end
end)

-- mute the game's own hitmarker sound
local cvmRef, cvmOrig
local function setMute(on)
    pcall(function()
        if not cvmRef then
            cvmRef = require(player.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ClientViewModel)
        end
        if on then
            if cvmOrig == nil then
                cvmOrig = rawget(cvmRef, "PlayHitmarkerSound")
                if cvmOrig then rawset(cvmRef, "PlayHitmarkerSound", function() end) end
            end
        elseif cvmOrig ~= nil then
            rawset(cvmRef, "PlayHitmarkerSound", cvmOrig)
            cvmOrig = nil
        end
    end)
end

task.spawn(function()
    while not Core.unloaded do task.wait(1) end
    setMute(false)
    if hitHooked and rcRef and rcOrig then pcall(rawset, rcRef, "_ObjectChanged", rcOrig) end
end)

---------------------------------------------------------------- mute the game's own gun sound (your viewmodel / character only)
local MUTE_SHOT = false
local GUN_WORDS = {"shoot", "fire", "shot", "gunshot", "blast", "bang", "minigun", "laser", "launch", "muzzle"}
local KEEP_WORDS = {"reload", "equip", "aim", "empty", "hit", "kill", "ricochet", "impact", "step", "walk", "land", "jump", "dry", "click", "pump", "cock", "mag"}
local function isGunSound(s)
    if not s:IsA("Sound") or s:GetAttribute("Aspen") then return false end
    local n = s.Name:lower()
    for _, w in ipairs(KEEP_WORDS) do if n:find(w, 1, true) then return false end end
    for _, w in ipairs(GUN_WORDS) do if n:find(w, 1, true) then return true end end
    return false
end
local muted = setmetatable({}, {__mode = "k"})
local function muteGun(s)
    if not MUTE_SHOT or not isGunSound(s) then return end
    pcall(function()
        if not muted[s] then
            muted[s] = s.Volume
            track(s:GetPropertyChangedSignal("Volume"):Connect(function()
                if MUTE_SHOT and s.Volume > 0 then s.Volume = 0 end
            end))
            track(s.Played:Connect(function() if MUTE_SHOT then s.Volume = 0; s:Stop() end end))
        end
        s.Volume = 0
        if s.Playing then s:Stop() end
    end)
end
local function scanMute(root)
    for _, d in ipairs(root:GetDescendants()) do muteGun(d) end
end
local function watchMuteRoot(root)
    if not root then return end
    track(root.DescendantAdded:Connect(function(d) task.defer(muteGun, d) end))
end
watchMuteRoot(Workspace.CurrentCamera)
track(Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function() watchMuteRoot(Workspace.CurrentCamera) end))
local function watchChar(ch) watchMuteRoot(ch) end
watchChar(player.Character)
track(player.CharacterAdded:Connect(watchChar))
local function setMuteShot(on)
    MUTE_SHOT = on
    if on then
        if Workspace.CurrentCamera then scanMute(Workspace.CurrentCamera) end
        if player.Character then scanMute(player.Character) end
    else
        for s, vol in pairs(muted) do pcall(function() if s.Parent then s.Volume = vol end end) end
    end
end

