pct(nil, "Reduce Recoil", "rec", "Recoil Reduction (%)", 0, 100, 75, "recPct")
wmod.Toggle("Remove Spread", false, function(v) M.spread = v == true; refreshHook() end)
wmod.Toggle("Automatic Fire", false, function(v) M.auto = v == true end)
pct(nil, "Aim Speed Override", "aim", "Aim Speed (%)", 50, 500, 200, "aimPct")
wmod.Section("Cooldowns")
pct(nil, "Fire Cooldown Override", "fire", "Fire Cooldown (%)", 0, 100, 25, "firePct")
pct(nil, "Aim Cooldown Override", "aimCd", "Aim Cooldown (%)", 1, 100, 50, "aimCdPct")
pct(nil, "Melee Cooldown Override", "melee", "Melee Cooldown (%)", 0, 100, 25, "meleePct")
pct(nil, "Dash Cooldown Override", "dash", "Dash Cooldown (%)", 0, 100, 25, "dashPct")
wmod.Section("Melee")
wmod.Toggle("Always Backstab", false, function(v) SA.mm.back = v == true; refreshHook() end)
wmod.Toggle("Extend Melee Range", false, function(v) SA.mm.range = v == true; refreshHook() end)
wmod.Slider("Melee Range", 5, 500, 10, function(v) SA.mm.rangeV = v end, 1)
wmod.Section("Grenades")
wmod.Toggle("Fuse Override", false, function(v) M.fuse = v == true; refreshHook() end)
wmod.Dropdown("Explode On", {"Impact", "Throw"}, "Impact", function(v) M.fuseOn = v end)
wmod.Toggle("Remove Fuse", false, function(v) M.noFuse = v == true; pcall(setNoFuse, M.noFuse); refreshHook() end)
wmod.Section("Movement")
wmod.Toggle("Infinite Double Jumps", false, function(v) M.jumps = v == true end)
end)() end


