local cT, cPos, cAng = 0, nil, 0
local function cFrame(dt)
local cam = Workspace.CurrentCamera
cRoot.Visible = C.on and cam ~= nil
if not cRoot.Visible then cPos = nil; return end
cT = cT + (dt)
local center = cam.ViewportSize / 2
local goal = center
if C.follow then
local sp = SA.tScreen
if not sp then
local rt = Core.rbTarget and Core.rbTarget()
if rt and rt.head then local v, on = cam:WorldToViewportPoint(rt.head.Position); if on then sp = Vector2.new(v.X, v.Y) end end
end
if sp then goal = sp end
end
if C.follow then
cPos = cPos or center
local d = (goal - cPos).Magnitude
if d <= C.fSnap then cPos = goal
else cPos = cPos:Lerp(goal, 1 - math.exp(-dt * C.fSpd / (1 + C.fDamp))) end
else cPos = center end
cHold.Position = UDim2.fromOffset(math.round(cPos.X), math.round(cPos.Y))
if C.rot then cAng = (cAng + dt * C.rotSpd) % 360 else cAng = 0 end
cHold.Rotation = C.angle + cAng
local gap = C.gap
if C.spread then gap = C.sMin + (C.sMax - C.sMin) * (0.5 + 0.5 * math.sin(cT * C.sSpd)) end
local st = C.style
local lines = st == "Lines" or st == "Lines + Circle" or st == "Lines + Diamond"
if C.pulse then gap = gap + math.abs(math.sin(cT * 3)) * C.pulseAmt end
local ccol = C.col
if C.cm == "Rainbow" then ccol = Color3.fromHSV((cT * C.cSpd * 0.2) % 1, 0.85, 1)
elseif C.cm == "Wave" then ccol = C.col:Lerp(C.colB, 0.5 + 0.5 * math.sin(cT * C.cSpd * 2))
elseif C.cm == "Pulse" then ccol = C.col:Lerp(Color3.new(0, 0, 0), 0.5 - 0.5 * math.sin(cT * C.cSpd * 4)) end
local ringOn = st == "Circle" or st == "Diamond" or st == "Lines + Circle" or st == "Lines + Diamond" or st == "Triple Ring"
local dia = st == "Diamond" or st == "Lines + Diamond"
local rr = C.rr + (C.pulse and math.abs(math.sin(cT * 3)) * C.pulseAmt or 0)
for i = 1, 3 do
local on = ringOn and (i == 1 or st == "Triple Ring")
cRings[i].Visible = on
if on then
local r = rr * (i == 1 and 1 or (i == 2 and 1.6 or 2.2))
cRings[i].Size = UDim2.fromOffset(r * 2, r * 2)
cRings[i].Rotation = dia and 45 or 0
local cr = cRings[i]:FindFirstChildOfClass("UICorner"); if cr then cr.CornerRadius = dia and UDim.new(0, 0) or UDim.new(1, 0) end
cRingStrokes[i].Color = ccol; cRingStrokes[i].Thickness = C.rth; cRingStrokes[i].Transparency = math.clamp(C.tr + (i - 1) * 0.25, 0, 1)
end
end
cGlow.Enabled = C.glow and ringOn; cGlow.Color = ccol; cGlow.Thickness = C.glowTh
local L, Th = C.len, C.th
local mid = gap + L / 2
