cBars[2].Size = UDim2.fromOffset(Th, L); cBars[2].Position = UDim2.fromOffset(0, mid)
cBars[3].Size = UDim2.fromOffset(L, Th); cBars[3].Position = UDim2.fromOffset(-mid, 0)
cBars[4].Size = UDim2.fromOffset(L, Th); cBars[4].Position = UDim2.fromOffset(mid, 0)
for i = 1, 4 do
