if C.txtOn then
cText.Text = C.txt; cText.TextSize = C.txtSize; cText.TextColor3 = C.txtCM and ccol or C.txtCol; cText.TextTransparency = C.txtTr; cTextStroke.Enabled = C.txtOut; cTextStroke.Thickness = C.txtOutTh; cTextStroke.Color = C.txtOutCol
if Core.fontOf then cText.FontFace = Core.fontOf(C.txtFont) end
local tp = (C.follow and C.fMode == "Crosshair + Text") and cPos or center
local half = (lines and (gap + L) or (C.style == "Image" and C.imgSize / 2 or 4))
cText.Position = UDim2.fromOffset(math.round(tp.X), math.round(tp.Y + C.txtOff))
end
end
pcall(function() RunService:UnbindFromRenderStep("AspenCrosshair") end)
RunService:BindToRenderStep("AspenCrosshair", Enum.RenderPriority.Camera.Value + 5, function(dt) pcall(cFrame, dt) end)


