-- ---- Kicia wireframe mesh generator (UGCValidationService -> EditableMesh -> edge ribbons) ----
local gti, sti = getthreadidentity, setthreadidentity
local function withId(fn)
    local old = gti and gti()
    if sti then pcall(sti, 8) end
    local ok, r = pcall(fn)
    if old and sti then pcall(sti, old) end
    return ok, r
end
local STYLES = {["Brush Stroke"] = {taper = 0.22, ridge = 0.45}, ["Chrome Tube"] = {taper = 0.6, ridge = 1.0}, ["Flat Ribbon"] = {taper = 1, ridge = 0}}
local cache, waiters = {}, {}
local function pk(v) return ("%.3f,%.3f,%.3f"):format(v.X, v.Y, v.Z) end
local function nOf(e) return e.Opposite == nil and -1 or e.Normal:Dot(e.Opposite) end
local function buildWire(meshId, width, crease, fallback, style)
    local UGC = game:GetService("UGCValidationService")
    if cloneref then UGC = cloneref(UGC) end
    local okB, bin = pcall(UGC.GetMeshDataBinaryString, UGC, meshId)
    if not okB then return fallback end
    local okE, em = pcall(UGC.CreateEditableMeshFromBinaryStringRobloxOnly, UGC, bin)
    if not okE or em == nil then return fallback end
    local faces = {}
    for i, f in ipairs(em:GetFaces()) do
        local fv = em:GetFaceVertices(f)
        if #fv >= 3 then
            local ps = {}
            for k, v in ipairs(fv) do ps[k] = em:GetPosition(v) end
            local n = (ps[2] - ps[1]):Cross(ps[3] - ps[1])
            if not (n.Magnitude < 1e-6) then faces[#faces + 1] = {FaceId = f, Verts = fv, Positions = ps, Normal = n.Unit} end
        end
        if i % 3000 == 0 then task.wait() end
    end
    for _, f in ipairs(faces) do em:RemoveFace(f.FaceId) end
    em:RemoveUnused()
    local map, edges = {}, {}
    for i, f in ipairs(faces) do
        local n = #f.Verts
        for k = 1, n do
            local k2 = k % n + 1
            local a, b = f.Positions[k], f.Positions[k2]
            local ka, kb = pk(a), pk(b)
            local key = ka .. "|" .. kb
            if kb < ka then key = kb .. "|" .. ka end
            local e = map[key]
            if e == nil then
                e = {PointA = a, PointB = b, Normal = f.Normal, Opposite = nil}
                map[key] = e; edges[#edges + 1] = e
            elseif e.Opposite == nil then e.Opposite = f.Normal end
        end
        if i % 3000 == 0 then task.wait() end
    end
    local cosC = math.cos(math.rad(crease))
    local keep = {}
    for _, e in ipairs(edges) do if nOf(e) < cosC then keep[#keep + 1] = e end end
    local tp, rd = style.taper, style.ridge
    local trisPer = (rd > 0) and 8 or ((tp < 1) and 4 or 2)
    local cap = math.min(10000, math.floor(24000 / trisPer))
    if #keep > cap then
        table.sort(keep, function(x, y) return nOf(x) < nOf(y) end)
        for i = #keep, cap + 1, -1 do keep[i] = nil end
    end
    if #keep == 0 then return fallback end
    local hw = width * 0.5
    for _, e in ipairs(keep) do
        local d = e.PointB - e.PointA
        if not (d.Magnitude < 1e-6) then
            local side = e.Normal:Cross(d.Unit)
            if not (side.Magnitude < 1e-6) then
                local u = side.Unit
                local nrm = e.Normal
                local off = nrm * 0.001
                local function build(withRidge)
                    local A, B = e.PointA, e.PointB
                    local secs
                    if tp < 1 then secs = {{A, hw * tp}, {(A + B) * 0.5, hw}, {B, hw * tp}} else secs = {{A, hw}, {B, hw}} end
                    local rows = {}
                    for i, sc in ipairs(secs) do
                        local pt, w = sc[1], sc[2]
                        local l = em:AddVertex(pt - u * w + off)
                        local c = withRidge and em:AddVertex(pt + off + nrm * (w * rd)) or nil
                        local r = em:AddVertex(pt + u * w + off)
                        for _ = 1, withRidge and 3 or 2 do em:AddColor(Color3.new(1, 1, 1), 1) end
                        rows[i] = {l, c, r}
                    end
                    for i = 1, #rows - 1 do
                        local a, b = rows[i], rows[i + 1]
                        if withRidge then
                            em:AddTriangle(a[1], a[2], b[2]); em:AddTriangle(a[1], b[2], b[1])
                            em:AddTriangle(a[2], a[3], b[3]); em:AddTriangle(a[2], b[3], b[2])
                        else
                            em:AddTriangle(a[1], a[3], b[3]); em:AddTriangle(a[1], b[3], b[1])
                        end
                    end
                end
                if not pcall(build, rd > 0) then
                    if not pcall(build, false) then break end
                end
            end
        end
    end
    return Content.fromObject(em)
end
local function getWire(meshId, width, crease, fallback, styleName, cb)
    local key = meshId .. "|" .. string.format("%.5f", width) .. "|" .. crease .. "|" .. styleName
    local c = cache[key]
    if c ~= nil then cb(c); return end
    if waiters[key] then table.insert(waiters[key], cb); return end
    waiters[key] = {cb}
    task.spawn(function()
        local res = fallback
        withId(function() res = buildWire(meshId, width, crease, fallback, STYLES[styleName] or STYLES["Brush Stroke"]) end)
        cache[key] = res
        local w = waiters[key]; waiters[key] = nil
        for _, f in ipairs(w or {}) do pcall(f, res) end
    end)
end
local function partRatio(p)
    local ms, s, n, c = p.MeshSize, p.Size, 0, 0
    for _, pr in ipairs({{ms.X, s.X}, {ms.Y, s.Y}, {ms.Z, s.Z}}) do
        if pr[2] > 1e-6 then n = n + pr[1] / pr[2]; c = c + 1 end
    end
    return c == 0 and 1 or n / c
end

-- ---- per-part state + Kicia viewmodel collector (item.ViewModel.Model -> ItemVisual / LeftArm / RightArm) ----
local wires = {}            -- [part] = state
local extras = {}           -- [root] = {hl = Highlight, light = PointLight}
local MATS = {["Chrome (Mirror)"] = Enum.Material.Metal, Neon = Enum.Material.Neon, ForceField = Enum.Material.ForceField, Glass = Enum.Material.Glass, Metal = Enum.Material.Metal}
local function applyPart(part, grp, root)
    local st = wires[part]
    if not st then
        local okM, mc = pcall(function() return part.MeshContent end)
        st = {grp = grp, root = root, meshId = part.MeshId, content = okM and mc or nil, color = part.Color, mat = part.Material, refl = part.Reflectance, trans = part.Transparency, busy = false, ver = -1}
        wires[part] = st
        -- only forget a part when the game really destroys it (never because it was missing for a moment)
        st.conn = part.Destroying:Once(function() if wires[part] == st then wires[part] = nil end end)
    end
    st.grp, st.root = grp, root
    if st.busy then return end
    st.busy = true
    local ver = C.ver
    getWire(st.meshId, G[grp].width * partRatio(part), C.crease, st.content, C.style, function(content)
        if wires[part] == st then
            if content ~= nil then
                withId(function() part.MeshContent = content; part.Color = G[grp].col end)
                st.wire = content
                local okO, obj = pcall(function() return content.Object end)
                st.wireObj = okO and obj or nil
            end
            st.ver = ver
        end
        st.busy = false
    end)
end
-- if the game puts its own mesh back on a wired part (reload / equip / animation), put the wireframe back in the same frame
local function enforce(part, st)
    if st.busy or st.ver ~= C.ver or not st.wireObj or not part.Parent then return end
    local okC, cur = pcall(function() return part.MeshContent end)
    if not okC then return end
    local okO, obj = pcall(function() return cur.Object end)
    if okO and obj == st.wireObj then return end
    local mid = part.MeshId
    if mid ~= "" and mid ~= st.meshId then
        -- the game swapped in a different mesh (new skin / part): rebuild the wire for it
        st.meshId = mid; st.content = cur; st.wire = nil; st.wireObj = nil; st.ver = -1
        return
    end
    withId(function() part.MeshContent = st.wire; part.Color = G[st.grp].col end)
end
local function dropExtras(root)
    local e = extras[root]
    if not e then return end
    extras[root] = nil
    pcall(function() if e.hl then e.hl:Destroy() end end)
    pcall(function() if e.fold then e.fold:Destroy() end end)
    pcall(function() if e.light then e.light:Destroy() end end)
end
local function removePart(part, st, restore)
    wires[part] = nil
    if st.conn then pcall(function() st.conn:Disconnect() end) end
    if restore and part.Parent then
        withId(function()
            if st.content ~= nil then part.MeshContent = st.content end
            part.Color = st.color; part.Material = st.mat; part.Transparency = st.trans; if st.refl ~= nil then part.Reflectance = st.refl end
        end)
    end
end
local function collect()
    local out = {}
    local f = Core.myFighter and Core.myFighter()
    local items = f and rawget(f, "Items")
    if type(items) ~= "table" then return out end
    for _, it in pairs(items) do
        local okV, vm = pcall(function() return rawget(it, "ViewModel") or it.ViewModel end)
        local okM, model = pcall(function() return vm and (rawget(vm, "Model") or vm.Model) end)
        if okV and okM and typeof(model) == "Instance" then
            for _, ch in ipairs(model:GetChildren()) do
                local grp = (ch.Name == "ItemVisual" and "Items") or ((ch.Name == "LeftArm" or ch.Name == "RightArm") and "Arms") or nil
                if grp and G[grp].on then
                    local list = {}
                    if ch:IsA("MeshPart") then list[1] = ch end
                    for _, d in ipairs(ch:GetDescendants()) do if d:IsA("MeshPart") then list[#list + 1] = d end end
                    for _, p in ipairs(list) do
                        if not p:GetAttribute("AspenProxy") and (p.MeshId ~= "" or wires[p]) then out[p] = {grp = grp, root = ch} end
                    end
                end
            end
        end
    end
    return out
end
local function scan()
    local want = collect()
    -- Wired parts stay wired for as long as the toggle is on. They are only restored when the toggle is turned off
    -- (a part that is briefly missing from the viewmodel collector is left alone, that was the blinking).
    for part, st in pairs(wires) do
        if want[part] then
            enforce(part, st)
        elseif not G[st.grp].on then
            removePart(part, st, true)
        end
    end
    for part, info in pairs(want) do
        local st = wires[part]
        if not st or (st.ver ~= C.ver and not st.busy) then
            applyPart(part, info.grp, info.root)
        else
            st.grp, st.root = info.grp, info.root
        end
    end
    -- drop glow helpers for roots that have no wired parts left
    local live = {}
    for _, st in pairs(wires) do if st.root then live[st.root] = true end end
    for root in pairs(extras) do if not live[root] or not root.Parent then dropExtras(root) end end
end

-- ---- per-frame: colour modes, material, transparency, outline of the real weapon shape, glow light ----
local t0 = os.clock()
local function colourFor(grp, now)
    local base = C.accent and (T and T.Accent) or G[grp].col
    local sp = C.speed
    if C.mode == "Rainbow" then return Color3.fromHSV((now * sp * 0.2) % 1, 0.85, 1)
    elseif C.mode == "Pulse" then local k = 0.3 + 0.7 * (0.5 + 0.5 * math.sin(now * sp * 3)); return Color3.new(base.R * k, base.G * k, base.B * k)
    elseif C.mode == "Gradient" then return base:Lerp(C.col2, 0.5 + 0.5 * math.sin(now * sp * 2)) end
    return base
end
local function outOK(grp) return C.outFor == "Both" or (C.outFor == "Weapon Only" and grp == "Items") or (C.outFor == "Arms Only" and grp == "Arms") end
local bloom
local function setBloom(on, br)
    if on then
        if not bloom or not bloom.Parent then
            bloom = Instance.new("BloomEffect"); bloom.Name = "AspenWireBloom"; bloom.Threshold = 0.85; bloom.Parent = Lighting
        end
        bloom.Enabled = true
        bloom.Intensity = math.clamp(br * 0.12, 0, 1.2)
        bloom.Size = math.clamp(10 + br * 3, 10, 40)
    elseif bloom then
        pcall(function() bloom:Destroy() end); bloom = nil
    end
end
-- brightness 0..10 -> (outline transparency, fill transparency, colour): 0-3 fades the glow in, 3-10 whitens the core and adds a soft fill
local function glowParams(br, base)
    local o = 1 - math.clamp(br / 3, 0, 1)
    local k = math.clamp((br - 3) / 7, 0, 1)
    return o, 1 - k * 0.4, base:Lerp(Color3.new(1, 1, 1), k * 0.6)
end
local function frame()
    if next(wires) == nil then return end
    local now = os.clock() - t0
    local cols = {Arms = colourFor("Arms", now), Items = colourFor("Items", now)}
    local mat = MATS[C.mat]
    local chrome = C.mat == "Chrome (Mirror)"
    local shiny = mat ~= nil and (chrome or C.mat == "Metal")
    local pulse = C.pulse and (0.5 + 0.5 * math.sin(now * 3)) or 0
    withId(function()
        for part, st in pairs(wires) do
            if part.Parent and not st.busy and st.ver == C.ver then
                local c = cols[st.grp]
                if chrome then c = c:Lerp(Color3.new(1, 1, 1), 0.35) end
                part.Color = c
                -- material / transparency are only touched when you picked one, otherwise the game keeps control of them
                if mat then
                    if part.Material ~= mat then part.Material = mat end
                    st.fMat = true
                elseif st.fMat then part.Material = st.mat; st.fMat = false end
                if shiny then
                    if part.Reflectance ~= C.shine then part.Reflectance = C.shine end
                    st.fRef = true
                elseif st.fRef then part.Reflectance = st.refl; st.fRef = false end
                if C.trans > 0 then
                    if part.Transparency ~= C.trans then part.Transparency = C.trans end
                    st.fTr = true
                elseif st.fTr then part.Transparency = st.trans; st.fTr = false end
            end
        end
    end)
    local seen = {}
    for part, st in pairs(wires) do
        local root = st.root
        if root and root.Parent and part.Parent and not st.busy and not seen[root] then
            seen[root] = true
            local e = extras[root]
            if C.light and st.grp == "Items" then
                if not e then e = {}; extras[root] = e end
                if not e.light or not e.light.Parent then
                    local ok, l = pcall(function() local l = Instance.new("PointLight"); l.Shadows = false; l.Parent = part; return l end)
                    e.light = ok and l or nil
                end
                if e.light then e.light.Color = cols.Items; e.light.Brightness = C.lightBr + pulse; e.light.Range = C.lightRange end
            elseif e and e.light then pcall(function() e.light:Destroy() end); e.light = nil end
        end
    end
end
-- ---- per-part glow: every part of the weapon / arms gets its own Highlight (outline mode), or every wired part gets one (wire glow) ----
local MAXH = 30
local outl = {}                  -- [part] = Highlight
local outParts, outScanAt = {}, -10
local function scanOutlineParts()
    local pools = {Items = {}, Arms = {}}
    local seen = {}
    local f = Core.myFighter and Core.myFighter()
    local items = f and rawget(f, "Items")
    if type(items) == "table" then
        for _, it in pairs(items) do
            local okV, vm = pcall(function() return rawget(it, "ViewModel") or it.ViewModel end)
            local okM, model = pcall(function() return vm and (rawget(vm, "Model") or vm.Model) end)
            if okV and okM and typeof(model) == "Instance" then
                for _, ch in ipairs(model:GetChildren()) do
                    local grp = (ch.Name == "ItemVisual" and "Items") or ((ch.Name == "LeftArm" or ch.Name == "RightArm") and "Arms") or nil
                    if grp and outOK(grp) then
                        local function add(q)
                            if q:IsA("BasePart") and not seen[q] and not q:GetAttribute("AspenProxy") and q.Transparency < 0.99 then
                                seen[q] = true; pools[grp][#pools[grp] + 1] = q
                            end
                        end
                        add(ch)
                        for _, d in ipairs(ch:GetDescendants()) do add(d) end
                    end
                end
            end
        end
    end
    local list = {}
    for _, q in ipairs(pools.Items) do list[#list + 1] = {q, "Items"} end
    for _, q in ipairs(pools.Arms) do list[#list + 1] = {q, "Arms"} end
    return list
end
local function outlineFrame()
    local now = os.clock() - t0
    local pulse = C.pulse and (0.5 + 0.5 * math.sin(now * 3)) or 0
    local mod = 1 + (pulse - 0.5) * 0.3
    local want, n, bloomBr = {}, 0, 0
    if C.glow then
        if now - outScanAt > 0.25 then outScanAt = now; outParts = scanOutlineParts() end
        for _, e in ipairs(outParts) do
            local q = e[1]
            if q.Parent and n < MAXH then n = n + 1; want[q] = {e[2], C.outBr * mod, C.outCol} end
        end
        bloomBr = math.max(bloomBr, C.outBr)
    end
    if C.wglow and C.wBr > 0 then
        for part, st in pairs(wires) do
            if part.Parent and st.wire and not st.busy and st.ver == C.ver and n < MAXH and not want[part] then
                n = n + 1; want[part] = {st.grp, C.wBr * mod, nil}
            end
        end
        bloomBr = math.max(bloomBr, C.wBr)
    end
    for part, info in pairs(want) do
        local h = outl[part]
        if not h or not h.Parent then
            local ok, nh = pcall(function()
                local nh = Instance.new("Highlight")
                nh.Name = "AspenGlow"; nh.DepthMode = Enum.HighlightDepthMode.Occluded; nh.Adornee = part; nh.Parent = part
                return nh
            end)
            h = ok and nh or nil
            outl[part] = h
        end
        if h then
            local o, fl, col = glowParams(info[2], info[3] or colourFor(info[1], now))
            h.OutlineColor = col; h.OutlineTransparency = o
            h.FillColor = col; h.FillTransparency = info[1] == "Items" and 0.7 or fl
        end
    end
    for part, h in pairs(outl) do
        if not want[part] or not part.Parent then pcall(function() h:Destroy() end); outl[part] = nil end
    end
    setBloom(C.bloom and next(want) ~= nil, bloomBr)
end
