local CHK = {ads = false, muzzle = false, overlay = false, reticle = false, tracers = false, hit = false}
local function gmodAt(root, ...)
local node = root
for _, n in ipairs({...}) do node = node and node:FindFirstChild(n) end
if not node then return nil end
local ok, m = pcall(require, node)
return ok and type(m) == "table" and m or nil
end
local CI = {"Modules", "ClientReplicatedClasses", "ClientFighter", "ClientItem"}
local function ciModP(extra)
local ps = player:FindFirstChild("PlayerScripts")
if not ps then return nil end
local path = {table.unpack(CI)}
for _, n in ipairs(extra) do path[#path + 1] = n end
return gmodAt(ps, table.unpack(path))
end

local function applyAds()
local m = ciModP({"ItemInterface", "Other"})
local upd = m and rawget(m, "Update")
if type(upd) == "function" and debug and debug.setconstant then pcall(debug.setconstant, upd, 2, CHK.ads and 999 or 1) end
end

local function applyMuzzle()
local m = ciModP({"ClientViewModel"})
local fn = m and rawget(m, "MuzzleFlash")
if type(fn) ~= "function" or not (debug and debug.getupvalue and debug.setupvalue) then return end
if CHK.muzzle and not CHK.mf then
local okU, old = pcall(debug.getupvalue, fn, 2)
if okU then CHK.mf = {fn = fn, up = old}; pcall(debug.setupvalue, fn, 2, {PlayParticles = function() end}) end
elseif not CHK.muzzle and CHK.mf then
pcall(debug.setupvalue, CHK.mf.fn, 2, CHK.mf.up); CHK.mf = nil
end
end

local function applyScope()
local sc = ciModP({"ItemInterface", "Mouse", "Scope"})
if not sc then return end
local want = CHK.overlay or CHK.reticle
if want and not CHK.sc then
local sa = rawget(sc, "SetActive")
if type(sa) ~= "function" then return end
CHK.sc = sa
rawset(sc, "SetActive", function(self, a)
coroutine.wrap(sa)(self, a)
if not rawget(self, "_is_scope_active") then return end
local cf, bf = rawget(self, "CircleFrame"), rawget(self, "BlurFrame")
if cf and bf then cf.Visible = not CHK.overlay; bf.Visible = not CHK.overlay end
local rc = rawget(self, "ReticleContainer")
if rc then rc.Visible = not CHK.reticle end
end)
elseif not want and CHK.sc then
rawset(sc, "SetActive", CHK.sc); CHK.sc = nil
end
end

local function applyTracers()
local ok, gun = pcall(function() return require(game:GetService("ReplicatedStorage").Modules.ItemTypes.Gun) end)
if not ok or type(gun) ~= "table" or not (debug and debug.getconstants and debug.setconstant) then return end
if CHK.tracers and not CHK.gt then
local fn = rawget(gun, "_LocalTracers")
if type(fn) ~= "function" then return end
for k, v in pairs(debug.getconstants(fn)) do
if v == "_Tracers" then
rawset(gun, "_Tracers\0NoGunTracers", function() end)
debug.setconstant(fn, k, "_Tracers\0NoGunTracers")
CHK.gt = {fn = fn, k = k, v = v}
return
end
end
elseif not CHK.tracers and CHK.gt then
pcall(debug.setconstant, CHK.gt.fn, CHK.gt.k, CHK.gt.v)
pcall(rawset, gun, "_Tracers\0NoGunTracers", nil)
CHK.gt = nil
end
end

CHK.hm = setmetatable({}, {__mode = "k"})
local function applyHit()
if not CHK.hit then return end
local pg = player:FindFirstChild("PlayerGui")
if not pg then return end
for _, d in ipairs(pg:GetDescendants()) do
if d.Name == "Hitmarker" and d:IsA("GuiObject") then
if d.Visible then d.Visible = false end
if not CHK.hm[d] then CHK.hm[d] = d:GetPropertyChangedSignal("Visible"):Connect(function() if CHK.hit and d.Visible then d.Visible = false end end) end
end
end
end
local function applyAll()
pcall(applyAds); pcall(applyMuzzle); pcall(applyScope); pcall(applyTracers); pcall(applyHit)
end
cs.Toggle("Hide ADS Vignette", false, function(v) CHK.ads = v == true; pcall(applyAds) end)
cs.Toggle("Hide Muzzle Flash", false, function(v) CHK.muzzle = v == true; pcall(applyMuzzle) end)
cs.Toggle("Hide Scope Overlay", false, function(v) CHK.overlay = v == true; pcall(applyScope) end)
cs.Toggle("Hide Scope Reticle", false, function(v) CHK.reticle = v == true; pcall(applyScope) end)
cs.Toggle("Hide Gun Tracers", false, function(v) CHK.tracers = v == true; pcall(applyTracers) end)
cs.Toggle("Hide Hitmarker", false, function(v) CHK.hit = v == true; pcall(applyHit) end)
task.spawn(function()
while not Core.unloaded do
task.wait(2)
if CHK.ads or CHK.muzzle or CHK.overlay or CHK.reticle or CHK.tracers or CHK.hit then applyAll() end
end
end)
end
