if part then
if AR.tint and part.Color ~= AR.color then pcall(function() part.Color = AR.color end) end
if AR.reflOn and math.abs(part.Reflectance - AR.refl) > 0.001 then pcall(function() part.Reflectance = AR.refl end) end
end
end
end
end
end
end)

local function setAuto(v)
