task.delay(0.25, function() if d.Parent then process(d) end end)
end
end)
end
end

local function restoreScan()
local ORIG = "rbxassetid://" .. TARGET
task.spawn(function()
pcall(function()
local n = 0
local cam = Workspace.CurrentCamera
for _, top in ipairs(Workspace:GetChildren()) do
if top ~= cam and not top:IsA("Terrain") and not Players:GetPlayerFromCharacter(top) then
local list = top:GetDescendants()
list[#list + 1] = top
for _, d in ipairs(list) do
local prop = PROPS[d.ClassName]
if prop then
local ok, cur = pcall(function() return d[prop] end)
if ok and applied[cur] then pcall(function() d[prop] = ORIG end) end
end
n = n + (1)
if n % 2000 == 0 then task.wait() end
end
end
end
end)
end)
end
local function restoreTexture()
for inst, rec in pairs(tracked) do
if inst.Parent then pcall(function() inst[PROPS[inst.ClassName]] = rec.orig end) end
end
restoreScan()
end
local function resetAll()
restoreScan()
for inst, rec in pairs(tracked) do
if inst.Parent then
local prop = PROPS[inst.ClassName]
pcall(function() inst[prop] = rec.orig end)
if rec.tint ~= nil then pcall(writeTint, inst, rec.tint) end
end
end
for part, r in pairs(partRec) do
if part.Parent then pcall(function() part.Color = r.color; part.Reflectance = r.refl end) end
end
end

local function revertColor()
for part, r in pairs(partRec) do if part.Parent then pcall(function() part.Color = r.color end) end end
for inst, rec in pairs(tracked) do if inst.Parent and rec.tint ~= nil then pcall(writeTint, inst, rec.tint) end end
end
local function revertRefl()
for part, r in pairs(partRec) do if part.Parent then pcall(function() part.Reflectance = r.refl end) end end
end
