local names = {}
for n in pairs(SKY) do names[#names + 1] = n end
table.sort(names)
do
local function variant(name, base, over)
if not SKY[base] then return end
local t = {}
for k, v in pairs(SKY[base]) do t[k] = v end
for k, v in pairs(over) do t[k] = v end
SKY[name] = t
if not table.find(names, name) then names[#names + 1] = name end
table.sort(names)
end
