local sk = addSub(mWorld, "Skyboxes", "Skybox presets plus fully custom skies: asset ids or raw links for each face.")
local Lighting = game:GetService("Lighting")
local cur, on, useCustom = names[1], false, false
local custom = {SkyboxUp = "", SkyboxDn = "", SkyboxFt = "", SkyboxBk = "", SkyboxLf = "", SkyboxRt = ""}
local customRes = {}
local saved, mine
local faces = {"SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp", "StarCount", "SunAngularSize", "MoonAngularSize", "SunTextureId", "MoonTextureId"}
local urlCache, urlFail, urlN = {}, {}, 0
local function resolveAsset(t)
t = tostring(t or ""):gsub("^%s+", ""):gsub("%s+$", "")
if t == "" then return nil end
local low = t:lower()
if low:sub(1, 4) == "http" and not low:find("roblox.com") then
if urlCache[t] then return urlCache[t] end
if urlFail[t] and os.clock() - urlFail[t] < 8 then return nil end
local got
pcall(function()
local data = game:HttpGet(t)
if type(data) == "string" and #data > 100 and type(writefile) == "function" and type(getcustomasset) == "function" then
pcall(function() if makefolder then makefolder("Aspen"); makefolder("Aspen/Assets") end end)
urlN = urlN + 1
local path = "Aspen/Assets/sky_" .. urlN .. "_" .. math.floor(os.clock() * 1000) .. ".png"
writefile(path, data)
got = getcustomasset(path)
end
end)
if got then urlCache[t] = got else urlFail[t] = os.clock() end
return got
end
if low:find("^rbxassetid://") or low:find("^rbxasset://") or low:find("^rbxthumb://") then return t end
local d = t:match("^(%d+)$") or t:match("[?&]id=(%d+)") or t:match("/asset/(%d+)") or t:match("/(%d+)/?$")
return d and ("rbxassetid://" .. d) or nil
end
local function getSky()
local sky = Lighting:FindFirstChildOfClass("Sky")
if not sky then sky = Instance.new("Sky"); sky.Name = "AspenSky"; sky.Parent = Lighting; mine = sky end
return sky
end
local function apply()
if not (on or useCustom) then return end
local d = {}
if on and SKY[cur] then for k, v in pairs(SKY[cur]) do d[k] = v end end
if useCustom then for k, v in pairs(customRes) do if v then d[k] = v end end end
local sky = getSky()
if not saved then saved = {}; for _, k in ipairs(faces) do pcall(function() saved[k] = sky[k] end) end end
for _, k in ipairs(faces) do if d[k] ~= nil then pcall(function() if sky[k] ~= d[k] then sky[k] = d[k] end end) end end
end
local function revert()
local sky = Lighting:FindFirstChildOfClass("Sky")
if sky and saved then for k, v in pairs(saved) do pcall(function() sky[k] = v end) end end
saved = nil
if mine and mine.Parent then mine:Destroy() end
mine = nil
end
local previewGui, refreshPreview
local function refresh() if on or useCustom then pcall(apply) else revert() end; if previewGui and previewGui.Parent and refreshPreview then pcall(refreshPreview) end end
local function resolveAll()
task.spawn(function()
for k, v in pairs(custom) do customRes[k] = resolveAsset(v) end
refresh()
end)
end
sk.Section("Skybox Presets")
sk.Toggle("Use Sky Preset", false, function(v) on = v == true; refresh() end)
sk.Dropdown("Sky", names, names[1], function(v) cur = v; if on then pcall(apply) end; if previewGui and previewGui.Parent then pcall(refreshPreview) end end)
