sk.Hint("Paste a Roblox asset id, rbxassetid:// link or a raw link (e.g. GitHub raw .png) for each face. Raw links need an executor with writefile and getcustomasset.")
sk.Toggle("Use Custom Faces", false, function(v) useCustom = v == true; if useCustom then resolveAll() else refresh() end end)
