local th_, ts, tv = (p[4] or TXT):ToHSV()
local t2 = Color3.fromHSV(th_, math.min(ts, 0.12), math.max(tv, 0.94))
return mk(a2, b2, t2, h2)
end
return mk(p[1], p[2], p[4] or TXT, p[3])
end
