Mono            = {glow = 0.86, pulse = nil, border = "comet", bspeed = 10, bar = "static", barT = 0, wash = 0.96, angle = 90, corners = false},
Prism           = {glow = 0.64, pulse = 3, border = "prism", bspeed = 8, bar = "prism", barT = 3, wash = 0.9, angle = 30, corners = true, spin = 35},
Custom          = {glow = 0.78, pulse = 4,   border = "flow",  bspeed = 10, bar = "sweep",   barT = 4,   wash = 0.93, angle = 40,  corners = true},
}
Core.ThemeStyles = STYLE
local tweens = {}
local function stopAll() for _, t in ipairs(tweens) do pcall(function() t:Cancel() end) end; tweens = {} end
local function loop(o, props, t, rev, style)
    if Core.FXStill then return end
    local tw = TS:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, rev or false), props)
    tw:Play(); tweens[#tweens + 1] = tw
end
local outer = make("ImageLabel", {Name = "ThemeGlow", BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = T.Accent,
    ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, 96, 1, 96), ZIndex = 0, Visible = false, Active = false}, holder)
local wash = make("Frame", {Name = "ThemeWash", BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 20, Active = false, Visible = false}, win)
local washG = make("UIGradient", {Name = "NoTheme"}, wash)
local bar = make("Frame", {Name = "ThemeBar", BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 2), ZIndex = 30, Active = false, Visible = false}, win)
local barG = make("UIGradient", {Name = "NoTheme"}, bar)
local c1 = make("ImageLabel", {Name = "ThemeCornerA", BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(0, 0), Size = UDim2.fromOffset(340, 340), ZIndex = 19, Active = false, Visible = false}, win)
local c2 = make("ImageLabel", {Name = "ThemeCornerB", BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
    Position = UDim2.fromScale(1, 1), Size = UDim2.fromOffset(340, 340), ZIndex = 19, Active = false, Visible = false}, win)
local cur = STYLE["Aspen"]
local function vis()
    local v = win.Visible
    outer.Visible = v and cur.glow ~= nil
    wash.Visible = v and cur.wash ~= nil
    bar.Visible = v and cur.bar ~= nil
    c1.Visible = false
    c2.Visible = false
end
win:GetPropertyChangedSignal("Visible"):Connect(vis)
local function CS(...) return ColorSequence.new({...}) end
local K = ColorSequenceKeypoint.new
Core.ThemeStyle = function(name)
    local st = STYLE[name] or STYLE.Custom
    cur = st
    stopAll()
    local A, H = T.Accent, T.AccentHi
    local MIX = A:Lerp(H, 0.5)
    local WHT = Color3.new(1, 1, 1)
    local I = Core.FXI or 1
    local function amp(x) if not x then return nil end return math.clamp(1 - (1 - x) * I, 0, 1) end
    local N = NumberSequenceKeypoint.new
    local function rainbow(s, v)
        local ks = {}
        for i = 0, 6 do ks[#ks + 1] = K(i / 6, Color3.fromHSV((i / 6) % 1, s, v)) end
        return ColorSequence.new(ks)
    end

    outer.ImageColor3 = A
    outer.ImageTransparency = amp(st.glow) or 1
    if st.glow and st.pulse then loop(outer, {ImageTransparency = math.min(1, amp(st.glow) + 0.1)}, st.pulse, true) end

    winGrad.Rotation = 0
    winGrad.Transparency = NumberSequence.new(0)
    if st.border == "solid" then
        winGrad.Enabled = false; winStroke.Color = A; winStroke.Thickness = 1.2; winStroke.Transparency = 0.25
    else
        winGrad.Enabled = true; winStroke.Transparency = 0.35
        winStroke.Thickness = (st.border == "dual" and 1.6) or (st.border == "flow" and 1.2) or 1.8
        if st.border == "dual" then winGrad.Color = CS(K(0, A), K(0.42, A), K(0.5, H), K(0.62, H), K(0.7, A), K(1, A))
        elseif st.border == "comet" then
            winGrad.Color = CS(K(0, A), K(0.6, A), K(0.82, H), K(0.93, WHT:Lerp(H, 0.25)), K(1, A))
            winGrad.Transparency = NumberSequence.new({N(0, 0.78), N(0.6, 0.78), N(0.93, 0), N(1, 0.78)})
            winStroke.Transparency = 0.08
        elseif st.border == "tri" then winGrad.Color = CS(K(0, A), K(0.33, H), K(0.66, WHT:Lerp(MIX, 0.55)), K(1, A))
        elseif st.border == "chrome" then
            local D = A:Lerp(Color3.new(0, 0, 0), 0.55)
            local HL = H:Lerp(WHT, 0.3)
            winGrad.Color = CS(K(0, D), K(0.18, A), K(0.32, HL), K(0.46, D), K(0.62, A), K(0.78, HL), K(0.9, A), K(1, D))
            winStroke.Transparency = 0.05; winStroke.Thickness = 2
        elseif st.border == "prism" then winGrad.Color = rainbow(0.55, 1); winStroke.Transparency = 0.2
        else winGrad.Color = CS(K(0, A), K(0.33, H), K(0.66, A), K(1, A)) end
        loop(winGrad, {Rotation = 360}, st.bspeed > 0 and st.bspeed or 10, false, Enum.EasingStyle.Linear)
    end

    if st.wash then
        local w = amp(st.wash)
        wash.BackgroundColor3 = WHT
        washG.Rotation = st.angle or 35
        if st.border == "chrome" then
            local D = A:Lerp(Color3.new(0, 0, 0), 0.35)
            local HL = H:Lerp(WHT, 0.2)
            washG.Color = CS(K(0, HL), K(0.3, D), K(0.5, HL), K(0.72, D), K(1, HL))
            washG.Transparency = NumberSequence.new({N(0, w), N(0.3, math.max(w, 0.96)), N(0.5, w - 0.04), N(0.72, math.max(w, 0.97)), N(1, w)})
        else
        washG.Color = CS(K(0, A), K(0.55, MIX), K(1, H))
        washG.Transparency = NumberSequence.new({N(0, w), N(0.5, math.max(w, 0.985)), N(1, w + (1 - w) * 0.4)})
        end
        if st.spin then loop(washG, {Rotation = (st.angle or 35) + 360}, st.spin, false, Enum.EasingStyle.Linear) end
    end

    bar.BackgroundTransparency = 0
    barG.Offset = Vector2.new(0, 0)
    if st.bar == "sweep" then
        barG.Color = CS(K(0, A), K(0.5, H), K(1, A))
        barG.Transparency = NumberSequence.new({N(0, 1), N(0.5, 0.05), N(1, 1)})
        barG.Offset = Vector2.new(-1, 0)
        loop(barG, {Offset = Vector2.new(1, 0)}, st.barT, false, Enum.EasingStyle.Quad)
    elseif st.bar == "twin" then
        barG.Color = CS(K(0, A), K(0.5, H), K(1, A))
        barG.Transparency = NumberSequence.new({N(0, 1), N(0.2, 0.08), N(0.4, 1), N(0.6, 1), N(0.8, 0.08), N(1, 1)})
        barG.Offset = Vector2.new(-1, 0)
        loop(barG, {Offset = Vector2.new(1, 0)}, st.barT, false, Enum.EasingStyle.Quad)
    elseif st.bar == "prism" then
        barG.Color = rainbow(0.5, 1)
        barG.Transparency = NumberSequence.new({N(0, 0.5), N(0.5, 0.05), N(1, 0.5)})
        barG.Offset = Vector2.new(-0.25, 0)
        loop(barG, {Offset = Vector2.new(0.25, 0)}, (st.barT or 3) + 2, true)
    elseif st.bar == "breathe" then
        barG.Color = CS(K(0, A), K(0.5, H), K(1, A)); barG.Transparency = NumberSequence.new(0.1)
        bar.BackgroundTransparency = 0.1
        loop(bar, {BackgroundTransparency = 0.75}, st.barT, true)
    else
        barG.Color = CS(K(0, A), K(0.5, H), K(1, A)); barG.Transparency = NumberSequence.new({N(0, 0.7), N(0.5, 0.1), N(1, 0.7)})
    end

    c1.ImageColor3 = H; c2.ImageColor3 = A
    c1.ImageTransparency = 1; c2.ImageTransparency = 1
    if false then
        loop(c1, {ImageTransparency = amp(0.93)}, (st.pulse or 4) + 1, true)
        loop(c2, {ImageTransparency = amp(0.95)}, (st.pulse or 4) + 2, true)
    end
    vis()
end
end, function(e) warn("[Aspen] theme style failed: " .. tostring(e)) end)

local function wheelTo(kr, kg, kb, vMin, vMax)
return function(hexv)
local ok, c = pcall(Color3.fromHex, hexv)
if not ok then return end
local hh, ss, vv = c:ToHSV()
c = Color3.fromHSV(hh, ss, math.clamp(vv, vMin, vMax))
if kr == "AR" then cust.hi = nil end
cust[kr], cust[kg], cust[kb] = math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)
if curPreset == "Custom" then queue() end
end
end
