local draft = {acc = Color3.fromRGB(104, 100, 142), hi = Color3.fromRGB(150, 104, 245), bg = Color3.fromRGB(10, 9, 18), txt = Color3.fromRGB(232, 230, 244), fx = "Aurora", name = ""}
local function toC3(c)
if typeof(c) == "Color3" then return c end
if type(c) == "string" then local ok, r = pcall(Color3.fromHex, c); if ok then return r end end
end
local function clampBg(c) local h, sa, v = c:ToHSV(); return Color3.fromHSV(h, sa, math.min(v, 0.12)) end
local function clampTx(c) local h, sa, v = c:ToHSV(); return Color3.fromHSV(h, sa, math.max(v, 0.85)) end
local function register(name)
THEMES[name] = {draft.acc, draft.bg, draft.hi, draft.txt}
if Core.ThemeStyles then Core.ThemeStyles[name] = EFFECTS[draft.fx] or EFFECTS.Aurora end
end
local function persist()
if type(writefile) ~= "function" then return end
local out = {}
for name, fx in pairs(userThemes) do
local pal = THEMES[name]
if pal then out[name] = {acc = pal[1]:ToHex(), bg = pal[2]:ToHex(), hi = pal[3]:ToHex(), txt = pal[4]:ToHex(), fx = fx} end
end
pcall(function() writefile(ROOT .. "/Themes.json", HttpService:JSONEncode(out)) end)
end
local function userList()
