local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local map = {}
for i = 1, 64 do map[chars:sub(i, i)] = i - 1 end
local function dec(s)
local out, n = {}, 0
for i = 1, #s, 4 do
local a, b, c, d = map[s:sub(i, i)], map[s:sub(i + 1, i + 1)], map[s:sub(i + 2, i + 2)], map[s:sub(i + 3, i + 3)]
local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
n = n + 1; out[n] = string.char(floor(v / 65536) % 256)
if c then n = n + 1; out[n] = string.char(floor(v / 256) % 256) end
if d then n = n + 1; out[n] = string.char(v % 256) end
end
return table.concat(out)
end
