-- ---------- helpers ----------
local function hexc(h) return C3(tonumber(h:sub(1, 2), 16), tonumber(h:sub(3, 4), 16), tonumber(h:sub(5, 6), 16)) end
local function c2hex(c) return string.format("%02x%02x%02x", floor(c.R * 255 + 0.5), floor(c.G * 255 + 0.5), floor(c.B * 255 + 0.5)) end
local FXS = {none = 1, shimmer = 1, rainbow = 1, pulse = 1, glow = 1}
local function hx(v, d) if type(v) == "string" and v:match("^%x%x%x%x%x%x$") then return v:lower() end return d end
local function clean(s)
if type(s) ~= "table" then s = {} end
return {c1 = hx(s.c1, "c9162b"), c2 = hx(s.c2, "ff5668"), tx = hx(s.tx, "ffffff"), sc = hx(s.sc, "ffc3ca"), nm = hx(s.nm, "ffffff"),
r = clamp(tonumber(s.r) or 14, 0, 24), a = clamp(tonumber(s.a) or 0, 0, 0.9), rot = clamp(tonumber(s.rot) or 45, 0, 360),
g = s.g ~= false, st = s.st ~= false, sp = s.sp == true, ts = s.ts == true, fx = FXS[s.fx] and s.fx or "none", th = s.th == true}
end
local function resolve(s)
if not s.th then return s end
local o = {}
for k, v in pairs(s) do o[k] = v end
o.c1, o.c2, o.sc = c2hex(T.Accent), c2hex(T.AccentHi), c2hex(T.AccentHi)
return o
end
local function seq(s)
local c1, c2 = hexc(s.c1), hexc(s.c2)
if s.sp then
local k = {}
for i = 0, 5 do
local t0 = i / 6 + (i > 0 and 0.002 or 0)
local t1 = (i + 1) / 6 - (i < 5 and 0.002 or 0)
local c = (i % 2 == 0) and c1 or c2
k[#k + 1] = ColorSequenceKeypoint.new(t0, c); k[#k + 1] = ColorSequenceKeypoint.new(t1, c)
end
k[1] = ColorSequenceKeypoint.new(0, k[1].Value); k[#k] = ColorSequenceKeypoint.new(1, k[#k].Value)
return ColorSequence.new(k)
end
if s.g then return ColorSequence.new(c1, c2) end
return ColorSequence.new(c1)
end
