-- ---------- network ----------
local HS = game:GetService("HttpService")
local connected, ws = false, nil
local function updStat()
local n = 1
for u, t0 in pairs(who) do if u ~= lp.UserId and os.clock() - t0 < 600 then n = n + 1 end end
stat.Text = (connected and "connected" or (reqF and "offline" or "no http support")) .. "  -  " .. n .. " chatting"
dot.BackgroundColor3 = connected and C3(90, 235, 130) or C3(255, 196, 64)
end
local function ingest(raw)
local ok, m = pcall(function() return HS:JSONDecode(raw) end)
if not ok or type(m) ~= "table" or type(m.i) ~= "string" or seen[m.i] then return end
if type(m.u) ~= "number" or type(m.t) ~= "string" or #m.t < 1 then return end
seen[m.i] = true
m.t = m.t:sub(1, 220)
m.n = type(m.n) == "string" and m.n:sub(1, 24) or "Player"
m.u = floor(m.u)
addMsg(m, false)
updStat()
end
local function onEvent(line)
local ok, e = pcall(function() return HS:JSONDecode(line) end)
if ok and type(e) == "table" and e.event == "message" and type(e.message) == "string" then ingest(e.message) end
end
local since = "10m"
local function pollOnce()
if not reqF then return end
local ok, r = pcall(reqF, {Url = "https://ntfy.sh/" .. TOPIC .. "/json?poll=1&since=" .. since, Method = "GET"})
if ok and r and r.StatusCode == 200 then
connected = true
for line in tostring(r.Body):gmatch("[^\n]+") do
local ok2, e = pcall(function() return HS:JSONDecode(line) end)
if ok2 and type(e) == "table" and e.id then since = e.id end
onEvent(line)
end
else connected = false end
updStat()
end
local function startNet()
task.spawn(function()
local WS = (WebSocket and WebSocket.connect) and WebSocket or nil
while gui.Parent and not Core.unloaded do
if WS then
local ok, sock = pcall(function() return WS.connect("wss://ntfy.sh/" .. TOPIC .. "/ws?since=10m") end)
if ok and sock then
ws = sock; connected = true; updStat()
local closed = false
pcall(function() sock.OnMessage:Connect(onEvent) end)
pcall(function() sock.OnClose:Connect(function() closed = true end) end)
local t0 = os.clock()
while gui.Parent and not closed and os.clock() - t0 < 3000 do task.wait(1) end
pcall(function() sock:Close() end)
connected = false; updStat()
else
pollOnce(); task.wait(7)
end
task.wait(3)
else
pollOnce(); task.wait(isOpen and 5 or 9)
end
end
end)
end
local lastSend = 0
local function send()
local text = box.Text:gsub("^%s+", ""):gsub("%s+$", "")
if #text < 1 then return end
if os.clock() - lastSend < 1.5 then notify("Chat", "Slow down a little", 1.5, "warn"); return end
lastSend = os.clock()
text = text:sub(1, 200)
box.Text = ""
local id = HS:GenerateGUID(false)
seen[id] = true
local sendStyle = nil
local shown = text
task.spawn(function()
pcall(function()
local fo = TextService:FilterStringAsync(text, lp.UserId)
shown = fo:GetNonChatStringForBroadcastAsync()
end)
addMsg({u = lp.UserId, n = lp.DisplayName, t = shown, s = mine}, true)
if reqF then
local payload = HS:JSONEncode({i = id, u = lp.UserId, n = lp.DisplayName, t = shown, s = sendStyle})
local ok, r = pcall(reqF, {Url = "https://ntfy.sh/" .. TOPIC, Method = "POST", Headers = {["Content-Type"] = "text/plain"}, Body = payload})
if not ok or not r or (r.StatusCode or 0) >= 300 then notify("Chat", "Message may not have been delivered", 2, "danger") end
else
notify("Chat", "Executor has no http request (local only)", 2, "warn")
end
end)
end
sendB.MouseButton1Click:Connect(function() clickSfx(); send() end)
box.FocusLost:Connect(function(enter) if enter then send() end end)
