do
local CAS = game:GetService("ContextActionService")
local GS = game:GetService("GuiService")
local VIM = nil
pcall(function() VIM = game:GetService("VirtualInputManager") end)
local padOn = false
local cx, cy = 400, 300
local cur = make("Frame", {Name = "PadCursor", BackgroundColor3 = Color3.new(1, 1, 1), AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(16, 16), Visible = false, ZIndex = 1000, BorderSizePixel = 0, Active = false}, gui)
corner(cur, 8); local cst = stroke(cur, T.Accent, 2, 0); onAccent(function() cst.Color = T.Accent end)
local function inset() local ok, v = pcall(function() return GS:GetGuiInset() end); return ok and v or Vector2.new(0, 36) end
local function vmove() if VIM then pcall(function() local i = inset(); VIM:SendMouseMoveEvent(cx, cy + i.Y, game) end) end end
local function vbtn(btn, down) if VIM then pcall(function() local i = inset(); VIM:SendMouseButtonEvent(cx, cy + i.Y, btn, down, game, 0) end) end end
local function vwheel(dir) if VIM then pcall(function() local i = inset(); VIM:SendMouseWheelEvent(cx, cy + i.Y, dir > 0, game) end) end end
local function refresh()
local usePad = UIS:GetLastInputType().Name:find("Gamepad") ~= nil
padOn = usePad and isOpen
cur.Visible = padOn
if padOn then
local vp = workspace.CurrentCamera.ViewportSize
if cx == 400 and cy == 300 then cx, cy = vp.X / 2, vp.Y / 2 end
cur.Position = UDim2.fromOffset(cx, cy)
end
end
track(UIS.LastInputTypeChanged:Connect(refresh))
local lastOpen = false
local function onAction(name, state, input)
if not (padOn and isOpen) then return Enum.ContextActionResult.Pass end
local k = input.KeyCode
if k == Enum.KeyCode.ButtonA then
if state == Enum.UserInputState.Begin then vmove(); vbtn(0, true) elseif state == Enum.UserInputState.End then vbtn(0, false) end
elseif k == Enum.KeyCode.ButtonX then
if state == Enum.UserInputState.Begin then vmove(); vbtn(1, true) elseif state == Enum.UserInputState.End then vbtn(1, false) end
elseif k == Enum.KeyCode.ButtonB then
if state == Enum.UserInputState.Begin then setOpen(false) end
elseif k == Enum.KeyCode.DPadUp then if state == Enum.UserInputState.Begin then vwheel(1) end
elseif k == Enum.KeyCode.DPadDown then if state == Enum.UserInputState.Begin then vwheel(-1) end
end
return Enum.ContextActionResult.Sink
end
pcall(function()
CAS:BindActionAtPriority("AspenPad", onAction, false, 3000, Enum.KeyCode.ButtonA, Enum.KeyCode.ButtonB, Enum.KeyCode.ButtonX, Enum.KeyCode.ButtonY, Enum.KeyCode.DPadUp, Enum.KeyCode.DPadDown, Enum.KeyCode.DPadLeft, Enum.KeyCode.DPadRight, Enum.KeyCode.ButtonL1, Enum.KeyCode.ButtonR1)
end)
do
local function cycleMain(step)
local idx = table.find(mains, activeMain) or 1
local nxt = mains[((idx - 1 + step) % #mains) + 1]
if nxt then pcall(selectMain, nxt) end
end
local function cycleSubTab(step)
local m = activeMain
local subs = m and m.subs
if type(subs) ~= "table" or #subs == 0 then return end
local idx = table.find(subs, activeSub) or 1
pcall(selectSub, m, subs[((idx - 1 + step) % #subs) + 1])
end
local function onTabs(name, state, input)
if not (padOn and isOpen) then return Enum.ContextActionResult.Pass end
if state == Enum.UserInputState.Begin then
local k = input.KeyCode
if k == Enum.KeyCode.ButtonL1 then cycleMain(-1) elseif k == Enum.KeyCode.ButtonR1 then cycleMain(1)
elseif k == Enum.KeyCode.DPadLeft then cycleSubTab(-1) elseif k == Enum.KeyCode.DPadRight then cycleSubTab(1) end
end
return Enum.ContextActionResult.Sink
end
pcall(function() CAS:BindActionAtPriority("AspenPadTabs", onTabs, false, 3000, Enum.KeyCode.ButtonL1, Enum.KeyCode.ButtonR1, Enum.KeyCode.DPadLeft, Enum.KeyCode.DPadRight) end)
end
track(UIS.InputBegan:Connect(function(i)
if i.KeyCode == Enum.KeyCode.ButtonSelect then setOpen(not isOpen); task.defer(refresh) end
end))
local acc = 0
track(RunService.RenderStepped:Connect(function(dt)
if isOpen ~= lastOpen then lastOpen = isOpen; refresh() end
if not padOn then return end
local lx, ly, ry = 0, 0, 0
local okS, st = pcall(function() return UIS:GetGamepadState(Enum.UserInputType.Gamepad1) end)
if okS and st then
for _, o in ipairs(st) do
if o.KeyCode == Enum.KeyCode.Thumbstick1 then lx, ly = o.Position.X, -o.Position.Y
elseif o.KeyCode == Enum.KeyCode.Thumbstick2 then ry = o.Position.Y end
end
end
if math.abs(lx) < 0.15 then lx = 0 end
if math.abs(ly) < 0.15 then ly = 0 end
if math.abs(ry) < 0.25 then ry = 0 end
if lx ~= 0 or ly ~= 0 then
local vp = workspace.CurrentCamera.ViewportSize
local sp = 700 * dt
cx = math.clamp(cx + lx * math.abs(lx) * sp * 1.4, 0, vp.X)
cy = math.clamp(cy + ly * math.abs(ly) * sp * 1.4, 0, vp.Y)
cur.Position = UDim2.fromOffset(cx, cy)
vmove()
end
if ry ~= 0 then
acc = acc + dt
if acc > 0.06 then acc = 0; vwheel(ry) end
end
end))
if UIS.TouchEnabled and VIM then
track(UIS.TouchLongPress:Connect(function(pos, state)
if state == Enum.UserInputState.Begin and pos and pos[1] and isOpen then
local i = inset()
