VIM:SendMouseButtonEvent(pos[1].X, pos[1].Y + i.Y, 1, true, game, 0)
VIM:SendMouseButtonEvent(pos[1].X, pos[1].Y + i.Y, 1, false, game, 0)
end)
end
end))
end
