do
local function splitPage(pg)
if true then return end
local kids, lay = {}, nil
for _, c in ipairs(pg:GetChildren()) do
if c:IsA("UIListLayout") then lay = c
elseif c:IsA("GuiObject") then
if c:GetAttribute("SecId") == nil then return end
kids[#kids + 1] = c
end
end
if not lay or #kids < 8 then return end
table.sort(kids, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
local blocks, cur, curId = {}, nil, nil
for _, c in ipairs(kids) do
local sid = c:GetAttribute("SecId")
if not cur or sid ~= curId then cur = {h = 0, items = {}}; blocks[#blocks + 1] = cur; curId = sid end
cur.items[#cur.items + 1] = c
if not c:GetAttribute("Hid") then cur.h = cur.h + (c.Size.Y.Offset + 9) end
end
local total = 0
for _, b in ipairs(blocks) do total = total + (b.h) end
if #blocks < 2 or total < 300 then return end
local best, bestD, acc = 1, math.huge, 0
for k = 1, #blocks - 1 do
acc = acc + (blocks[k].h)
local d = math.abs(acc * 2 - total)
if d < bestD then best, bestD = k, d end
end
local ha = lay.HorizontalAlignment
lay.FillDirection = Enum.FillDirection.Horizontal
lay.HorizontalAlignment = Enum.HorizontalAlignment.Left
lay.VerticalAlignment = Enum.VerticalAlignment.Top
lay.Padding = UDim.new(0, 14)
local function newCol(order)
local col = make("Frame", {Name = "Col" .. order, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(0.5, -7, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, ZIndex = 2}, pg)
col:SetAttribute("ColFrame", true)
make("UIListLayout", {Padding = UDim.new(0, 9), SortOrder = Enum.SortOrder.LayoutOrder, HorizontalAlignment = ha}, col)
return col
end
local c1, c2 = newCol(1), newCol(2)
for k, b in ipairs(blocks) do
for _, it in ipairs(b.items) do it.Parent = (k <= best) and c1 or c2 end
end
pg:SetAttribute("Split", true)
pg.ChildAdded:Connect(function(ch)
task.defer(function()
if ch.Parent == pg and ch:IsA("GuiObject") and not ch:GetAttribute("ColFrame") then
ch.Parent = (c1.AbsoluteSize.Y <= c2.AbsoluteSize.Y) and c1 or c2
end
end)
end)
end
