local function mk(class, props, parent)
local o = Instance.new(class)
for k, v in pairs(props) do o[k] = v end
o.Parent = parent
return o
end
local function tw(o, t, p, st, d)
local x = TS:Create(o, TweenInfo.new(t, st or Enum.EasingStyle.Quint, d or Enum.EasingDirection.Out), p)
x:Play()
return x
end
